window.__D("text/maamarim-melukatim/c014",{"p":[[1500380034,"<h3>בס\"ד. ש\"פ אחרי, מבה\"ח אייר ה'תשל\"ג<sup data-n=\"1851\">*</sup></h3>\n<b>כל</b> ישראל יש להם חלק לעולם הבא<sup data-n=\"1852\">1</sup>, דפירוש<sup data-n=\"1853\">2</sup> עולם הבא במשנה זו הוא עולם התחי', וכדמוכח מהמשך המשנה ואלו שאין להם חלק לעולם הבא האומר אין תחיית המתים מן התורה, שהטעם על זה הוא כדאיתא בגמרא<sup data-n=\"1854\">3</sup> הוא כפר בתחיית המתים לפיכך לא יהי' לו חלק בתחיית המתים כו' מדה כנגד מדה. וכל ישראל יש להם חלק לעולם הבא, דבגן עדן כתיב<sup data-n=\"1855\">4</sup> מי יעלה בהר הוי' גו' נקי כפים ובר לבב גו', שישנם כמה תנאים בכדי לעלות לג\"ע, אפילו לג\"ע התחתון<sup data-n=\"1856\">5</sup>, משא\"כ בנוגע עולם התחי' כל ישראל יש להם חלק לעולם הבא<sup data-n=\"1857\">6</sup>. וצריך להבין, הרי הגילוי שיהי' בעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע<sup data-n=\"1858\">7</sup>, גם מהגילוי שבג\"ע העליון, גם מדרגא הכי נעלית שבג\"ע [וכמובן גם מהענין דתחיית המתים עצמו, דיקומו לתחי' כל ישראל, גם הנשמות שנמצאים בג\"ע כמה אלפים שנה, וג' פעמים בכל יום הם מתעלים לדרגא נעלית יותר, ואעפ\"כ לע\"ל יתלבשו בגופים, כי הגילוי דעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע, גם מדרגא הכי נעלית דג\"ע<sup data-n=\"1859\">8</sup>], ואעפ\"כ בכדי לזכות להגילוי דג\"ע צ\"ל כמה תנאים, והגילוי דעולם התחי' יהי' לכל ישראל.\nב) <b>ויובן</b> זה בהקדים הביאור דענין זה שהגילוי דעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע. דלכאורה, כיון שג\"ע הוא עולם הנשמות (נשמות בלא גופים), ובעולם התחי' יהיו נשמות בגופים, מהו הביאור בזה שבעולם התחי', כשהנשמה תהי' מלובשת בגוף גשמי, יהי' גילוי נעלה יותר מבג\"ע. והגם שלע\"ל יהי' הגוף בתכלית הזיכוך, וכמו גופו של אדה\"ר (יציר<sup data-n=\"1860\">9</sup> כפיו של הקב\"ה)<sup data-n=\"1861\">10</sup>, שהי'מכהה גלגל חמה<sup data-n=\"1862\">11</sup>, ויתירה מזו, שלע\"ל יהי' הגוף בתכלית השלימות עוד יותר מכמו של אדה\"ר<sup data-n=\"1863\">12</sup>, הרי זהו לכאורה ביאור רק על זה שלע\"ל יהיו הנשמות המלובשים בגופים כלים לקבל גילוי נעלה יותר מהגילוי שמתגלה עכשיו לנשמות בלא גופים. אבל אין בזה ביאור על זה שהגילוי דלע\"ל יהי' דוקא לנשמות בגופים. דהגם שגם לע\"ל, כשהגוף יהי' בתכלית השלימות, יהי' גוף גשמי, דההגבלות שבדבר גשמי הם יותר מההגבלות שבדבר רוחני<sup data-n=\"1864\">13</sup>, וכמו ההגבלה דזמן ומקום שהיא (בעיקר) בדברים גשמיים<sup data-n=\"1865\">14</sup>, ואעפ\"כ, בכדי שהנשמה תוכל לקבל הגילוי דלע\"ל, הוא דוקא ע\"י שמתלבשת בגוף גשמי. והיינו, שמהחילוקים בין הגילוי דג\"ע והגילוי דלע\"ל הוא שבכדי לקבל הגילוי דג\"ע הוא ע\"י ההפשטה מדברים הגשמיים. שקודם עליית הנשמה לג\"ע צריך להיות תחלה הטבילה בנהר דינור לשכוח חיזו דהאי עלמא<sup data-n=\"1866\">15</sup>. [ועד\"ז הוא בהעליות שבג\"ע עצמו, שבכל עלי' צריך תחלה לשכוח ההשגה והתענוג דמדריגה התחתונה<sup data-n=\"1866\">15</sup>]. ובכדי לקבל הגילוי דלע\"ל הוא ע\"י שמתלבשת בגוף גשמי.\nג) <b>והנה</b> כתיב<sup data-n=\"1867\">16</sup> זאת התורה אדם, שהתורה היא בדוגמת אדם. דכמו שהאדם מורכב מגוף ונשמה, עד\"ז הוא בתורה שיש בה גוף ונשמה. ובכללות הוא החילוק בין תורה למצוות<sup data-n=\"1868\">17</sup>. דרמ\"ח מצוות הם רמ\"ח אברים דמלכא<sup data-n=\"1869\">18</sup>, ע\"ד אברי הגוף, והתורה היא הדם הוא הנפש<sup data-n=\"1870\">19</sup> שממשכת חיות בהאברים דהמצוות<sup data-n=\"1871\">20</sup>. וזהו שהמצוות הם בזמן ומקום והתורה היא למעלה מזמן ומקום [שלכן כל העוסק בתורת עולה כאילו הקריב עולה<sup data-n=\"1872\">21</sup>, גם כשאינו בזמן ומקום ההקרבה]<sup data-n=\"1871\">20</sup>, כי הגוף שהוא גשמי הוא מוגדר בזמן ומקום, והנשמה שהיא רוחנית היא למעלה מזמן ומקום. וכמו שהוא בתורה ומצוות עצמם, עד\"ז הוא בנוגע לשייכותם דהתורהוהמצוות להאדם הלומד ומקיים המצוות. דלימוד התורה שייך בעיקר להנשמה וקיום המצוות להגוף<sup data-n=\"1873\">22</sup>.\n<b>והנה</b> ידוע<sup data-n=\"1874\">23</sup> דזה שהתורה היא למעלה מהמצוות הוא כמו שהתומ\"צ נמשכו בגילוי, אבל בשרשם, המצוות הם נעלים יותר. דהתורה היא חכמתו ית' והמצוות הם רצונו ית', רצון שלמעלה מחכמה<sup data-n=\"1875\">24</sup>. ויתירה מזו, דגם לאחרי שהתומ\"צ באו בהמשכה ניכר בגילוי מעלת המצוות, דהתורה היא פירוש וביאור המצוות<sup data-n=\"1876\">25</sup>.\n<b>ומזה</b> מובן, שעד\"ז הוא בנשמה וגוף שבאדם [שהם בדוגמת תורה ומצוות], דהגם שחיות הגוף הוא מהנשמה, שורש הגוף הוא למעלה משורש הנשמה [וכמבואר במק\"א<sup data-n=\"1877\">26</sup>, שהאהבה וההתקשרות דהקב\"ה לישראל מצד נשמתם, בנים אתם להוי' אלקיכם<sup data-n=\"1878\">27</sup>, היא כמו אהבה <i>טבעית</i> כביכול, ע\"ד אהבת אב לבנו. היינו, ששורש אהבה זו הוא ממדריגה ששייכת שם תפיסת מקום דהנאהב, ואינה מעצמותו ממש. משא\"כ האהבה וההתקשרות דהקב\"ה לישראל מצד הגוף שלהם, היא (לא מצד מעלת הגוף, גם לא המעלה דבן, מעלה עצמית, אלא) מצד זה שהקב\"ה בחר בהגוף דישראל<sup data-n=\"1879\">28</sup>, בבחירה חפשית, שבחירה זו היא מעצמותו]. וזה גופא שהנשמה נמשכת להחיות את הגוף הוא מפני העילוי של הגוף מצד שרשו (בדוגמת זה שהתורה מפרשת ומבארת המצוות, מפני שהמצוות הם למעלה מהתורה).\nד) <b>והנה</b> ידוע<sup data-n=\"1880\">29</sup> דזה שבהחיוב דקיום המצוות כל ישראל הם שוים ובהחיוב דלימוד התורה יש כו\"כ מדריגות, דביושבי אהל שיש להם פנאי החיוב דוהגית<sup data-n=\"1881\">30</sup> בו יומם ולילה הוא כפשוטו, ובעלי עסקים יוצאים ידי חובתם בפרק אחד שחרית ופרק אחד ערבית<sup data-n=\"1882\">31</sup>, הוא, כי המצוות הם רצון העליון (כנ\"ל), ורצון הוא למעלה מהתחלקות, והתורה היא חכמתו ית', ובחכמה יש התחלקות.\n<b>ויש</b> לומר, שעד\"ז הוא בנוגע ללימוד התורה וקיום המצוות בפועל, דזה שקיום המצוות הוא בכל ישראל, דאפילו פושעי ישראל מלאים מצוות כרימון<sup data-n=\"1883\">32</sup>, משא\"כ בלימוד התורה, הוא, כי אפשר להיות איזה חסרון בישראל רק בהגילויים<sup data-n=\"1884\">33</sup>,וכיון שהמצוות הם רצון העליון ושייכים להגוף שבו הוא בחירת העצמות, לכן ענין זה (בקיום המצוות) הוא בכל ישראל.\nה) <b>וזהו</b><sup data-n=\"1885\">34</sup> כל ישראל יש להם חלק לעולם הבא, דהגם שהגילוי דעולם הבא (עולם התחי') הוא נעלה יותר מהגילוי דג\"ע ומ\"מ גילוי זה יהי' לכל ישראל, כי בג\"ע הוא הגילוי דהתורה שלומדים בעוה\"ז, ולע\"ל בעולם התחי' יהי' הגילוי דהמצוות שמקיימים עכשיו. וכיון שקיום המצוות הוא בכל ישראל כנ\"ל, לכן, כל ישראל יש להם חלק לעולם הבא. וזהו שהגילוי דעולם התחי' יהי' לנשמות בגופים דוקא, כי קיום המצוות שייך בעיקר להגוף, כנ\"ל. ויש לומר, דזה שהגילוי דעולם התחי' יהי' גם להנשמות (שיתלבשו אז בהגוף), הוא ע\"ד מאמר רז\"ל<sup data-n=\"1886\">35</sup> גדול תלמוד שמביא לידי מעשה, דע\"י שהתלמוד מביא לידי מעשה נעשה גדלות בתלמוד. [וע\"ד המבואר בהמשך תרס\"ו<sup data-n=\"1887\">36</sup>, דכאשר הלימוד הוא בנוגע לפסק דין בפועל ממש, אז הוא מייגע עצמו יותר ובא לעמקות יתירה בהענין].\n<b>ועפ\"ז</b> יש לומר, שבמעלת התורה דלע\"ל, תורתו של משיח, שני ענינים. זה שאז יהי' הגילוי דשלימות התורה מצד עצמה, והעילוי שיהי' אז בתורה ע\"י העילוי דמצוות. ועד\"ז הוא בנוגע לנשמה, דנוסף לזה שאז יתגלה שורש הנשמות עצמם, תקבל הנשמה גם הגילוי דמעלת הגוף (בחירת העצמות בהגוף).\n<b>ויהי</b> רצון, שע\"י מעשינו ועבודתינו<sup data-n=\"1888\">37</sup>, ובפרט על ידי העבודה דיפוצו מעיינותיך חוצה<sup data-n=\"1889\">38</sup>, נזכה ללימוד תורתו של משיח, מפיו של משיח, בקרוב ממש.\n**********",[["1851","*","יצא לאור \"בסמיכות לש\"ק פ' תרומה, וא\"ו אדר – יום היאָרצייט של הרה\"ג הרה\"ח ר' שמריהו ב\"ר מנחם מענדל ע\"ה גורארי', יו\"ר ועד הפועל מרכז הישיבות תומכי תמימים ליובאוויטש, חדב\"נ כ\"ק אדמו\"ר מהוריי\"צ נ\"ע, וגיסו של – יבלחט\"א – כ\"ק אדמו\"ר שליט\"א . . <i>זיין אדר</i>,<i> יום א' פ' ואתה תצוה</i>,<i> שנת ה'תש\"נ</i>\"."],["1852","1","משנה סנהדרין ר\"פ חלק."],["1853","2","רע\"ב (ועוד) לסנהדרין שם. מדרש שמואל על מס' אבות בתחלתו."],["1854","3","סנהדרין שם (צ, א)."],["1855","4","תהלים כד, ג-ד."],["1856","5","כ\"מ בד\"ה כי ישאלך שבהערה הבאה. ולהעיר מהמשך תער\"ב ח\"ב ר\"פ שעט (ס\"ע תשעט).\nולהעיר מחגיגה (טו, ב) דלולי תפלת ר' מאיר לא הי' אחר נכנס לג\"ע (לג\"ע התחתון)."],["1857","6","ד\"ה כי ישאלך עטר\"ת (סה\"מ עטר\"ת ס\"ע שנא ואילך), ה'ש\"ת (סה\"מ ה'ש\"ת ס\"ע 44 ואילך)."],["1858","7","כדעת הרמב\"ן בשער הגמול בסופו (בהוצאת שאוועל – ע' שט). וכ\"ה ההכרעה בתורת החסידות – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. דרושים לשבת שובה סה, סע\"ד. סהמ\"צ להצ\"צ מצות ציצית (דרמ\"צ יד, ב). ובאוה\"ת חוקת (ס\"ע תתט. שם כרך ה ע' א'תרלז): ואדה\"ז בהדרושים מזכיר רק דעת הרמב\"ן."],["1859","8","ד\"ה כי ישאלך תרנ\"ד (סה\"מ תרנ\"ד ע' רכ). המשך תער\"ב שם (ריש ע' תשפ). סה\"מ קונטרסים ח\"ב תיב, א. ועוד."],["1860","9","ראה ב\"ר פכ\"ד, ה. קה\"ר פ\"ג, יא (ב)."],["1861","10","ראה בארוכה סה\"מ עטר\"ת ע' תטו; ה'תשי\"א ע' 209, דכיון שהווייתו של הגוף יהי' <i>מהקב\"ה</i> ע\"י טל תחי', לכן יהי' כמו גופו של אדה\"ר יציר כפיו של הקב\"ה."],["1862","11","ויק\"ר פ\"כ, ב. מדרש משלי בסופו. וראה תקו\"ז בהקדמה (י, ב). ועיין ב\"ב נח, א.\nובסה\"מ עטר\"ת ותשי\"א שם \"שהי' גופו מזוכך וטהור לגמרי כמו אור . . שהי' הגוף כחומר אל הצורה שהיא הנשמה שהיו בערך זל\"ז\"."],["1863","12","ראה סה\"מ עטר\"ת ותשי\"א שם."],["1864","13","ולהעיר גם מהמובא לעיל הערה 11, דמעלת גופו של אדה\"ר (ועד\"ז הגוף שיהי' לע\"ל) שהי' \"כחומר אל הצורה\", דמזה מובן שגם בחומר מזוכך בתכלית, הצורה היא נעלית יותר מהחומר."],["1865","14","וזה שגם בדברים רוחניים יש מקום וזמן רוחני, הוא לפי שדברים אלו הם \"גשמיים\" בערך הרוחניות ממש. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, סע\"ב</a>) \"לא שייך כלל בחי' מקום ברוחניות\", אף שמדבר שם במקום רוחני."],["1866","15","זח\"א רא, א. וראה ד\"ה כי ישאלך עטר\"ת פ\"א (סה\"מ שם ע' שנב), ה'ש\"ת פ\"א (סה\"מ שם ע' 45). וראה ד\"ה להבין ענין תחיית המתים ה'תשמ\"ו ס\"ה (לקמן ע' רכד). וש\"נ."],["1867","16","חוקת יט, יד. וראה סה\"מ ה'תש\"א ע' 99."],["1868","17","בסה\"מ ה'תש\"א שם (וראה גם זח\"ג קנב, א) מדובר בענין הגוף ונפש שבתורה עצמה. וי\"ל, דכיון שהענינים כלולים זה מזה, לכן גם בתורה יש גוף, ועד\"ז במצוות, שיש בהם נפש, דכוונת המצוות היא הנפש שבהם."],["1869","18","ראה תקו\"ז ת\"ל (עד, סע\"א). הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. שם רפכ\"ג. ועוד."],["1870","19","ראה יב, כג."],["1871","20","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>."],["1872","21","מנחות בסופה. שו\"ע אדה\"ז או\"ח מהדו\"ת סוף ס\"א. מהדו\"ק שם סי\"א. הל' ת\"ת פ\"ב סי\"א. וראה לקו\"ש חי\"ח ע' 413 הערה 25 ובשוה\"ג שם."],["1873","22","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה (מד, סע\"א</a> ואילך), <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">ושם פל\"ז (מט, א</a>-ב). ובכ\"מ."],["1874","23","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380196\" data-slug=\"likkutei-torah\" data-id=\"4001380196\">לקו\"ת אחרי כח, א</a>. ובכ\"מ. ולהעיר שב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380191\" data-slug=\"likkutei-torah\" data-id=\"4001380191\">לקו\"ת שם לפנ\"ז (כו, ד</a> ואילך) מבואר המעלה דתורה לגבי מצוות (ומובא שם ה<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380420\" data-slug=\"likkutei-torah\" data-id=\"4001380420\">לקו\"ת במדבר</a> שבהערה 20), ואעפ\"כ מבאר שם (כח, א) שבשרשם המצוות הם גבוהים יותר."],["1875","24","סהמ\"צ להצ\"צ טו, ב. ובכ\"מ."],["1876","25","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380191\" data-slug=\"likkutei-torah\" data-id=\"4001380191\">לקו\"ת אחרי שם כו, ד</a>."],["1877","26","ראה בארוכה לקמן ח\"ד ע' ער."],["1878","27","ראה יד, א. וב<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a> שזה קאי על הנשמה."],["1879","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"א</a> ואילך). וראה ספר השיחות תורת שלום ע' 120."],["1880","29","המשך תער\"ב ח\"א פ\"ד (ע' ח). פנ\"ב (ע' צג)."],["1881","30","לשון הכתוב – יהושע א, ח."],["1882","31","מנחות צט, ב. הל' ת\"ת לאדה\"ז פ\"ג ה\"ד."],["1883","32","חגיגה בסופה."],["1884","33","ואף שגם שורש הנשמה הוא בהעצמות – יש לומר, דכיון שאהבת הקב\"ה לישראל היא כמו אהבה טבעית (כנ\"ל בפנים), לכן, לגבי הענין דבחירת העצמות בהגוף, הוא דוגמת ענין הגילויים. ועצ\"ע."],["1885","34","בהבא לקמן, ראה בארוכה ד\"ה לה\"ע תחיית המתים דלעיל הערה 15 ס\"ב (לקמן ע' רכב). <i>וש\"נ</i>."],["1886","35","קידושין מ, ב. ב\"ק יז, א."],["1887","36","ע' שצ ואילך."],["1888","37","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1889","38","שעי\"ז אתי מר דא מלכא משיחא – כמ\"ש באגה\"ק המפורסמת של הבעש\"ט, נדפסה גם בכתר שם טוב בתחלתו."]]],[1500380035,"<h3>בס\"ד. ש\"פ אחרי, מבה\"ח אייר ה'תשמ\"ו<sup data-n=\"1890\">*</sup></h3>\n<b>להבין</b> ענין תחיית המתים, הנה איתא במשנה<sup data-n=\"1891\">1</sup> כל ישראל יש להם חלק לעולם הבא, וידוע<sup data-n=\"1892\">2</sup> דפירוש עולם הבא במשנה זו הוא עולם התחי', וכדמוכח מהמשך המשנה ואלו שאין להם חלק לעולם הבא האומר אין תחיית המתים מן התורה, שהטעם על זה הוא כדאיתא בגמרא<sup data-n=\"1893\">3</sup> הוא כפר בתחיית המתים לפיכך לא יהי' לו חלק בתחיית המתים כו' מדה כנגד מדה. וזהו כל ישראל יש להם חלק לעולם הבא, דבגן עדן [שלפעמים נקרא ג\"כ בשם עולם הבא<sup data-n=\"1894\">4</sup>, אף שישנו גם עכשיו<sup data-n=\"1895\">5</sup>, לפי שבא <i>לאדם</i> לאחרי עבודתו בעולם הזה<sup data-n=\"1896\">6</sup>] כתיב<sup data-n=\"1897\">7</sup> מי יעלה בהר הוי' גו' נקי כפים ובר לבב גו', שישנם כמה תנאים בכדי לזכות לג\"ע<sup data-n=\"1898\">8</sup>, משא\"כ בנוגע לעולם התחי' (שבו הוא עיקר התואר עולם הבא) אמרו כל ישראל יש להם חלק לעולם הבא<sup data-n=\"1899\">9</sup>.\n<b>וצריך</b> להבין, הרי ידוע שהגילוי שיהי' בעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע, וכמובן גם מזה שהג\"ע ישנו גם עכשיו משא\"כ הגילוי דעולם התחי' יהי' רק לע\"ל, ויתירה מזו שהגילוי דעולם התחי' יהי' (גם) לאחרי ימות המשיח, שמזה מובן שהגילוי שיהי' אז הוא למעלה גם מהגילוי שיהי' בימות המשיח [דזהו מה שאומרים<sup data-n=\"1900\">10</sup> אין ערוך לך כו' בעולם הזה ואין זולתך כו' לחיי העולם הבא אפס בלתך כו' לימות המשיח ואין דומה כו' לתחיית המתים, שד' ענינים אלו הם בסדר דמלמטה למעלה, שהגילוי דעולם הבא (שהכוונה בעוה\"ב כאן היא לג\"ע<sup data-n=\"1901\">11</sup>) הוא למעלה יותר מהגילוי שיכול להיות בעולם הזה, ולמעלה יותר הוא הגילוי דימות המשיח, ולאח\"ז הוא הגילוי דתחיית המתים שהוא למעלה יותר גם מהגילוי דימות המשיח], ואעפ\"כ בכדי לזכות להגילוי דג\"ע צריך כמה תנאים, והגילוי דתחיית המתים שהוא למעלה יותר מהגילוי דג\"ע יהי' לכל ישראל.ב) <b>ונקודת</b> אחד הביאורים בזה הוא, כמבואר בכמה דרושים<sup data-n=\"1902\">12</sup>, שהשכר דג\"ע הוא על עסק התורה, והשכר דתחיית המתים הוא על קיום המצוות. וזהו שג\"ע הוא עולם הנשמות (נשמות בלא גופים) ובעולם התחי' יהיו נשמות בגופים, כי עסק התורה שייך בעיקר להנשמה וקיום המצוות להגוף<sup data-n=\"1903\">13</sup>. וכיון שקיום המצוות הוא בכל ישראל, דאפילו פושעי ישראל מלאים מצוות כרמון<sup data-n=\"1904\">14</sup>, לכן כל ישראל יש להם חלק לעולם הבא. ויש לומר, דזהו גם מה שממשיך במשנה שנאמר<sup data-n=\"1905\">15</sup> ועמך כולם צדיקים לעולם יירשו ארץ כו', דיש לומר, שכוונת המשנה בשנאמר כו' היא לא רק להביא ראי' על זה שכל ישראל יש להם חלק לעולם הבא אלא גם לבאר הטעם על זה. דמי שמקיים מצוות נק' בשם צדיק [דכל המצוות נק' בשם צדקה<sup data-n=\"1906\">16</sup>, ומקיימי המצוות נק' בשם צדיקים<sup data-n=\"1907\">17</sup>], וכיון שועמך כולם צדיקים, שכל ישראל (אפילו הפושעים שבהם) מקיימים מצוות, ויתירה מזו שהם מלאים מצוות, דהמצוות שמקיימים ממלאים את כל מציאותם, לכן לעולם יירשו ארץ, ארץ החיים<sup data-n=\"1908\">18</sup> שקאי על חיי עולם הבא. אמנם, עפ\"ז צריך להבין מה שמביא במשנה גם המשך הכתוב נצר מטעי מעשה ידי להתפאר, והרי זה שישראל הם נצר מטעי ומעשה ידיו של הקב\"ה הוא מצד עצם מציאותם (עוד לפני שמקיימים מצוות), ובהמשנה דכל ישראל יש להם חלק לעולם הבא מביא גם סיום הכתוב נצר מטעי מעשה ידי להתפאר, דמזה משמע, דזה שכל ישראל יש להם חלק לעולם הבא הוא (גם) מצד המעלה שבהם מצד עצמם.\nג) <b>ויש</b> לומר, שבהגילוי שיהי' בתחיית המתים שני ענינים. השכר על העבודה דקיום המצוות (ועמך כולם צדיקים), שההמשכות שהמשיכו ישראל ע\"י המצוות שקיימו עכשיו תהי' אז בגילוי, ועי\"ז יתעלו (אח\"כ<sup data-n=\"1909\">19</sup>) למדריגה נעלית יותר, שתתגלה מעלתן של ישראל מצד עצמם, שהם נצר מטעי מעשה ידי להתפאר, שהוא למעלה יותר גם מההמשכה שנמשכת ע\"י קיום המצוות. ויש להוסיף, שעיקר החידוש והעילוי דתחיית המתים הוא שאז תתגלה מעלת ישראל עצמם. דגילוי ההמשכה שנמשכת ע\"י המצוות, יהי' גם בימות המשיח (קודם זמן התחי'), וכמבואר בתניא<sup data-n=\"1910\">20</sup> שע\"י מעשינו ועבודתינו עכשיו ממשיכים אוא\"ס למטה והגילוי דהמשכה זו יהי' בימות המשיח ובתחיית המתים (אלא שבתחיית המתים, גם הגילוי דהמשכה זו יהי' באופןנעלה יותר<sup data-n=\"1911\">21</sup>), ועיקר החידוש והעילוי דתחיית המתים הוא שאז יתגלה השורש דישראל כמו שהם מושרשים בהעצמות<sup data-n=\"1912\">22</sup>.\n<b>ויש</b> לומר, דמ\"ש בכמה דרושים (הובא לעיל) שבתחיית המתים יהי' גילוי ההמשכה שנמשכת ע\"י קיום המצוות, הוא, כי שם מדובר בהשכר לישראל שיהי' בעולם הבא עבור עבודתם בתומ\"צ בעולם הזה<sup data-n=\"1913\">23</sup>, ושלימות השכר הוא שיאיר להם בגילוי ההמשכה שהמשיכו ע\"י קיום המצוות. ולכן מבואר בדרושים אלו ששכר הנשמות בג\"ע הוא שמשיגים האלקות דהתורה שלמדו בעוה\"ז, דתורה היא חכמתו של הקב\"ה, אור הממלא, והשכר דתחיית המתים הוא שאז יראו עינינו גילוי אלקותו הבלתי בע\"ג<sup data-n=\"1914\">24</sup> שנמשך ע\"י קיום המצוות, רצונו ית' (שלמעלה מחכמתו), אור הסובב. אמנם, כל זה הוא השכר לישראל עבור עבודתם בתומ\"צ<sup data-n=\"1915\">25</sup>. ועיקר החידוש והעילוי שיהי' בעולם הבא הוא הגילוי דמעלת ישראל עצמם, נצר מטעי מעשה ידי להתפאר.\nד) <b>וביאור</b> הענין (דג' מדריגות אלו, ג\"ע וב' הדרגות בתחיית המתים), דאיתא בגמרא<sup data-n=\"1916\">26</sup> כל הנביאים כולן לא נתנבאו אלא לימות המשיח אבל לעולם הבא עין<sup data-n=\"1917\">27</sup> לא ראתה אלקים זולתך. ובהמשך הענין שם מאי עין לא ראתה כו' זה עדן שלא שלטה בו עין כל ברי', שמא תאמר אדה\"ר היכן הי' בגן כו', גן לחוד ועדן לחוד. והיינו שהחידוש והעילוי דעולם הבא (תחיית המתים) לגבי ימות המשיח הוא שאז יהי' הגילוי דבחינת עדן, עין לא ראתה. ומזה מובן, דזה שבעולם הבא יהי' גילוי ההמשכה שנמשכה ע\"י קיום המצוות, מכיון שגילוי זה יהי' (בכללות) גם בימות המשיח, אין זה אמיתית הענין דעוה\"ב. ועיקר הענין דעוה\"ב הוא הגילוי דבחינת עדן, והוא התענוג העצמי שמתענג בישראל, שלמעלה גם מהתענוג שמתענג בתומ\"צ<sup data-n=\"1918\">28</sup>. ולהעיר, שבכ\"מ<sup data-n=\"1919\">29</sup> מבואר החילוק בין תורה למצוות, דבתורה שהיא חכמתו ית' מלובש הארת התענוג ובמצוות שהם רצונו ית' מלובש עצמות התענוג (בחינת עדן). וזהו שבג\"ע כתיב<sup data-n=\"1920\">30</sup> ונהר יוצא מעדן להשקות את הגן, שהתענוגשנמשך לנשמות בג\"ע (בהשגת התורה) הוא רק המשכה מצומצמת מבחינת עדן שנמשכת ע\"י הנהר שמפסיק בין עדן לגן, משא\"כ בעוה\"ב שהוא מתן שכרן של מצוות הוא הגילוי דבחינת עדן עצמו. ויש לומר, שזהו בכללות. אבל בפרטיות, כיון שהגילוי דהמצוות יהי' (בכללות) גם בימות המשיח ואעפ\"כ אמרו שבימות המשיח לא יהי' גילוי דבחינת עין לא ראתה (בחינת עדן), וגילוי בחינה זו יהי' רק בעולם הבא, מוכח מזה, שעיקר בחינת עדן שיהי' בעולם הבא הוא שאז יתגלה התענוג העצמי שמתענג בישראל, שלמעלה גם מהתענוג העצמי שבמצוות.\nה) <b>וביאור</b> העילוי דתחיית המתים לגבי ימות המשיח (ועד\"ז החילוק שבין ב' הדרגות שבתחיית המתים גופא), יובן בהקדים ביאור המעלה דימות המשיח לגבי ג\"ע<sup data-n=\"1921\">31</sup>. שהגילוי דג\"ע הוא דוקא לנשמות בלא גופים, והגילוי דימות המשיח יהי' גם למטה בעוה\"ז הגשמי (וכמו עתידה ארץ ישראל שתוציא גלוסקאות<sup data-n=\"1922\">32</sup>). והטעם לזה הוא, כי בג\"ע הוא הגילוי דאור הממלא, אור מוגבל, ולכן אינו נמשך למטה, משא\"כ בימות המשיח יהי' גילוי אוא\"ס הבלתי מוגבל, ולכן יהי' הגילוי גם למטה. ועוד חילוק, דבג\"ע יש בכללות שתי בחינות, ג\"ע התחתון וג\"ע העליון, ובכל א' מהם יש ריבוי מדריגות עד אין קץ<sup data-n=\"1923\">33</sup>, כמרז\"ל<sup data-n=\"1924\">34</sup> ת\"ח אין להם מנוחה כו' ילכו מחיל אל חיל<sup data-n=\"1925\">35</sup>, שעולים תמיד ממדריגה למדריגה. ופירוש אין להם מנוחה הוא שעלייתם ממדריגה למדריגה היא ע\"י עבודה. דבעלי' צ\"ל מקודם טבילה בנהר דינור לשכוח ההשגה והתענוג דמדריגה התחתונה<sup data-n=\"1926\">36</sup>, וגם העלי' עצמה היא דרך העמוד<sup data-n=\"1927\">37</sup> שבין מדריגה למדריגה, שגם עי\"ז הוא מתבטל מהשגתו הקודמת, אלא שהביטול שע\"י הטבילה בנהר דינור הוא הביטול שמצד התחתון והביטול שע\"י העמוד הוא שמתבטל מצד גילוי אור של מדריגה העליונה שמאיר עליו<sup data-n=\"1928\">38</sup>. וזהו שהעלי' ממדריגה למדריגה היא ע\"י עבודה (אין להם מנוחה), עבודת הביטול, בדוגמת העבודה למטה בעוה\"ז, שכללותה היא לצרף את הבריות<sup data-n=\"1929\">39</sup>, זיכוך וביטול, עבודה מלשון עיבוד עורות<sup data-n=\"1930\">40</sup>. ויש להוסיף, דכמו שהעבודה למטה היא בשני קוין, סור מרע ועשה טוב, עד\"ז הוא גם בהביטול שבהעליות דג\"ע, שהוא בשני קוין אלו. הביטול שע\"י נהר דינור – דוגמת העבודה דסור מרע כביכול, והביטול שע\"י העמוד, שמצד גילויאור העליון – דוגמת העבודה דועשה טוב. דכל זה הוא בגן עדן. משא\"כ בהגילוי שיהי' בימות המשיח, הגם שגם אז יהיו כו\"כ עליות, העליות שיהיו אז לא יהיו באופן דילכו מחיל אל חיל, שבכדי להגיע למדריגה נעלית יותר צריך ללכת (לצאת ולהתבטל) ממדריגה הקודמת, אלא שגם בהיותו במדריגתו הקודמת יכול להתעלות למדריגה העליונה (עצ\"ע).\nו) <b>ויש</b> לומר הביאור בזה, שההמשכה דאור הממלא להחיות ולהוות את הנבראים היא באופן דהשתלשלות מלמעלה למטה. שבתחילה הוא מתלבש בנבראים הרוחניים, ואח\"כ הוא מתלבש בנבראים שלמטה מהם, שהם רק כמו משל לנבראים העליונים, ואח\"כ מתלבש למטה יותר<sup data-n=\"1931\">41</sup>, וכמו שידוע בענין וידבר שלשת אלפים משל<sup data-n=\"1932\">42</sup>. ויש לומר, דזהו הטעם שהעלי' בג\"ע (שבג\"ע הוא הגילוי דאור הממלא, כנ\"ל) ממדריגה למדריגה היא ע\"י שמתבטל ממדריגה התחתונה, כי כמו שההמשכה מלמעלה למטה היא ע\"י שמתלבש בעוד לבוש ובעוד לבוש, עד\"ז הוא בהעלי' מלמטה למעלה, שהעלי' היא ע\"י הפשטת הלבוש, ביטול מדריגה הקודמת<sup data-n=\"1933\">43</sup>. [ויש לומר, דזהו ג\"כ מה שמובא בכמה דרושים<sup data-n=\"1934\">44</sup> שגם האבות ומשה רבינו שיושבין בג\"ע העליון יותר מג' אלפים שנה יבואו להתלבש בגופים, כי הגילוי שיהי' בתחיית המתים הוא נעלה הרבה יותר מהגילוי שמאיר בג\"ע, אפילו בג\"ע העליון. דזה שמדייקים \"שיושבין בג\"ע העליון יותר מג' אלפים שנה\", יש לומר, דג' אלפים שנה הם דוגמת שלשת אלפים משל, שהם כנגד ג' עולמות בי\"ע, דבכל עולם יש אלף מדריגות. וזהו שמדייקים \"שיושבין בג\"ע העליון יותר מג' אלפים שנה\", דבמשך ג' אלפים שנה מפשיטים כל הלבושים (המשלים) דג' עולמות בי\"ע, וכשיושבים בג\"ע יותר מג' אלפים שנה מתעלים גם באצילות וכו', ואעפ\"כ יבואו להתלבש בגופים, כי הגילוי דתחיית המתים הוא למעלה יותר מהגילוי דג\"ע, גם כשהגילוי דג\"ע הוא לאחרי שמפשיטים כל הלבושים]. משא\"כ העליות שיהיו בימות המשיח יהיו באופן שלא יצטרך לצאת ממצבו ומדריגתו, מכיון שאז יהי' הגילוי דאוא\"ס הבל\"ג, והגילוי יהי' גם למטה.\nז) <b>אמנם</b>, גם הגילוי דימות המשיח הוא רק גילוי הסובב, ולכן יהיו בו חילוקי מדריגות (כנ\"ל), משא\"כ הגילוי דתחיית המתים יהי' (בכללותו) לכל ישראל בשוה<sup data-n=\"1935\">45</sup>, לפי שבתחיית המתים יהי' גילוי עצמות אוא\"ס שלמעלה מהתחלקות. ובזה גופא יהיו שני ענינים. הגילוי דעצמות אוא\"ס שהמשיכו ע\"י קיום המצוות, ועי\"ז יתעלו ישראל למדריגה עליונה יותר<sup data-n=\"1936\">46</sup>, שתתגלה מעלת ישראל עצמם, נצרמטעי מעשה ידי להתפאר, שמעלה זו שבישראל היא נעלית יותר מזה שממשיכים גילוי אלקות ע\"י לימוד התורה וקיום המצוות. דשרש הנשמות הוא בעצמותו ית' (למעלה משורש התומ\"צ), וגם בהגוף דישראל הוא בחירת העצמות<sup data-n=\"1937\">47</sup>.\n**********",[["1890","*","יצא לאור ב<b>קונטרס כ\"א טבת – תשמ\"ט</b>, \"לקראת יום ה' פ' שמות, כ\"א טבת, יום סיום אמירת קדיש אחרי הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע – הננו מוציאים לאור . . <i>כ' טבת תשמ\"ט</i>\"."],["1891","1","סנהדרין ר\"פ חלק."],["1892","2","רע\"ב (ועוד) לסנהדרין שם. מדרש שמואל על מס' אבות בתחלתו."],["1893","3","סנהדרין שם (צ, א)."],["1894","4","רמב\"ם שבהערה 6. וגם לההכרעה בתורת החסידות (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. ועוד). ד\"עולם הבא\" (בכלל) הוא עולם התחי' – לפעמים, גם ג\"ע נק' בשם \"עולם הבא\", כדלקמן בפנים, ובהנסמן שם בהערה 11."],["1895","5","ועפ\"ז יש לבאר מה שאמרו \"וכי שלשה עולמות יש\" (סנהדרין צ, סע\"ב) – אף שלכאורה יש ג' עולמות, עולם הזה ג\"ע ועולם התחי' (כמו שהקשה בספר העיקרים פ\"ל וספל\"א, הובא באוה\"ת שלח ע' תקמג) – כי כיון שג\"ע ישנו גם עכשיו, יש לומר שהוא נכלל ב\"עולם הזה\"."],["1896","6","רמב\"ם הל' תשובה פ\"ח ה\"ח."],["1897","7","תהלים כד, ג-ד."],["1898","8","גם לג\"ע התחתון – כ\"מ בד\"ה כי ישאלך שבהערה הבאה. ולהעיר מהמשך תער\"ב ח\"ב ר\"פ שעט (ס\"ע תשעט)."],["1899","9","ד\"ה כי ישאלך עטר\"ת (סה\"מ עטר\"ת ס\"ע שנא ואילך), ה'ש\"ת (סה\"מ ה'ש\"ת ס\"ע 44 ואילך)."],["1900","10","בנוסח תפלת שחרית דשבת. וראה בארוכה ד\"ה אין ערוך תרנ\"ב (סה\"מ תרנ\"ב ע' ו ואילך)."],["1901","11","סה\"מ תרנ\"ב שם. המשך תער\"ב ח\"א פרע\"ט (ע' תקסה). ח\"ב פ' שפ (ע' תשפא). ח\"ג ע' א'שפז."],["1902","12","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370325\" data-slug=\"torah-or\" data-id=\"3901370325\">תו\"א יתרו עג, ב</a>. וראה גם סהמ\"צ להצ\"צ טו, ב. ד\"ה כי ישאלך עטר\"ת רפ\"ב (סה\"מ שם ס\"ע שנג ואילך), ה'ש\"ת פ\"ד (סה\"מ שם ע' 48)."],["1903","13","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה (מד, סע\"א</a> ואילך), <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">ושם פל\"ז (מט, א</a>-ב). ובכ\"מ."],["1904","14","עירובין יט, א. חגיגה כז, א."],["1905","15","ישעי' ס, כא."],["1906","16","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). וראה בהנסמן לעיל ח\"א ע' רנח הערה 33."],["1907","17","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">לקו\"ת שה\"ש טז, ג</a>. ד\"ה כל ישראל יש להם חלק לעוה\"ב (הא') תרכ\"ו (סה\"מ תרכ\"ו ע' קצב). <i>ועוד</i>."],["1908","18","אוה\"ת נ\"ך עה\"פ ישעי' שם ס\"ג (ע' רפח)."],["1909","19","לאחרי שתתגלה להם ההמשכה שהמשיכו ע\"י קיום המצוות – ראה לקמן הערה 46. ועפ\"ז יש לבאר הסדר שבכתוב: \"ועמך כולם צדיקים\", המעלה דישראל; לאח\"ז – \"לעולם יירשו ארץ\"; ולאח\"ז עוד מעלה \"נצר מטעי גו'\" – די\"ל הביאור בזה, שלאחרי ש\"יירשו ארץ\" ותתגלה להם ההמשכה שהמשיכו ע\"י קיום המצוות (\"ועמך כולם צדיקים\") – אז דוקא יוכל להיות הגילוי ד\"נצר מטעי גו'\"."],["1910","20","פל\"ז (בתחלתו. וראה גם שם מח, א)."],["1911","21","ראה שם פל\"ו \"שימות המשיח <i>ובפרט</i> כשיחיו המתים\"."],["1912","22","ראה המשך תרס\"ו ע' תקז \"דתכלית העלי' דלעתיד הוא שיגיעו לשרשן ומקורן האמיתי כי אין למעלה מזה . . אין דומה לך מושיענו לתחיית המתים, שתתגלה שורש ומקור האמיתי של הנשמות כמו באמיתת העצמות\"."],["1913","23","ראה ד\"ה כי ישאלך ה'ש\"ת (סה\"מ שם ע' 45) \"הצד השוה שבהם (בג\"ע ובעולם התחי') הוא . . שהם <i>תשלום שכר וגמול טוב</i>\"."],["1914","24","לשון הצ\"צ בסהמ\"צ שבהערה 12."],["1915","25","ולהעיר, שהגילוי דאוא\"ס שהמשיכו ישראל ע\"י קיום המצוות, יהי' גם בעולם [אלא שבישראל יהי' הגילוי ביותר – ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> ספל\"ו. פל\"ז (מז, סע\"ב ואילך)]. וגם מזה מוכח לכאורה שלא זהו עיקר הענין דעוה\"ב."],["1916","26","ברכות לד, ב."],["1917","27","ישעי' סד, ג."],["1918","28","ראה המשך תרס\"ו ע' קה. ושם (ע' קו) שבכדי להגיע לבחי' תענוג העצמי כמו שהוא בעצמותו א\"א ע\"י תומ\"צ אלא ע\"י התשובה – והרי ענין התשובה הוא העילוי דנשמות שלמעלה מתומ\"צ."],["1919","29","סהמ\"צ שבהערה 12."],["1920","30","בראשית ב, י."],["1921","31","בהבא לקמן ראה המשך תער\"ב ח\"ב פ' שעט-שפ (ע' תשעט ואילך)."],["1922","32","שבת ל, סע\"ב. וש\"נ."],["1923","33","אגה\"ק סי\"ז."],["1924","34","סוף מסכת ברכות. וש\"נ."],["1925","35","תהלים פד, ח."],["1926","36","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370146\" data-slug=\"torah-or\" data-id=\"3901370146\">זהר ח\"א רא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">ח\"ב ריא, ב</a>. רמז, א. תקו\"ז בהקדמה (ד, א). וראה תו\"א מקץ לא, ב. לב, ד. מג\"א צו, א. ד\"ה כי ישאלך עטר\"ת פ\"א (סה\"מ שם ע' שנב), ה'ש\"ת פ\"א (סה\"מ שם ע' 45). וראה מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתכא-ב. וש\"נ."],["1927","37","ראה זהר ח\"א ריט, א. ח\"ב ריא, א. וראה מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תשעג, ובהנסמן במראי מקומות לשם (ע' תתקפד)."],["1928","38","ראה בארוכה המשך תרס\"ו ע' טו."],["1929","39","ב\"ר רפמ\"ד. וש\"נ."],["1930","40","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו\"א משפטים עו, א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380085\" data-slug=\"likkutei-torah\" data-id=\"4001380085\">לקו\"ת ויקרא ב, ד</a>. ובכ\"מ."],["1931","41","ראה בארוכה סה\"מ עטר\"ת ע' שטו ואילך. ובכ\"מ."],["1932","42","מלכים-א ה, יב. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מג\"א צח, ב</a>. ובכ\"מ."],["1933","43","ראה המשך תרס\"ו שם."],["1934","44","סה\"מ תרנ\"ד ע' רכ. המשך תער\"ב שם (ריש ע' תשפ). סה\"מ קונטרסים ח\"ב תיב, א. ועוד."],["1935","45","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380499\" data-slug=\"likkutei-torah\" data-id=\"4001380499\">לקו\"ת שלח מו, ד</a>. המשך תער\"ב ח\"ב ע' א'קיב. עיי\"ש."],["1936","46","<i>וע\"ד</i> הידוע שבכדי להגיע להגילוי דתחיית המתים צ\"ל תחלה הגילוי דג\"ע (ראה בארוכה ד\"ה היושבת בגנים תשי\"ג ס\"ח (לעיל ח\"ב ס\"ע רלה)) – עד\"ז הוא גם בהגילוי דתחיית המתים גופא, שבתחלה צ\"ל הגילוי דהמצוות, ועי\"ז אפשר להיות הגילוי דשורש נש\"י כמו שמושרשים בהעצמות."],["1937","47","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"ב</a> ואילך). ספר השיחות תורת שלום ע' 120 ואילך."]]],[1500380036,"<h3>בס\"ד. ש\"פ שמיני, מבה\"ח וער\"ח אייר ה'תשכ\"ח<sup data-n=\"1938\">*</sup></h3>\n<b>ויאמר</b> לו יהונתן מחר חודש ונפקדת כי יפקד מושבך<sup data-n=\"1939\">1</sup>, ומביא אדמו\"ר מהר\"ש [בעל יום ההולדת דב' אייר] במאמרו ע\"פ זה<sup data-n=\"1940\">2</sup> מה שפירש רש\"י עה\"פ שונפקדת הוא לשון זכרון ויפקד הוא לשון חסרון, ופירוש ונפקדת כי יפקד מושבך הוא, דע\"י שיפקד מקום מושבו של דוד, עי\"ז יזכור שאול עליו. וממשיך בהמאמר<sup data-n=\"1941\">3</sup>, דהטעם שנאמר ונפקדת (ולא ונזכרת וכיו\"ב), שונפקדת הוא (גם) לשון יחוד<sup data-n=\"1942\">4</sup> [כלשון רז\"ל<sup data-n=\"1943\">5</sup> חייב אדם לפקוד את אשתו כו'], כי שאול הוא בינה (כמ\"ש<sup data-n=\"1944\">6</sup> שאול מרחובות הנהר), שורש המדות דז\"א [כמ\"ש<sup data-n=\"1945\">7</sup> מי ברא אלה, דמי, בינה, הוא השורש דאלה, מדות<sup data-n=\"1946\">8</sup>], ודוד הוא מלכות, ולכן נאמר ונפקדת, ששאול <i>יפקוד</i> את דוד, היינו שיהי' יחוד ז\"א [ששרשו מבינה, שאול] ומלכות [דוד]. וזהו הקשר דונפקדת כי יפקד מושבך עם מחר חודש, כי בערב ר\"ח הוא העלם והסתר הלבנה, ועד שברגע שלפני המולד לא נשאר ממנה גם נקודה, ועי\"ז<sup data-n=\"1947\">9</sup> נעשה אח\"כ (מחר) חודש, מולד הלבנה מחדש, יחוד שמשא וסיהרא. וכמו\"כ הוא במלכות (שורש הלבנה), דע\"י שיפקד מושבך (של דוד, מלכות), עי\"ז דוקא ונפקדת, יחוד מלכות עם ז\"א. ולכאורה יש להוסיף, דזה שבר\"ח נעשה יחוד שמשא (ז\"א) וסיהרא (מלכות) הוא<sup data-n=\"1948\">10</sup> שנמשך בהשמש (ז\"א) מבחינת לעילא מן שמשא<sup data-n=\"1949\">11</sup>, כתר שלמעלה מהשתלשלות. כמ\"ש<sup data-n=\"1950\">12</sup> בעטרה שעטרה לו אמו ביום חתונתו, שבכדי שיהי' יחוד ז\"א עם המלכות (יום חתונתו) הוא ע\"י שנמשך בו עטרה, כתר. והמשכת הכתר לז\"א (ביום חתונתו) הוא ע\"י הבינה, עטרה שעטרה לו <i>אמו</i><sup data-n=\"1951\">13</sup>. ועפ\"ז מובן עוד יותר הקשר דמחר חודש עם ונפקדת כי יפקד מושבך, כי ענין מחר חודש [מה שע\"י העלם והסתר הלבנה (שבערב ר\"ח) נעשה(בר\"ח) יחוד שמשא וסיהרא], הוא, לפי שהביטול דהלבנה (מה שמתעלמת ומסתתרת עד שלא נשאר בה אפילו נקודה) מגיע לבחינת הכתר שלמעלה מהשתלשלות&lt;10&gt; שממנו נמשך (ע\"י הבינה) הכח על יחוד שמשא וסיהרא. וכמו\"כ הו\"ע ונפקדת כי יפקד מושבך, שע\"י שיפקד מקום מושבו של דוד (מלכות), עי\"ז יהי' ונפקדת דדוד ע\"י שאול, המשכת הבינה (שאול מרחובות הנהר), ועי\"ז – המשכת הכתר (בעטרה שעטרה לו אמו).\n<b>וצריך</b> להבין, דונפקדת לשון זכרון ולשון פקידה (יחוד) ויפקד לשון חסרון הם לכאורה שני הפכים, ואיך אפשר שע\"י יפקד יהי' ונפקדת. ואף שיפקד מושבך (זה שנחסר מקום מושבו) קשור עם ענין הביטול, והביטול מגיע בכתר (כנ\"ל) שממנו נמשך הכח על היחוד, מ\"מ, מזה שפירוש יפקד מושבך הוא שיהי' מושבך <i>חסר</i>, משמע, דזה שיפקד מושבך הוא טעם על ונפקדת (ונפקדת <i>כי</i> יפקד מושבך) הוא (לא רק לפי שיפקד מושבך קשור עם ענין הביטול, אלא גם) שיפקד מושבך עצמו (שיהי' מושבך <i>חסר</i>) הוא טעם על ונפקדת, וצריך להבין, איך שייך שיפקד לשון חסרון מביא לונפקדת. וכן אינו מובן, דמזה שנאמר <i>יפקד</i> מושבך (ולא יחסר מושבך), לשון פקידה, משמע, שהשייכות דיפקד לונפקדת הוא (לא רק שיפקד <i>מביא</i> לונפקדת, אלא) שביפקד עצמו יש (בהעלם) ענין ונפקדת.\nב) <b>וממשיך</b> בהמאמר<sup data-n=\"1952\">14</sup>, דיהונתן הוא יה\"ו נתן, ואיתא במאורי אור<sup data-n=\"1953\">15</sup> שנתן בגימטריא ת\"ק הוא ה' אחרונה דשם הוי', כי ה' בהכאה בגימטריא ת\"ק. ומדייק בהמאמר, דלהפירוש שברוב המקומות שיהונתן הוא יה\"ו [ונתן (שביהונתן) הוא שהיה\"ו הם בבחינת נתינה והמשכה<sup data-n=\"1954\">16</sup>] מובן מ\"ש ויאמר <i>לו</i> יהונתן, ההמשכה מיהונתן לדוד, שהיה\"ו דיהונתן נמשכו למלכות, דוד. אבל לפירוש המאו\"א דנתן שביהונתן הוא ה' אחרונה, היא המלכות, מהו\"ע ויאמר <i>לו</i> יהונתן (המשכת יהונתן לדוד), הרי נתן דיהונתן ודוד הם לכאורה היינו הך. ומבאר, דבמלכות שתי מדריגות. כמו שהיא סוף האצילות (זנב לאריות<sup data-n=\"1955\">17</sup>), וכמו שהיא מקור לבי\"ע (ראש לשועלים<sup data-n=\"1955\">17</sup>). וזהו החילוק בין נתן (דיהונתן) לדוד, דנתן שהוא ה' אחרונה דשם הוי' (כנ\"ל) הוא המלכות כמו שהיא סוף האצילות, ודוד הוא המלכות כמו שהיא מקור לבי\"ע. וענין ויאמר לו יהונתן הוא המשכת המלכות כמו שהיא באצילות (נתן, ה' אחרונה. ועי\"ז – גם המשכת יה\"ו) בהמלכות שהיא מקור לבי\"ע (דוד). ומוסיף בהמאמר, דשתי הבחינות שבמלכות נק' בשם ים וארץ. ים<sup data-n=\"1956\">18</sup> הוא המלכות כמו שהיא באצילות, שבה נמשכים הספירות דז\"א שלמעלה מהמלכות – כל הנחלים הולכים אל הים<sup data-n=\"1957\">19</sup>. וע\"ישהמלכות מקבלת וכונסת בתוכה את הספירות שלמעלה ממנה – היא מעלמת עליהם, כדוגמת הים שהוא מכסה על מה שבתוכו. ועי\"ז<sup data-n=\"1958\">20</sup> נמשכת המלכות להיות מקור להוות הנבראים – בחינת ארץ, תדשא הארץ גו' תצא הארץ גו'<sup data-n=\"1959\">21</sup>. ומבאר, דענין ויאמר לו יהונתן הוא כענין הפך ים ליבשה<sup data-n=\"1960\">22</sup> שהי' בקריעת ים סוף. היינו, דנוסף להמשכת המלכות כמו שהיא באצילות (נתן, ה' אחרונה) שנמשכה בבחינת המלכות כמו שהיא מקור לבי\"ע (דוד), הי' גם הענין דהפיכת ים ליבשה, שנבקע ההעלם (ים) ונתגלו האורות דהספירות דאצילות (שבמלכות) כמו שהם בעצמותם.\n<b>וממשיך</b> בהמאמר&lt;14&gt;, דלאחרי שדוד קיבל מאמר ודברי יהונתן (היינו שנמשכו בו עצמיות האורות דאצילות), אז<sup data-n=\"1961\">23</sup> אמר לו<sup data-n=\"1962\">24</sup> ושלשת תרד מאד, ושלשת הוא<sup data-n=\"1963\">25</sup> שתיעשה בחינת סגול (שיש בו ג' נקודות) שרומז על עבודת הבירורים<sup data-n=\"1964\">26</sup> (היינו ירידת המלכות למטה לברר בירורים), ועי\"ז יהי' ושלשת, בחינת סגולתא (שגם בסגולתא יש ג' נקודות), בחינת סגולה. כמ\"ש<sup data-n=\"1965\">27</sup> והייתם לי סגולה מכל העמים, דע\"י הבירור שמבררים מכל העמים, עי\"ז והייתם לי סגולה. ולכאורה, זה שאמר יהונתן לדוד ושלשת תרד מאד [שע\"י הירידה לבחינת סגול לברר בירורים<sup data-n=\"1966\">28</sup> יתעלה לבחינת סגולתא וסגולה], הוא בכללות ענין אחד עם זה שאמר לו תחלה ונפקדת כי יפקד מושבך, דע\"י שיפקד מושבך (ירידה והסתר) יהי' ונפקדת. [אלא שבתחילה אמר לו הענין בכללות, ואח\"כ הוסיף בזה פרטים, הן בנוגע להירידה – ושלשת <i>תרד מאד</i> גו' וישבת אצל <i>האבן האזל</i>, הירידה בעולם העשי'<sup data-n=\"1967\">29</sup>, והן בנוגע להעלי' שע\"י הירידה – <i>ושלשת</i>, שיתעלה לבחינת סגולתא וסגולה].\nג) <b>וצריך</b> להבין מה שהתחלת ההפטורה דמחר חודש הוא ויאמר לו יהונתן, דלכאורה, הרי תוכן ההפטורה דמחר חודש הוא, שבכדי שיהי' מולד הלבנה (מלכות) צריך להיות תחלה (בערב ר\"ח) הירידה וההסתר (יפקד מושבך, תרד מאד גו' אצל האבן האזל), וענין ויאמר לו יהונתן שבתחילת ההפטורה הוא (אדרבה) תכלית השלימות דהמלכות (מקור דבי\"ע), שמאיר בה בגילוי בחינת המלכות דאצילות וגם המדות דז\"א (כנ\"ל סעיף ב). ונקודת הביאור בזה, שבכדי שיהי' הענין דיפקדמושבך [ובאופן שעי\"ז יהי' ונפקדת] הוא על ידי המשכה מלמעלה. וזהו שהתחלת ההפטורה [עוד לפני שאומרים התיבות מחר חודש] היא ויאמר לו יהונתן, שבתחילה נמשך במלכות (מקור דבי\"ע) האורות דאצילות, ועי\"ז<sup data-n=\"1968\">30</sup> אפשר להיות אח\"כ ענין מחר חודש<sup data-n=\"1969\">31</sup> – הירידה וההסתר דהלבנה, יפקד מושבך (ענין <i>ערב</i> ראש חודש, <i>מחר</i> חודש), ולאחרי זה (בראש חודש) – ונפקדת.\n<b>וע\"פ</b> הידוע גודל הדיוק במאמרי רבותינו נשיאנו גם בנוגע להשייכות דהענינים שבהמאמרים <i>לזמן</i> אמירתם, יש לומר, דענין הנ\"ל שההמשכה דויאמר לו יהונתן (שבערב ר\"ח) הוא כענין הפך ים ליבשה, הוא מודגש בעיקר בערב ר\"ח סיון<sup data-n=\"1970\">32</sup> – הזמן דאמירת המאמר. ויובן זה ע\"פ המבואר במק\"א<sup data-n=\"1971\">33</sup> בענין ג' חדשים הראשונים (ניסן אייר וסיון), דהטעם שבג' חדשים אלה דוקא נזכר יציאת מצרים [חודש האביב כי בו יצאת ממצרים<sup data-n=\"1972\">34</sup>, באחד לחודש השני בשנה השנית לצאתם מארץ מצרים<sup data-n=\"1973\">35</sup>, בחודש השלישי לצאת בני ישראל מארץ מצרים<sup data-n=\"1974\">36</sup>], הוא, כי התכלית דיציאת מצרים [ענינו דחודש ניסן] הוא מתן תורה<sup data-n=\"1975\">37</sup> [ענינו דחודש סיון<sup data-n=\"1976\">38</sup>], וספירת העומר [ענינו דחודש אייר<sup data-n=\"1977\">39</sup>] הוא הממוצע שעל ידו באים מיציאת מצרים למתן תורה<sup data-n=\"1978\">40</sup>. ועפ\"ז יש לומר, דהמבואר בהמאמר שענין ויאמר לו יהונתן (מחר חודש) הוא כענין הפך ים ליבשה, הוא, כי מאמר זה<sup data-n=\"1979\">41</sup> נאמר בשבת ערב ר\"ח סיון, וכיון שחודש סיון וכן חודש אייר באים בהמשך ליציאת מצרים, לכן, בערב ראש חודש דחדשים אלה מודגש שענין ויאמר לו יהונתן (מחר חודש) הוא דוגמת הענין דקריעת ים סוף – הגמר דיציאת מצרים<sup data-n=\"1980\">42</sup>.\nד) <b>ויש</b> לומר, שג' הענינים שבג' חדשים הנ\"ל – יציאת מצרים, ספירת העומר ומתן תורה – הם דוגמת ג' הענינים דויאמר לו יהונתן גו' ונפקדת כי יפקד מושבך. יציאת מצרים שבאה ע\"י המשכה מלמעלה – ע\"ד הענין דויאמר לויהונתן, וכנ\"ל שההמשכה דויאמר לו יהונתן היא ע\"ד הענין דקריעת ים סוף, הגמר דיציאת מצרים. ספירת העומר, הירידה דנפש האלקית והתלבשותה בנפש הבהמית בכדי לברר המדות דנפש הבהמית – ע\"ד הענין דיפקד מושבך ושלשת תרד מאד גו' בכדי לברר בירורים. והגילוי דמתן תורה שבא לאחרי עבודת הבירורים דספירת העומר, שהוא נעלה יותר גם מהגילוי דיציאת מצרים וקי\"ס (שלפני העבודה) – ע\"ד הענין דונפקדת שלאחרי יפקד מושבך שהוא נעלה יותר גם מהגילוי דויאמר לו יהונתן שלפני זה.\n<b>ועפ\"ז</b> יש לומר, דבערב ר\"ח סיון, ההדגשה דויאמר לו יהונתן היא בעיקר בנוגע לזה שע\"י ההמשכה דויאמר לו יהונתן נמשך הנתינת כח על הענין דונפקדת, ענין סגולתא (וסגולה) שבושלשת. וכמבואר בהמאמר השייכות דושלשת תרד מאד לקריעת ים סוף (ויאמר לו יהונתן), דפירוש ושלשת תרד מאד גו' וישבת אצל אבן האזל הוא שהענין דסגולתא (סגולה) [שנמשך ע\"י הבירורים] יומשך למטה (תרד מאד) עד בעשי' (אבן האזל), ע\"ד הגילוי דקריעת ים סוף שנמשך גם בדרגות התחתונות דעשי', ראתה <i>שפחה</i> כו'<sup data-n=\"1981\">43</sup>. ובערב ר\"ח אייר, ההדגשה דויאמר לו יהונתן היא בעיקר שעי\"ז נמשך הנתינת כח על הענין דיפקד מושבך, ענין סגול שבושלשת, עבודת הבירורים.\nה) <b>ויש</b> לקשר זה עם מ\"ש הצ\"צ ברשימותיו לתהלים<sup data-n=\"1982\">44</sup> בנוגע המזמור למנצח בנגינות מזמור שיר<sup data-n=\"1983\">45</sup> (שאומרים אחרי ספירת העומר<sup data-n=\"1984\">46</sup>), שכתב האלשיך, שמזמור זה מדבר בימות המשיח, שאז יהיו שני דברים. שפע ברכות טוב לישראל – אלקים יחננו ויברכנו גו'<sup data-n=\"1985\">47</sup>, ויתקדש שמו ית' בעולם – כי תשפוט <i>עמים</i> מישור גו'<sup data-n=\"1986\">48</sup>. וזהו שבהתחלת המזמור נאמר מזמור שיר, מזמור על ענין הראשון שיר על ענין השני. ולאחרי שהצ\"צ מעתיק את דברי האלשיך, מביא מ\"ש בלקו\"ת סד\"ה מזמור שיר חנוכת הבית<sup data-n=\"1987\">49</sup>, דמזמור הוא שיר המלאכים ושיר הוא שירת הנשמות. ולכאורה הכוונה, דמ\"ש האלשיך שמזמור הוא על ענין הראשון (שפע ברכות לישראל) ושיר הוא על ענין השני (כי תשפוט <i>עמים</i> מישור) הוא ע\"פ דרוש (וכידוע<sup data-n=\"1988\">50</sup> שהאריז\"ל אמר עליו שנשמתו היא מעולם הדרוש), אבל ע\"פ המבואר בלקו\"ת(מיוסד על קבלה, סוד) שמזמור הוא שירת המלאכים ושיר הוא שירת הנשמות, צריך לומר, שמזמור שייך לכי תשפוט <i>עמים</i> מישור, כי ההשפעה לאומות העולם היא מהמלאכים (ע\"י הע' שרים), ושיר שייך להשפע שיושפע לישראל. וממשיך הצ\"צ ברשימותיו, דהטעם שאומרים מזמור זה אחר ספירת העומר, הוא, כי ענין ספה\"ע הוא בירור ז' המדות דנפש הבהמית, דשורש נה\"ב הוא מחיות המרכבה – מלאכים, ענין מזמור, וע\"י הבירור והעלי' דנפש הבהמית נעשה גם העלי' דנפש האלקית, שיר. ויש לומר, דזה שאומרים מזמור זה שמדבר בענין בירור עמים (כפשוטם) אחרי ספירת העומר שענינה הוא בירור המדות דנפש הבהמית (שבישראל) הוא, כי ע\"י בירור המדות דנפש הבהמית נמשך גם בירור העמים, כי תשפוט עמים מישור. ועפ\"ז מובן עוד יותר שבערב ר\"ח אייר (החודש דספה\"ע) מודגש ענין הסגול שבושלשת, הבירור שמבררים \"מכל העמים\" שמביא לוהייתם לי סגולה.\nו) <b>והנה</b> כמו שבספירת העומר, ע\"י העלי' דנפש הבהמית (מזמור) נעשה העלי' דנפש האלקית (שיר), עד\"ז הוא בימות המשיח [דמזמור זה מדבר בעיקר בימות המשיח], דע\"י שיתקדש שמו ית' <i>בעולם</i> (כי תשפוט <i>עמים</i> מישור), עי\"ז יתוסף בהשפע לישראל. דהגם שענין הבירורים (שעי\"ז נמשך הגילוי) הוא עכשיו, וענין ימות המשיח הוא המשכת הגילוי <i>שלאחרי</i> עבודת הבירורים, מ\"מ, ע\"י כי תשפוט <i>עמים</i> מישור ויתקדש שמו ית' בעולם <i>אז</i>, יתוסף עוד יותר בההמשכה והגילוי לישראל לגבי ההמשכה והגילוי שתהי' אז ע\"י עבודת הבירורים עכשיו. ולכן נאמר מזמור שיר, מזמור לפני שיר [הגם שמדבר בעיקר בימות המשיח, וענין מזמור הוא כי תשפוט עמים מישור שיהי' <i>אז</i>], כי גם אז יהי' בתחילה מזמור ועל ידו יהי' (הוספה ב)שיר. וזה שבהפסוקים (שלאחרי פסוק הראשון) נאמר אלקים יחננו ויברכנו גו' <i>לפני</i> תשפוט עמים מישור גו', יש לומר, דכיון שכוונת הבריאה היא בשביל ישראל<sup data-n=\"1989\">51</sup>, הרי מובן, שעיקר הענין דימות המשיח הוא שאז יושפע שפע רב (ברוחניות ובגשמיות) לישראל, אלא ששלימות השפע לישראל הוא ע\"י שיתקדש שמו ית' בעולם, ולכן נאמר אלקים יחננו ויברכנו יאר פניו אתנו סלה לפני תשפוט עמים מישור גו'.\n<b>וע\"ד</b> הידוע בענין נשמה וגוף, דנוסף לזה שהגילוי אלקות שנמשך להנשמה ע\"י עבודתה בתומ\"צ בהיותה מלובשת בגוף הוא גילוי נעלה הרבה יותר מהגילוי שהי' לה קודם ירידתה למטה, הנה גם <i>הגילוי</i> שע\"י העבודה דתומ\"צ בגוף גשמי יהי' בעיקר בתחיית המתים, כשהנשמה תהי' מלובשת בגוף גשמי. דהגם שגם הגילוי בג\"ע לאחרי יציאת הנשמה מהגוף הוא נעלה הרבה מהגילוי דג\"ע שהי' להנשמה קודם ירידתה, לפי שהגילוי דג\"ע שלאחרי ירידתה בגוף ויציאתה מהגוף הוא ע\"י העבודה דתומ\"צ בגוף גשמי, מ\"מ, עיקר הגילוי שע\"י העבודה דתומ\"צ יהי' בתחיית המתים, כשהנשמה תהי' מלובשת בגוף<sup data-n=\"1990\">52</sup>. וכמובן גם מהענין דתחיית המתים עצמו, דיקומו לתחי' כל ישראל, גם הנשמות שנמצאים בג\"ע כמה אלפים שנה, וג' פעמיםבכל יום הם מתעלים לדרגא נעלית יותר, ואעפ\"כ לע\"ל יתלבשו בגופים, כי הגילוי דעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע גם מדרגא הכי נעלית דג\"ע<sup data-n=\"1991\">53</sup>.\nז) <b>והענין</b> הוא, דבהיתרון שבעבודת הנשמה בהיותה מלובשת בגוף לגבי עבודת הנשמה למעלה קודם שירדה למטה, שני ביאורים בכללות. שע\"י<sup data-n=\"1992\">54</sup> שהנשמה עובדת את ה' גם בהיותה מלובשת בגוף גשמי מתגלה תוקף ההתקשרות שלה עם הקב\"ה, שגם ההעלם וההסתר דהגוף ונה\"ב אינו יכול לבטל ח\"ו ואפילו לא לעשות גרעון בההתקשרות שלה. ועאכו\"כ, כשעבודת הנשמה למטה היא באהבה רבה שלמעלה מטעם ודעת, כמו אהבת הבן לאביו, שעי\"ז מתגלה תוקף ההתקשרות שלה עם הקב\"ה כמו שהוא מצד עצם הנשמה כמו שהיא מושרשת בעצמות אוא\"ס, בדוגמת הבן כמו שהוא במוח האב עצמו. כי לגבי דרגת הנשמה כמו שהיא באצילות, שהיא דוגמת הבן (כמו) <i>שנמשך</i> ממוח האב, הירידה לבי\"ע (ומכ\"ש הירידה למטה בעוה\"ז הגשמי) מעלמת ומסתרת על זה [וכידוע<sup data-n=\"1993\">55</sup> שרק נשמות דאצילות נק' בשם בנים], וזה שגם בירידתה למטה היא בבחינת בן בגילוי, שהאהבה שלה היא אהבה עצמית שלמעלה מטעם ודעת כאהבת בן לאביו, הוא ע\"י גילוי עצם הנשמה כמו שהיא במוח האב (טרם שנמשך), שלגבי דרגא זו (עצם הנשמה כמו שמושרשת בהעצמות), אצילות ובי\"ע הם בשוה.\n<b>ולהוסיף</b><b>,</b> דעיקר גילוי דרגא זו (עצם הנשמה כמו שמושרשת בהעצמות) הוא ע\"י העבודה דבירור וזיכוך הגוף ונה\"ב וחלקו בעולם. כי זה שהגוף ונה\"ב אינם יכולים להסתיר על האהבה דהנשמה שלמעלה מטו\"ד הוא לפי שעצמות אוא\"ס (שבו מושרשת הנשמה) הוא בכל מקום (ולכן אין שייך שיהי' דבר שיוכל להעלים עליו), והכח דהנשמה לברר ולזכך את הגוף והנה\"ב עצמם ולעשות אותם כלים לאלקות הוא מפני שעצמות אוא\"ס (שבו מושרשת הנשמה) אינו מוגדר בשום גדר<sup data-n=\"1994\">56</sup>, שלכן, גם הגוף ונה\"ב שמצד ענינם (מצד הגדר שלהם) אינם כלים לאלקות, הרי ע\"י גילוי כח העצמות, נעשים הם כלים לאלקות.\nח) <b>ועוד</b> ביאור בהיתרון שבעבודת הנשמה בהיותה מלובשת בגוף, דשורש הגוף הוא למעלה משורש הנשמה. דבנשמות כתיב<sup data-n=\"1995\">57</sup> בנים אתם להוי' אלקיכם, ולכן, האהבה וההתקשרות דהקב\"ה לישראל מצד נשמתם היא ע\"ד אהבת אב לבנו, היינו, ששורש אהבה זו היא ממדריגה ששייכת שם תפיסת מקום דהנאהב, ואינה מעצמותו ממש. משא\"כ האהבה וההתקשרות דהקב\"ה לישראל מצד הגוף שלהם, היא (לא מצד מעלת הגוף, גם לא המעלה ד\"בן\", מעלה עצמית, אלא) מצד זהשהקב\"ה <i>בחר</i> בהגוף דישראל<sup data-n=\"1996\">58</sup>, בבחירתו החפשית, שבחירה זו היא מעצמותו ממש. וע\"י עבודת הנשמה בהגוף, נמשך גם בהנשמה הענין דבחירת העצמות. והיינו, דלביאור הראשון, העלי' שנעשית בהנשמה ע\"י עבודתה בהגוף הוא גילוי השורש שלה בעצמות אוא\"ס, בדוגמת הבן כמו שהוא במוח האב עצמו (טרם שנמשך), ולביאור השני, ע\"י עבודת הנשמה בהגוף נעשה בה ענין <i>חדש</i> – המשכת העצמות (שלמעלה גם משורש הנשמה כמו שהיא במוח האב עצמו).\n<b>ויש</b> לומר, דזה שע\"י עבודת הנשמה בהגוף נעשה בה ענין חדש (שלמעלה גם משרשה), הוא, כי הבחירה דהקב\"ה בישראל הוא לא רק בהגוף דישראל אלא גם בהנשמה [דזה גופא שהנשמות הם בנים להקב\"ה הוא לפי שכך בחר בבחירתו החפשית]. אלא שבהנשמה שיש בה המעלה ד\"בן\", ענין הבחירה הוא בהעלם<sup data-n=\"1997\">59</sup>. וע\"י עבודת הנשמה בהגוף, שבו בחירת העצמות היא בגילוי, נמשך גילוי זה גם בהנשמה.\n<b>והנה</b> מהחילוקים דשני הביאורים הוא, שלביאור הראשון – הגוף הוא רק כמו ממוצע שעל ידו מתגלה שורש הנשמה. ולכן מקום לומר, דלאחרי שע\"י העבודה בהגוף נתגלה שורש הנשמה, אין צריכה הנשמה להגוף. ולביאור השני – גם הגילוי שנמשך להנשמה ע\"י עבודתה בהגוף הוא המשכת הענין דבחירת העצמות ששייך (בעיקר) להגוף, ולכן, הגילוי שע\"י העבודה דתומ\"צ יהי' בעיקר בתחיית המתים, כשהנשמה תהי' מלובשת בגוף. ויש לקשר זה עם הידוע<sup data-n=\"1998\">60</sup> שלע\"ל תהי' הנשמה ניזונית מהגוף – כי הגילוי שיהי' להנשמה לע\"ל הוא המשכת הגילוי דבחירת העצמות ששייך (בעיקר) להגוף.\nט) <b>ועפ\"ז</b> יובן מה שנתבאר לעיל [בהמאמר ד\"ה כימי צאתך דאחרון של פסח] דזה שהכתוב מדמה הגאולה העתידה להגאולה דיציאת מצרים, כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"1999\">61</sup>, הוא בנוגע <i>כל</i> הענינים שהיו ביציאת מצרים<sup data-n=\"2000\">62</sup>, כולל גם הענין דרכוש גדול שהי' ביציאת מצרים. וכמו שכל הענינים דגאולה העתידה יהיו באופן נעלה יותר מכמו שהיו ביציאת מצרים [וכפירוש הידוע<sup data-n=\"2001\">63</sup> באראנו נפלאות, שהנפלאות שיהיו בגאולה העתידה יהיו נפלאות גם בערך הנפלאות שהיו ביציאת מצרים], עד\"ז הוא בנוגע להרכוש גדול שיהי' בגאולה העתידה, שהוא רכוש גדול גם בערך הרכוש גדול שהי' ביציאת מצרים. וכמובן גם מזה שאמרו רז\"ל<sup data-n=\"2002\">64</sup>שלש מטמוניות הטמין יוסף במצרים כו' ואחת גנוזה לצדיקים לעתיד לבוא, דאין ענין יוצא מידי פשוטו, שהמטמון הגנוז לצדיקים לע\"ל הוא (גם) מטמון של כסף וזהב גשמיים. ויתירה מזה, שבימות המשיח יהיו כל המעדנים מצויים כעפר, כפס\"ד הרמב\"ם<sup data-n=\"2003\">65</sup>. וצריך ביאור, הרי הענין דימות המשיח הוא שאז יהי' מלאה הארץ דעה את ה' כמים לים מכסים<sup data-n=\"2004\">66</sup>, והענינים הגשמיים לא יתפסו מקום [ועד שלא יהי' עסק העולם כולו אלא לדעת את ה' בלבד<sup data-n=\"2005\">67</sup>], ומה נוגע שיהי' אז רכוש גדול.\n<b>ויש</b> לומר הביאור בזה, דזה שהגוף מתענג בטבעו מדברים גשמיים [מעדנים, ועד\"ז רכוש גדול] הוא לפי שענינים אלה <i>שייכים</i> להגוף מצד ענינו הפנימי [והשייכות שלו לדברים אלה הוא לא רק מצד החומריות שבו אלא גם (בעיקר) מצד ענינו הפנימי], ולכן, ע\"י הרכוש גדול והמעדנים יתוסף במלאה הארץ דעה את ה' – <i>ע\"ד</i> הענין שהנשמה תהי' ניזונית מהגוף.\nיו\"ד) <b>והנה</b> מבואר בכ\"מ<sup data-n=\"2006\">68</sup> דזה ששורש הגוף הוא למעלה משורש הנשמה, הוא, כי נשמה וגוף הם דוגמת אורות וכלים ושורש הכלים הוא למעלה משורש האורות. וכמו שע\"י המשכת והתלבשות האורות בהכלים נעשה יתרון והוספה בהאורות, כמו\"כ הוא גם בנשמה וגוף, שע\"י ירידת הנשמה והתלבשותה בגוף מתעלית הנשמה למדריגה נעלית יותר מכמו שהיתה קודם ירידתה. וע\"פ הידוע<sup data-n=\"2007\">69</sup> דזה שהבריאה היא בשביל ישראל&lt;51&gt; הכוונה בזה היא לא רק לבריאת העולם אלא לכל הגילויים, יש לומר, דהטעם הפנימי על זה ששורש הכלים הוא למעלה משורש האורות [ושע\"י הכלים נעשה יתרון בהאורות] הוא לפי שהכוונה דאורות וכלים היא בשביל ישראל, בכדי שעל ידם יומשך הענין דנשמה וגוף, וכיון ששורש הגוף הוא למעלה משורש הנשמה, דבהגוף הוא בחירת העצמות, לכן נתהוו האורות וכלים באופן ששורש הכלים הוא למעלה משורש האורות. [אלא שבנשמה וגוף, זה ששורש הגוף הוא למעלה משורש הנשמה הוא זה שבהגוף הוא <i>בחירת</i> העצמות (בחירה <i>חפשית</i>, ואין זה שייך לענין ומעלת הגוף), ובאורות וכלים, זה ששורש הכלים הוא למעלה משורש האורות שייך לענינם דהכלים. ועי\"ז נעשה עד\"ז גם בנשמה וגוף שנשתלשלו מהם, דזה ששורש הגוף הוא למעלה משורש הנשמה שייך גם לענין ומעלת הגוף].\n<b>ועפ\"ז</b> יש לבאר הטעם על זה שהיתרון שע\"י בירור העמים [שמקבלים מהמלאכים ששרשם הוא מהכלים] יהי' גם בימות המשיח (כנ\"ל סעיף ו), כי זה שע\"י הכלים נעשה יתרון בהאורות הוא מפני שהשורש (האמיתי) דאורות וכלים הוא הענין דנשמה וגוף, ולכן, כמו שהעלי' דהנשמה שע\"י הגוף היא לא רק שע\"י <i>עבודת</i>הנשמה בהגוף היא מתעלית <i>אח\"כ</i> למדריגה נעלית יותר אלא שגם העלי' עצמה דלע\"ל היא שהנשמה ניזונית מהגוף, עד\"ז הוא בנוגע להיתרון שע\"י הכלים, וכן היתרון שע\"י המלאכים ששרשם הוא מהכלים, וכן היתרון שע\"י בירור אומות העולם שמקבלים מהמלאכים, שיתרון זה יהי' גם לע\"ל, דע\"י כי תשפוט <i>עמים</i> מישור יתוסף בהשפע שנמשך לישראל.\nיא) <b>והנה</b> ידוע<sup data-n=\"2008\">70</sup> דזה שהנשמה רוצה לירד למטה להחיות את הגוף הוא מפני שהנשמה מרגשת מעלת הגוף מצד שרשו, ששורש הגוף הוא למעלה משורש הנשמה, ולכן היא רוצה להחיות את הגוף. ומה שאמרו רז\"ל<sup data-n=\"2009\">71</sup> <i>על כרחך</i> אתה חי, הוא, דכיון שהרצון דהנשמה להחיות את הגוף הוא לא מצד עצמה אלא מפני שהיא מרגשת את שורש הגוף, לכן נק' זה בשם הכרח, <i>על כרחך</i> אתה חי. ויש לומר, דזה שהנשמה מרגשת את שורש הגוף [אף שהרגש זה אינו שייך לכאורה לענינה דהנשמה, וכמובן מזה שהרצון שלה להחיות את הגוף הבא מהרגש זה נקרא בשם <i>הכרח</i>], הוא, כי בכדי שיהי' לה רצון להחיות את הגוף נמשך בה גילוי שורש הגוף, אף שמצד עצמה (גם כמו שהיא מצד שרשה) אינה שייכת לגילוי זה. וע\"י הגילוי דשורש הגוף שמאיר בהנשמה (באופן דהכרח עכ\"פ) קודם ירידתה למטה, היא נעשית כמו כלי להגילוי דשורש הגוף שמאיר בה אח\"כ ע\"י עבודתה בהגוף. ועד\"ז הוא בהענין דאורות וכלים, דזה שע\"י התלבשות האורות בהכלים נמשך בהם בחינת שורש הכלים הוא ע\"י שנרגש בהם עוד קודם ירידתם בהכלים שורש הכלים. ויש לומר, דכמו\"כ הוא בנוגע להענין דספירת העומר ומתן תורה, דזה שע\"י הירידה דנפש האלקית לברר המדות דנפש הבהמית (יפקד מושבך) נמשך בה הגילוי דמ\"ת מצד מעלת הבירורים (כנ\"ל סעיף ד), הוא, כי הירידה לברר המדות דנפש הבהמית באה לאחרי וע\"י הגילוי דיציאת מצרים, וע\"י הגילוי דיציאת מצרים נרגש בה (גם לפני הירידה) מעלת הבירורים, מכיון שהיציאה ממצרים היתה ברכוש גדול.\nיב) <b>וזהו</b> ויאמר לו יהונתן מחר חודש ונפקדת כי יפקד מושבך, שבכדי שע\"י יפקד מושבך יהי' ונפקדת הוא ע\"י ההמשכה דויאמר לו יהונתן (כנ\"ל סעיף ג), שהוא ע\"ד הענין דיציאת מצרים וקריעת ים סוף, שעי\"ז נרגש (עוד לפני הירידה) מעלת הבירורים. וזהו ונפקדת כי <i>יפקד</i> מושבך, דמלשון זה משמע שהשייכות דיפקד לונפקדת הוא לא מצד הביטול שביפקד מושבך, אלא מצד הענין דיפקד מושבך עצמו (כנ\"ל סעיף א), כי העלי' דהנשמה שע\"י ירידתה בגוף הוא לא מפני שעי\"ז מתגלה ענין דהנשמה (ביטול, וכו') אלא מצד הגוף עצמו (כנ\"ל סעיף ה), ועד\"ז הוא בנוגע להענין דונפקדת, שזה נעשה ע\"י הענין דיפקד מושבך עצמו. ונאמר ונפקדת כי <i>יפקד</i> מושבך, דיפקד הוא (גם) לשון ונפקדת, דנוסף לזה שיפקד <i>מביא</i> לונפקדת, גם ביפקד עצמו יש ענין ונפקדת (כנ\"ל סעיף א), כי ע\"י שהירידה דיפקד מושבך באה ע\"י ההמשכה דויאמר לו יהונתן, נרגש גם בהירידה עצמה מעלת הבירורים, אלא שעיקר הגילוי הוא לאחרי הירידה דיפקד מושבך, <i>מחר</i> חודש.<b>ועד\"ז</b> הוא בהחידוש דכנס\"י בגאולה העתידה, שהם עתידים להתחדש כמותה<sup data-n=\"2010\">72</sup>, שגם <i>בערב</i> ראש חודש, ברגעים האחרונים שלפני הגאולה, מאיר מעין העילוי דהגאולה, הן בנוגע לענינים הרוחניים – גילוי פנימיות התורה, ובאופן דיפוצו מעיינותיך חוצה, והן בנוגע להרכוש גדול שיהי' בגאולה העתידה – שלכל בני ישראל תהי' פרנסה בהרחבה ועד לעשירות, ומזה באים מיד להגאולה, שאז יהיו שני הענינים בתכלית השלימות – שהטובה תהי' מושפעת הרבה וכל המעדנים מצויים כעפר&lt;67&gt;, ועאכו\"כ בנוגע לענינים הרוחניים – מלאה הארץ דעה את הוי' כמים לים מכסים&lt;66&gt;.\n**********",[["1938","*","יצא לאור ב<b>קונטרס ב' אייר – תנש\"א</b>, \"לקראת ב' אייר, תפארת שבתפארת, יום הולדת כ\"ק אדמו\"ר מהר\"ש נ\"ע . . <i>ר\"ח אייר</i>,<i> שנת ה'תנש\"א</i>\"."],["1939","1","שמואל-א כ, יח – הפטורה דמחר חודש."],["1940","2","בהמאמר ד\"פ' במדבר, מחר חודש\" שבהמשך והחרים תרל\"א (ס\"ע סג ואילך). ולכאורה, התחלת המאמר שם הוא \"ויאמר לו יהונתן מחר חודש גו'\", אלא שנתוסף בהתחלתו \"ולהבין כו' צ\"ל מ\"ש (ויאמר לו כו')\" בכדי לקשרו עם המאמרים שלפניו. וראה גם ד\"ה זה דש\"פ במדבר תרנ\"ח (בסה\"מ תרנ\"ח ע' קעט ואילך) שמיוסד, לכאורה, על מאמר זה שבהמשך והחרים."],["1941","3","ראה שם ריש ע' סד וע' סט."],["1942","4","ראה גם ד\"ה זה תקס\"ז (סה\"מ תקס\"ז ע' נה. ועם הגהות – באוה\"ת בראשית יא, סע\"ב)."],["1943","5","יבמות סב, ב."],["1944","6","וישלח לו, לז. וראה ע\"ח שער ח (שער דרושי נקודות) ספ\"ד."],["1945","7","ישעי' מ, כו."],["1946","8","המשך והחרים שם ע' סט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. ובכ\"מ."],["1947","9","ראה בארוכה סה\"מ תקס\"ז שם (ע' נג ואילך). אוה\"ת שם (ט, ב ואילך)."],["1948","10","אוה\"ת שם יו\"ד, ב."],["1949","11","לשון הזהר ח\"א רכג, ב. ח\"ב נט, א. וראה זהר ח\"א צא, ב. ח\"ב קטו, ב."],["1950","12","שה\"ש ג, יא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381235\" data-slug=\"likkutei-torah\" data-id=\"4001381235\">לקו\"ת שה\"ש כו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381318\" data-slug=\"likkutei-torah\" data-id=\"4001381318\">שם מז, ג</a>-ד. המשך והחרים שם ע' סז."],["1951","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">לקו\"ת שם כו, ד</a>. המשך והחרים שם."],["1952","14","בהמשך והחרים שם ע' סט."],["1953","15","ערך יהונתן (יו\"ד, נד) – הובא גם באוה\"ת שם (יא, א)."],["1954","16","ראה סה\"מ תקס\"ז שם (ע' נה). אוה\"ת שם (טז, ב)."],["1955","17","לשון המשנה (אבות פ\"ד מט\"ו). וראה שער מאמרי רז\"ל (להרח\"ו) לאבות שם. המשך והחרים הנ\"ל ס\"ע מג ואילך. ובכ\"מ."],["1956","18","בהבא לקמן (בענין ים וארץ) ראה בארוכה המשך הנ\"ל ס\"ע לט ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380133\" data-slug=\"likkutei-torah\" data-id=\"4001380133\">לקו\"ת צו יד, ב</a> ואילך. ובכ\"מ."],["1957","19","קהלת א, ז."],["1958","20","ראה המשך הנ\"ל ע' מא, שההעלם דבחינת ים דמלכות הוא שע\"י שהמלכות מקבלת בתוכה את האורות הם <i>משתנים</i> [ע\"ד הלבנה, שע\"י שהיא מקבלת את אור השמש היא משנית את האור, שנעשה אור הלבנה ולא אור השמש], ולכן, ע\"י ההעלם דבחינת ים, אפשר להיות בחינת ארץ."],["1959","21","בראשית א, יא. שם, כד. וראה זח\"ג לט, ב (הובא בלקו\"ת שם). ובכ\"מ."],["1960","22","תהלים סו, ו."],["1961","23","כ\"ה הלשון בהמשך והחרים שם ע' סט. וראה לקמן הערה 30."],["1962","24","שמואל-א כ, יט."],["1963","25","בהבא לקמן ראה גם סה\"מ תקס\"ז שם (ע' נו. שם ע' סב ואילך). אוה\"ת שם (יב, סע\"א ואילך. שם כא, ב ואילך)."],["1964","26","כמבואר בסה\"מ תקס\"ז ובאוה\"ת שם."],["1965","27","יתרו יט, ה."],["1966","28","כ\"ה בסה\"מ תקס\"ז ובאוה\"ת שם. ובהמשך והחרים שם, דפירוש ושלשת תרד מאד הוא <i>שהגילוי</i> שנמשך ע\"י הבירורים (בחינת סגולתא) ירד ויומשך למטה, כדלקמן סעיף ד."],["1967","29","ראה בארוכה סה\"מ תקס\"ז שם (ע' סג). אוה\"ת שם (כד, ב)."],["1968","30","וכהלשון בהמשך והחרים שם (נעתק לעיל ס\"ב) \"<i>אז</i> אמר לו ושלשת תרד מאד\"."],["1969","31","ואולי י\"ל דהטעם (בפנימיות הענינים) על זה שההפטורה דמחר חודש אומרים דוקא בער\"ח שחל בשבת – כי <i>עיקר</i> הענין דמחר חודש הוא המשכת הגילוי דבחינת שבת. וע\"ד מ\"ש בספירת העומר (ראה לקמן ס\"ד) וספרתם לכם ממחרת השבת. וראה שיחת אחש\"פ שנה זו (תנש\"א (התוועדויות תנש\"א ח\"ג ע' 89 ואילך)) דכאשר התחלת הספירה היא ממחרת השבת כפשוטו (כבשנה זו), הספירה היא באופן נעלה יותר."],["1970","32","וכן בערב ר\"ח אייר, כדלהלן בפנים."],["1971","33","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011280\" data-slug=\"likkutei-sichot\" data-id=\"1300011280\">לקו\"ש ח\"א ע' 266</a>."],["1972","34","משפטים כג, טו. וכן בתשא לד, יח: כי בחודש האביב יצאת ממצרים."],["1973","35","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380320\" data-slug=\"likkutei-torah\" data-id=\"4001380320\">במדבר א, א</a>. ואף ש\"לצאתם מארץ מצרים\" קאי בפשטות על \"בשנה השנית\" – ראה לקו\"ת במדבר ג, א מזהר ח\"ג קיז, א \"לחודש השני בשנה השנית כולא חד\"."],["1974","36","יתרו יט, א."],["1975","37","כמ\"ש (שמות ג, יב) בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה."],["1976","38","כמ\"ש (יתרו שם) בחודש השלישי גו' באו מדבר סיני. וראה שבת פח, א \"אוריאן תליתאי גו' בירחא תליתאי\"."],["1977","39","דבחודש אייר (דוקא) <i>כל</i> ימי החודש הם ימי ספה\"ע."],["1978","40","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, ב</a>. ובכ\"מ. וראה בארוכה לקו\"ש שם ואילך."],["1979","41","וכן המאמר ד\"ה זה דשנת תרנ\"ח, שבו מבואר כבהמשך והחרים, נאמר בשבת ער\"ח סיון."],["1980","42","ראה לעיל ע' קסג הערה 16."],["1981","43","פרש\"י בשלח טו, ב (ממכילתא עה\"פ)."],["1982","44","אוה\"ת לתהלים (יהל אור) ע' רכו."],["1983","45","תהלים מזמור סז*."],["1984","46","שו\"ע אדה\"ז או\"ח הל' פסח סתפ\"ט סי\"א."],["1985","47","תהלים שם פסוק ב."],["1986","48","שם פסוק ה. הטעם שאינו מביא מ\"ש <i>לפנ\"ז</i> (פסוק ג) יודוך עמים גו' [וגם בפסוק ה אינו מביא התחלת הפסוק \"ישמחו וירננו לאומים\"] – אולי יש לומר, לפי ש\"יודוך עמים\" דפסוק ג [וכן ישמחו וירננו לאומים דפסוק ה] הוא על זה \"שמדתך להטיב <i>לעמך</i>\" (פרש\"י שם פסוק ב)."],["1987","49","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381121\" data-slug=\"likkutei-torah\" data-id=\"4001381121\">לקו\"ת ברכה צח, ג</a>. וכ\"ה גם בד\"ה זה בסידור (עם דא\"ח) שער החנוכה רעז, ד. ועוד."],["1988","50","ראה שם הגדולים להחיד\"א ערך ר' משה אלשיך.\n*) <i>להעיר שבי\"א ניסן שנה זו (תשכ\"ח – שנת אמירת מאמר זה) התחילו לומר מזמור זה [ראה סה\"מ י\"א ניסן ח\"א ע' 1 ואילך]</i>."],["1989","51","פרש\"י ר\"פ בראשית."],["1990","52","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. ובכ\"מ. וראה לעיל ע' ריז, ובהנסמן שם הערה 7."],["1991","53","ד\"ה כי ישאלך תרנ\"ד (סה\"מ תרנ\"ד ע' רכ). המשך תער\"ב ח\"ב פשע\"ט (ריש ע' תשפ). סה\"מ קונטרסים ח\"ב תיב, א. ועוד."],["1992","54","בהבא לקמן (עד סוף הסעיף) ראה לקמן ח\"ד ע' קמט. לקמן ע' שע. וש\"נ."],["1993","55","המשך תרס\"ו ע' קנז. <i>ובכ\"מ</i>."],["1994","56","לא רק שאינו <i>מוגבל</i> ונמצא בכל מקום אלא שגם אינו <i>מוגדר</i>. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071044\" data-slug=\"likkutei-sichot\" data-id=\"1300071044\">לקו\"ש ח\"ז ע' 44</a> ואילך."],["1995","57","ראה יד, א. וב<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a> שזה קאי על הנשמה."],["1996","58","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, סע\"א</a> ואילך). וראה ספר השיחות תורת שלום ע' 120."],["1997","59","להעיר שעד\"ז הוא בנוגע לאהבה עצמית דאב לבנו, דבבן שיש לו מעלות וראוי לאהוב אותו גם מצד השכל אין ניכר כ\"כ שהאהבה שאביו אוהב אותו היא אהבה עצמית."],["1998","60","המשך וככה תרל\"ז פצ\"א-ב. וראה גם ספר השיחות תורת שלום ס\"ע 127 ואילך. סה\"מ תרח\"ץ ע' ריט. ובכ\"מ."],["1999","61","מיכה ז, טו."],["2000","62","ראה זח\"ב ט, א \"<i>כל</i> אתין ונסין וגבוראן דעבד קוב\"ה במצרים יעביד לון לישראל, כד\"א כימי צאתך מארץ מצרים אראנו נפלאות\"."],["2001","63","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600486\" data-slug=\"or-hatorah-hb\" data-id=\"8316600486\">אוה\"ת נ\"ך</a> עה\"פ סק\"ג (ע' תפו) וסק\"ז (ע' תפז). אוה\"ת לתהלים (יהל אור) ע' קנד."],["2002","64","פסחים קיט, א. סנהדרין קי, א."],["2003","65","סוף הלכות מלכים."],["2004","66","ישעי' יא, ט. רמב\"ם שם."],["2005","67","רמב\"ם שם."],["2006","68","ראה סה\"מ תרמ\"ט ע' רמג-ד. תרנ\"ט ע' ז ואילך. ובכ\"מ."],["2007","69","ראה לקמן ח\"ד ע' קצט ואילך. <i>וש\"נ</i>."],["2008","70","סה\"מ תרנ\"ט שם. ובכ\"מ."],["2009","71","אבות פ\"ד מכ\"ב."],["2010","72","נוסח קידוש לבנה. מסנהדרין מב, א."]]],[1500380037,"<h3>בס\"ד. ש\"פ קדושים, ב' דר\"ח אייר ה'תשל\"ו<sup data-n=\"2011\">*</sup></h3>\n<b>השמים</b> כסאי והארץ הדום רגלי, אי זה בית אשר תבנו לי גו' ואל זה אביט אל עני ונכה רוח גו'<sup data-n=\"2012\">1</sup>, וידוע הדיוק בזה<sup data-n=\"2013\">2</sup>, הרי אין לו דמות הגוף<sup data-n=\"2014\">3</sup> ואיך שייך לומר כסאי והדום רגלי. וגם צ\"ל מ\"ש איזה בית אשר תבנו לי גו' ואל זה אביט אל עני ונכה רוח גו', מהי המעלה דעני ונכה רוח, דהגם שאיזה בית אשר תבנו לי, מ\"מ אל זה (לעני ונכה רוח) אביט. ונקודת הביאור בזה, דשמים וארץ הם תורה ומצוות (כמבואר בארוכה בתו\"א<sup data-n=\"2015\">4</sup>), שבכללות היא העבודה דנר\"נ<sup data-n=\"2016\">5</sup>. ובית היא העבודה דבכל מאדך<sup data-n=\"2017\">6</sup> שלמעלה מהגבלה<sup data-n=\"2018\">7</sup>, שמצד חי' יחידה<sup data-n=\"2016\">5</sup>. ופירוש איזה בית אשר תבנו לי הוא<sup data-n=\"2019\">8</sup>, שגם העבודה שמצד המקיפים חי' יחידה, שעל ידה נמשכים המקיפים שלמעלה, אין זה בית אשר תבנו לי (לי לעצמותי), כי גם המקיפים הכי עליונים הם הארה בלבד. אל זה אביט אל עני ונכה רוח<sup data-n=\"2020\">9</sup>, דע\"י הביטול (עני ונכה רוח) הוא המשכת העצמות (אל זה אביט).\nב) <b>ויש</b> לומר, שזהו גם הקשר והשייכות דההפטורה השמים כסאי לשבת ר\"ח, כי בר\"ח הוא מולד הלבנה, שאז (בעת המולד) היא נקודה בלבד, שזה מורה על הביטול שלה<sup data-n=\"2021\">10</sup>, שלית לה מגרמה כלום<sup data-n=\"2022\">11</sup>. ויתירה מזו, שברגע שלפני מולד הלבנה היא בביטול לגמרי, שאינה אפילו כנקודה, ועי\"ז דוקא נעשה המולד שלה<sup data-n=\"2023\">12</sup>. וע\"י הביטול שלה, היא מקבלת אור חדש מהשמש, דשרש המשכת אור זה הוא לא מהשמש עצמו (שהרי אין כל חדש תחת השמש<sup data-n=\"2024\">13</sup>) אלא מלעילא<sup data-n=\"2025\">14</sup> מן שמשא<sup data-n=\"2026\">15</sup>. וזהו שבשבתר\"ח מפטירין השמים כסאי גו' ואל זה אביט אל עני ונכה רוח גו', דההמשכה שע\"י הביטול<sup data-n=\"2027\">16</sup> היא המשכה נעלית ביותר, כנ\"ל.\nג) <b>ויש</b> להוסיף בפירוש הכתוב ואל זה אביט אל עני גו', דהכוונה בעני היא לא רק לענין הביטול, אלא גם לעני כפשוטו (עני בדעת<sup data-n=\"2028\">17</sup>), שאין לו ידיעה והשגה באלקות ועבודתו היא רק מצד האמונה<sup data-n=\"2029\">18</sup> שלמטה<sup data-n=\"2030\">19</sup> מטעם ודעת, מ\"מ, מכיון שבעניות זו (דאמונה שלמטה מטעם ודעת) יש גם ענין העניות למעליותא, ביטול<sup data-n=\"2031\">20</sup>, לכן, אל זה אביט. ובדוגמת הלבנה, דהגם שזה שבעת המולד היא נקודה בלבד (ומכש\"כ זה שברגע שלפני המולד היא מתעלמת ומסתתרת לגמרי) הוא שאינה מאירה, ואעפ\"כ, מכיון שזה קשור גם עם הביטול שלה, נמשך בה אז אור חדש מלעילא מן שמשא.\n<b>ויש</b> לקשר זה עם הביאור של אדמו\"ר מהר\"ש<sup data-n=\"2032\">21</sup> (בעל יום ההולדת דב' אייר) עה\"פ<sup data-n=\"2033\">22</sup> ובראשי חדשיכם, דמ\"ש ובראשי חדשיכם, ראשי לשון רבים<sup data-n=\"2034\">23</sup>, הוא, כי חודש היא מדת המלכות, שהיא בחינת האמונה, שיש בה ב' נקודות. דבסגול נקודה האמצעית היא תחת שתי הנקודות, ובסגולתא נקודה האמצעית היא למעלה משתי הנקודות, ובאמונה יש ב' הנקודות. שבגילוי היא נקודה התחתונה שבסגול, ויש בה גם נקודה העליונה שבסגולתא<sup data-n=\"2035\">24</sup>, כי נעוץ<sup data-n=\"2036\">25</sup> תחלתן בסופן.\nד) <b>ועפ\"ז</b> נמצא, שהעבודה דעני ונכה רוח (אמונה) צריכה להיות גם לפני העבודה דהשמים כסאי והארץ הדום רגלי (תורה ומצוות), ומכש\"כ לפני העבודה דאיזה בית אשר תבנו לי (בכל מאדך), שהרי אמונה וביטול הם היסוד של כל הענינים. אלא שבתחילה, העניות שלו היא כפשוטה<sup data-n=\"2037\">26</sup>, דזה שצריך לאמונה באלקות (אף שכמה ענינים מוכרחים מצד השכל) הוא מפני שהוא עני בדעת, ולאחרי העבודה בכחות הפנימיים (השמים כסאי והארץ הדום רגלי) ובכחות המקיפים (בית), העניות שלוהיא&lt;26&gt; ע\"ד מרז\"ל<sup data-n=\"2038\">27</sup> פתי יאמין לכל דבר<sup data-n=\"2039\">28</sup> זה משה רבינו, דהגם שמשה הי' בעל השגה גדולה בתכלית השלימות, מ\"מ היו אצלו כל הענינים (דאלקות)<sup data-n=\"2040\">29</sup> באופן של אמונה, כי מכיון שלגבי הקב\"ה דלית מחשבה תפיסא בי' כלל<sup data-n=\"2041\">30</sup> הכל כפתיים אצלו ית'<sup data-n=\"2042\">31</sup>, לכן כל הענינים צריכים להיות באופן של אמונה. ובכללות הוא, דהעניות שבתחילת העבודה היא ביטול דקבלת עול שלמטה מטעם ודעת, והעניות שלאח\"ז היא ביטול במציאות שלמעלה מטעם ודעת.\n<b>ויש</b> לומר, דזה שכתוב ואל זה אביט אל עני ונכה רוח <i>לאחרי</i> השמים כסאי גו', אף שגם האמונה שלמטה מהדעת היא בהעצמות [וכמובן מהידוע<sup data-n=\"2043\">32</sup> דזה ששם שמים שגור בפי כל הוא מפני <i>שהמאור</i> הוא בהתגלות], הוא, כי הבטה (ואל זה אביט) הוא גילוי (כמו דבר שרואה בעיניו), <i>וגילוי</i> העצמות הוא<sup data-n=\"2044\">33</sup> בהאמונה שלמעלה מהדעת.\nה) <b>ויש</b> לומר, שג' ענינים אלה [עניות שבתחילת העבודה, העבודה דהשמים כסאי גו', והעניות שלאחרי העבודה דהשמים כסאי] הם ע\"ד ג' החלוקות שבפירות האילן (שבפרשתנו<sup data-n=\"2045\">34</sup>), ג' שני ערלה, שנה הרביעית ושנה החמישית. והענין הוא<sup data-n=\"2046\">35</sup>, דארץ היא מלכות ואילן הוא ז\"א, ונטיעת אילן בארץ (כי תבואו אל הארץ ונטעתם כל עץ מאכל<sup data-n=\"2047\">36</sup>) הוא המשכת ז\"א במלכות. דבהמשכה זו ישנם ג' דרגות. דבג' שנים הראשונות, מקבלת המלכות רק מג' ספירות האחרונות דז\"א, נצח הוד ויסוד. ומכיון שעיקר ענינם של מדות אלו הוא שעל ידם באה ההשפעה בפועל<sup data-n=\"2048\">37</sup>, לכן, גם המדות נה\"י הם דוגמת המלכות<sup data-n=\"2049\">38</sup> שהיא שרש ומקור הנבראים, שנותנים מקוםליש, ואפשר להיות מהם יניקה לחיצונים. דזהו הקשר של הפירוש (הנ\"ל) שג' שנים הראשונות הם כנגד ג' המדות נה\"י, עם הפירוש<sup data-n=\"2050\">39</sup> שג' שנים הראשונות הם כנגד ג' קליפות הטמאות, כי כשהמלכות מקבלת רק מנה\"י אפשר להיות יניקה לג' קליפות הטמאות. ולכן הפירות דג' שנים אלו הם ערלה ואסורים בהנאה. ובשנה הרביעית מקבלת המלכות מת\"ת (משליש התחתון שבו או משני שלישים שבו). ולכן הפירות דשנה הרביעית הם קודש הילולים להוי'<sup data-n=\"2051\">40</sup>, דהילול הוא בת\"ת כמ\"ש<sup data-n=\"2052\">41</sup> ומהללים לשם תפארתך. ובשנה החמישית מקבלת המלכות גם משליש העליון דת\"ת. וזהו ובשנה החמישית גו' <i>להוסיף</i> לכם תבואתו<sup data-n=\"2053\">42</sup>, דד' הבחינות תנה\"י (שבשנה הרביעית) שייכים לד' אותיות הוי', ובשנה החמישית, נמשך תוספות אור מקוצו של יו\"ד, כתר.\nו) <b>וביאור</b> הענין דג' חלוקות אלו בעבודת האדם, יש לומר, דענין המלכות הוא קיום התומ\"צ בפועל ממש, במחשבה דיבור ומעשה. וזה שמקיים תומ\"צ בפועל ממש הוא ע\"י המשכת וגילוי המדות בהמחשבה דיבור ומעשה. ויש בזה ג' אופנים. דכשההמשכה היא רק מנה\"י (דמדות אלו הם רק בנוגע לפועל), הנה אף שנה\"י הם שוקיים<sup data-n=\"2054\">43</sup> ורגלים שמוליכים אותו למקום הראוי, ללכת בדרך הוי', מ\"מ, כיון שאין לו חיות בקיום התומ\"צ (דהחיות בתומ\"צ הוא ע\"י אהבה ויראה דוקא), לכן אפשר שבמשך הזמן תהי' חלישות בעבודתו, ובפרט בקדש עצמך במותר לך<sup data-n=\"2055\">44</sup>, ועד שיבוא מזה לדברים האסורים (כולל גם דברים האסורים בהנאה<sup data-n=\"2056\">45</sup>). ולכן העבודה שלו צריכה להיות באופן של אתכפיא. ויש לומר, שהוא ע\"ד האמונה שלמטה מהדעת (העניות שלפני העבודה דהשמים כסאי), שגם אמונה זו היא בעצמות אלא שאין בזה <i>גילוי</i> העצמות (כנ\"ל סוף סעיף ד). וע\"ד המבואר בלקו\"ת<sup data-n=\"2057\">46</sup> (בענין ג' שני ערלה כפשוטם), דזה ששובר תאוותו וממתין ג' שנים ומקיים מל\"ת דשלש שנים יהי' לכם ערלים&lt;36&gt; הוא כענין מודים אנחנו לך<sup data-n=\"2052\">41</sup>, שההודאה היא לך, למהותו ועצמותו ית', אלא שאין זה באופן של הילול, דהילול הוא גילוי [כמובא בלקו\"ת<sup data-n=\"2058\">47</sup> שהילול הוא לשון הארה כמו בהלו נרו<sup data-n=\"2059\">48</sup>], ורק באופן של הודאה, העלם.<b>ועי\"ז</b> בא אח\"כ לשנה הרביעית, שנמשך במלכות גם הת\"ת, דבעבודת האדם הוא שבהמחשבה דיבור ומעשה שלו נמשך גם מעצמיות המדות, אהבה ויראה, וכן שמחת לבב בתפארת הוי' והדר גאונו שבא ע\"י לאסתכלא ביקרא דמלכא<sup data-n=\"2060\">49</sup>. ואז, עבודתו אינה לדחות את הרע [כי כשיש לו אהבת ה', הרע הוא מאוס אצלו<sup data-n=\"2061\">50</sup> ואינו צריך לדחותו] אלא להמשיך תוספות אור. דזהו שבשנה הרביעית יהי' כל פריו קודש הילולים להוי', דענין ההילול הוא כמבואר בלקו\"ת&lt;47&gt; בפירוש הכתוב<sup data-n=\"2062\">51</sup> ואתה קדוש יושב תהלות ישראל, שהוא ית' מצד עצמו הוא קדוש ומובדל, וע\"י תהלות ישראל הוא יושב ונמשך למטה. ויש לומר, שהוא ע\"ד העבודה שמצד נר\"נ (השמים כסאי והארץ הדום רגלי) ומצד המקיפים חי' יחידה (בית), שעי\"ז נמשכים ומתגלים הפנימיים והמקיפים<sup data-n=\"2063\">52</sup> שלמעלה. אלא שהמשכה זו היא רק מבחינת הגילויים, וכמבואר בלקו\"ת&lt;46&gt; בפירוש הכתוב מודים אנחנו לך ומהללים לשם תפארתך, שההודאה היא לך, למהותו ועצמותו, וההילול הוא רק לשמו ית'<sup data-n=\"2064\">53</sup>, <i>לשם</i> תפארתך.\n<b>ועי\"ז</b> באים אח\"כ לשנה החמישית, להוסיף לכם תבואתו, תוספות אור שנמשך מקוצו של יו\"ד, כתר. דיש לומר, שענינה בעבודת האדם הוא האמונה שלמעלה מהדעת, שהאמונה שלו היא מצד ההכרה שלית מחשבה תפיסא בי' כלל. דבאמונה זו ישנם ב' המעלות. שהיא בעצמותו ית', ושהעצמות הוא בגילוי. היינו שבאמונה זו<sup data-n=\"2065\">54</sup> נרגש הפלאת העצמות, שכל ההילולים והתשבחות הם רק לשם תפארתך, ובעצמותו ית' אין שייך שום הילול, ורק אמונה והודאה<sup data-n=\"2066\">55</sup>.\nז) <b>ויש</b> לומר, דזהו שהפירות דשנה הרביעית אין נאכלים אלא בירושלים<sup data-n=\"2067\">56</sup>, והפירות דשנה החמישית נאכלים בכל מקום, כי הגילוי דשנה הרביעית הוא במדידה והגבלה, ולכן ההילול דפירות אלו הוא שמביאים אותם לירושלים לשבח ולהלל לשמים<sup data-n=\"2068\">57</sup>, והגילוי דשנה החמישית, כיון שהוא למעלה ממדידה והגבלה, לכן ההודאהלה' על ההוספה בתבואה זו<sup data-n=\"2069\">58</sup> היא בכל מקום (וגם בפירות שאין בהם קדושה, ועד שהן נאכלין אפילו בטומאה). וע\"י ההודאה לה' על פירות אלו שאין בהם קדושה, ההמשכה היא מעצמות אוא\"ס (שלמעלה משייכות לספירות)<sup data-n=\"2070\">59</sup>, ונמשכת למטה ביותר, ועי\"ז נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"2071\">60</sup>, שהתחתון שאין תחתון למטה ממנו<sup data-n=\"2072\">61</sup>, נעשה דירה לו ית', לו לעצמותו<sup data-n=\"2073\">62</sup>.\nח) <b>ויש</b> להוסיף, דע\"י שהעבודה דשנה הרביעית (שמצד עצמה היא בסדר והדרגה) באה לאחרי וע\"י קדימת העבודה דג' שנים הראשונות, נעשה ענין של קפיצה ודילוג גם בהעבודה דשנה הרביעית. דזהו גם הטעם על זה שמהעבודה דשנה הרביעית באים להגילוי דלמעלה מהשתלשלות בשנה החמישית<sup data-n=\"2074\">63</sup>. ויש לקשר זה עם ההוראה של בעל יום ההולדת דתפארת שבתפארת<sup data-n=\"2075\">64</sup>, שצריך להיות \"מלכתחילה אַריבער\"<sup data-n=\"2076\">65</sup>.\n<b>ויהי</b> רצון, שע\"י מעשינו ועבודתינו, ובפרט באופן ד\"מלכתחילה אַריבער\", יהי' קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות<sup data-n=\"2077\">66</sup>, כפירוש המדרש<sup data-n=\"2078\">67</sup> שקאי על מלך המשיח, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, בקרוב ממש.\n**********",[["2011","*","יצא לאור ב<b>קונטרס ב' אייר – תשמ\"ט</b>, \"לקראת ב' אייר, תפארת שבתפארת, יום הולדת כ\"ק אדמו\"ר מהר\"ש נ\"ע – הננו מוציאים לאור . . <i>עש\"ק ר\"ח אייר תשמ\"ט</i>\"."],["2012","1","ישעי' סו, א-ב. – הפטורת שבת ר\"ח."],["2013","2","ד\"ה זה בתו\"א בתחילתו. ד\"ה זה תרס\"ו (בהמשך תרס\"ו ע' תקיט). <i>ועוד</i>."],["2014","3","פיוט \"יגדל\". וראה פיהמ\"ש להרמב\"ם סנה' פ' חלק יסוד הג'."],["2015","4","ד\"ה הנ\"ל בתחילתו. וראה גם המשך תרס\"ו שם (ס\"ע תקלד ואילך)."],["2016","5","אוה\"ת בראשית ד\"ה זה (א, סע\"ב)."],["2017","6","לשון הכתוב – ואתחנן ו, ה."],["2018","7","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א שם א, ג</a>. ושם, ש\"בית\" הוא תפלה. <i>עיי\"ש</i>."],["2019","8","המשך תרס\"ו שם ע' תקלה בפירוש השני."],["2020","9","בתו\"א שם (וכ\"ה בהמשך תרס\"ו שם בפירוש הראשון), \"אל זה אביט הוא בחינת תפלה\", וזה בא בהמשך ל\"איזה בית גו'\". אבל בהמשך תרס\"ו שם בפירוש השני הוא כבפנים. ולהעיר גם מאוה\"ת שם (ב, ריש ע\"ב) \"אי זה בית כו' . . ומ\"מ ואל זה אביט אל עני כו'\"."],["2021","10","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370485\" data-slug=\"torah-or\" data-id=\"3901370485\">תו\"א יתרו בהוספות קט, ג</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">תו\"א שם סז, ג</a>."],["2022","11","זהר ח\"א קפא, א. וראה גם שם לג, ב. רמט, ב. ח\"ב קמה, ב. רטו, א. ח\"ג קיג, ב. ועוד."],["2023","12","ראה אוה\"ת בראשית ט, ב. וראה ד\"ה באתי לגני שנה זו (סה\"מ תשל\"ו ע' 91 ואילך. ע' 102 ואילך)."],["2024","13","קהלת א, ט."],["2025","14","לשון הזהר ח\"א רכג, ב. ח\"ב נט, א. וראה זהר ח\"א צא, ב. ח\"ב קטו, ב."],["2026","15","אוה\"ת שם י, ב. וראה ספר הערכים-חב\"ד ערך אור הלבנה ס\"ו אות ה' (ע' שיא). <i>וש\"נ</i>."],["2027","16","להעיר מאוה\"ת שם א, ב (בענין אל זה אביט אל עני גו') \"ענין עני הוא סיהרא דלית לה מגרמה כלום\"."],["2028","17","ראה נדרים מא, א. כתובות סח, א."],["2029","18","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">לקו\"ת ויקרא ו, ג</a> \"כשהיא רק בבחי' אמונה לבד נק' לחם עוני\". ושם (לפנ\"ז) שלחם עוני הוא \"ע\"ד סיהרא לית לה מגרמה כלום\"."],["2030","19","היינו, <i>שבגילוי</i> היא למטה מהדעת, אבל שרשה הוא למעלה מהדעת – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380131\" data-slug=\"likkutei-torah\" data-id=\"4001380131\">לקו\"ת צו יג, ד</a> ואילך. וראה המשך וככה תרל\"ז פנ\"ה שבקטנות אבא מלובש גדלות אבא."],["2031","20","ראה לקו\"ת שם, ריש ע\"ד \"שהאמונה היא . . ביטול, שמבטל שכלו ואינו מבקש טעם רק מאמין האמת באמונה הטהורה\"."],["2032","21","בהמשך מים רבים תרל\"ו פק\"ג. וראה שם פק\"א."],["2033","22","פינחס כח, יא."],["2034","23","וכמו שמדייק בזהר עה\"פ (ח\"ג רמח, א (ברע\"מ)) \"וכי כמה ראשין אינון לסיהרא\".\nהביאור בהתירוץ שבזהר שם [ששני הראשים הם יעקב ויוסף] – ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010018\" data-slug=\"or-hatorah-hb\" data-id=\"8159010018\">אוה\"ת פינחס ע' א'קסו</a> ואילך. ד\"ה ובראשי חדשיכם דליל א' דר\"ח אייר שנה זו (סה\"מ ה'תשל\"ו ע' 193 ואילך)."],["2035","24","השייכות דסגול לסגולתא – ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381182\" data-slug=\"likkutei-torah\" data-id=\"4001381182\">לקו\"ת שה\"ש יג, ב</a>. אוה\"ת בראשית כב, א."],["2036","25","ספר יצירה פ\"א מ\"ז."],["2037","26","שני ענינים אלו בעניות – ראה (עד\"ז) לקו\"ת ויקרא שם, ד."],["2038","27","שמו\"ר פ\"ג, א."],["2039","28","משלי יד, טו."],["2040","29","גם הענינים המושגים בשכל, כלשון הכתוב \"פתי יאמין <i>לכל</i> דבר\". וי\"ל הטעם לזה, כי גם הענינים דאלקות המושגים בשכל – להיותם <i>אלקות</i>, הם <i>בלי גבול</i>, וכשהם נתפסים בשכל, אין מאיר כ\"כ האלקות (הבל\"ג) שבהם."],["2041","30","תקו\"ז בהקדמה \"פתח אליהו\" – יז, א."],["2042","31","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח (כד, א</a>). וראה המשך באתי לגני ה'שי\"ת פ\"ה (סה\"מ ה'שי\"ת ע' 117 ואילך). ובארוכה בד\"ה באתי לגני ה'תשט\"ו פ\"ג ואילך (תורת מנחם – התוועדויות חי\"ג ע' 208 ואילך)."],["2043","32","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א וירא</a> ד\"ה פתח אליהו (יד, ב). סה\"מ תר\"ס ע' מג. קונטרסים ח\"ב רצו, א. ובכ\"מ."],["2044","33","ראה לקמן סעיף ו, ובהערה 55 שם."],["2045","34","קדושים יט, כג ואילך."],["2046","35","בכל הבא לקמן ראה לקו\"ת פרשתנו כט, ג ואילך."],["2047","36","פרשתנו שם, כג."],["2048","37","ראה אגה\"ק סט\"ו (קכב, סע\"א) \"בבוא ההשפעה לידי מעשה\". וראה סהמ\"צ להצ\"צ יב, ב ואילך. המשך תרס\"ו ע' רפט. <i>ובכ\"מ</i>."],["2049","38","ולא ממש. כידוע החילוק בין ז\"א למלכות, שהמלכות היא קצה העליון (מקור) דבי\"ע וז\"א (גם נה\"י שבו) הוא קצה התחתון דאצילות (תו\"א תרומה פא, ב. המשך תרס\"ו ס\"ע תרפד ואילך. ובכ\"מ). אלא שאעפ\"כ, נה\"י שבז\"א הם דוגמת המלכות, כבפנים.\nולהעיר מהמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380204\" data-slug=\"likkutei-torah\" data-id=\"4001380204\">לקו\"ת שם (ל, א</a>) ד\"יחוד קול ודבור\" הוא דוקא כשמאיר בדיבור מהת\"ת [וראה גם לקו\"ת שם (כט, ג) מזהר (ח\"ג ס\"פ קדושים – פז, סע\"א ואילך) שדוקא בשנה הרביעית \"מזדווג בה קוב\"ה בכנס\"י\"], ובהמשך תרס\"ו שם (ע' רפח ואילך) שגם ההמשכה מנה\"י למלכות היא בכלל \"יחוד זו\"ן\" – דיש לומר, שבתרס\"ו שם בא ענין זה בהמשך להמבואר שם לפני זה (ע' רפז) <i>שכללות</i> הז\"א הוא סוף עולמות הא\"ס, ובלקו\"ת שם מדבר <i>בעיקרו</i> של ז\"א (משא\"כ המדות נה\"י הם דוגמת המלכות)."],["2050","39","לקו\"ת שם, מפרדס שער כה* (שער התמורות) בסופו. שערי אורה (להר\"י גיקטליא) שער חמישי. זח\"ב רמד, ב."],["2051","40","פרשתנו יט, כד."],["2052","41","דברי הימים-א כט, יג."],["2053","42","פרשתנו שם, כה."],["2054","43","דנצח והוד הן תרין שוקין – זהר ח\"ג סח, רע\"א (ברע\"מ). תקו\"ז בהקדמה (ב, ב). שם בהקדמת \"פתח אליהו\" (יז, א). ועוד."],["2055","44","<a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">יבמות כ, א</a>. ספרי עה\"פ ראה יד, כא (פיסקא קד). וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ל (לט, א</a>) \"שהוא מדאורייתא\". וראה רמב\"ן ר\"פ קדושים. תניא פ\"ז. פכ\"ז (לד, סע\"ב)."],["2056","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161088\" data-slug=\"likkutei-sichot\" data-id=\"1300161088\">לקו\"ש חט\"ז ע' 88</a>, שהדברים שאסורים גם בהנאה – הרע שבהם הוא גם בעצם מציאותם (ולא רק בהצורה שלהם)."],["2057","46","שם ל, א."],["2058","47","שם כט, ג."],["2059","48","איוב כט, ג.\n*) <i>בלקו\"ת שם</i>:<i> שער </i><b>כד</b>,<i> ולכאורה הוא ט\"ס</i>."],["2060","49","<a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט (יג, ב</a>)."],["2061","50","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא פ\"י (טו, א</a>) דכפי ערך גודל האהבה לה' כך ערך גודל המיאוס ברע."],["2062","51","תהלים כב, ד."],["2063","52","להעיר מלקו\"ת שם, שע\"י תהלות ישראל הוא \"גילוי <i>מדותיו</i> ית'\" (פנימים) כמו שהם נמשכים מעצמות אוא\"ס שקדוש ומובדל (מקיפים)."],["2064","53","דהגם שההמשכה היא מ\"אתה קדוש\" – מכיון שהתהלות (שבלקו\"ת שם) הם \"קריאת שמותיו ית'\" השייכים למדות פרטיות, מובן, שהענין ד\"אתה קדוש\" שבלקו\"ת שם הוא אוא\"ס כמו שיש לו שייכות לספירות. וראה בארוכה ד\"ה באתי לגני ה'תשכ\"ט הערה 69 (לעיל ח\"ב ס\"ע שכה)."],["2065","54","משא\"כ בהאמונה שלמטה מהדעת, אינו יודע שהו\"ע שלמעלה מהשכל."],["2066","55","להעיר מלקו\"ת שם (ל, סע\"ג ואילך) דשנה החמישית הו\"ע \"הוד והדר לפניו עוז וחדוה במקומו\" (דברי הימים-א טז, כז), דיש לומר שבפסוק זה מרומזים שני הענינים: הוד – שההודאה היא \"לך\" כנ\"ל בפנים [ולהעיר מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600712\" data-slug=\"or-hatorah-hb\" data-id=\"8316600712\">אוה\"ת נ\"ך עה\"פ (ע' תשיב</a> ואילך) שהוא הוד <i>דעתיק</i>]; \"עוז וחדוה גו'\" – דשמחה היא מדבר שבגילוי דוקא."],["2067","56","פרש\"י פרשתנו יט, כד. רמב\"ם הל' מעשר שני ונטע רבעי רפ\"ט (שיעור היומי דעש\"ק ר\"ח אייר שנה זו (תשמ\"ט [בה י\"ל המאמר]) – לפי החלוקה דג' פרקים ליום)."],["2068","57","ראה פרש\"י שם (הובא גם בלקו\"ת שם כט, סע\"ב) \"ודבר זה הלולים לה' הוא שנושאו שם לשבח ולהלל לשמים\"."],["2069","58","ויש לומר, דזה שאין ציווי על הודאה זו הוא, כי ענינה של הודאה זו הוא לעשות לו ית' דירה <i>בתחתונים</i> (כדלקמן בפנים), ולכן, ההודאה היא לא מצד ציווי <i>התורה</i> אלא מצד האדם (התחתון), <i>שבטבעו</i> הוא מודה על השפעת הטובה.\nולהעיר מגודל ההשתדלות דהבעש\"ט שישראל יאמרו דברי תהלה להשי\"ת על זה שמשפיע להם בריאות ופרנסה, ע\"י ששאל אותם \"ווי גייט זיי אין געזונט . . אין פרנסה\" (סה\"מ אידיש ע' 138 ואילך), באופן שאמירת התהלות שלהם תהי' (לא מצד ציווי התורה וגם לא ע\"י שיעוררו אותם על זה, אלא) <i>מעצמם</i>.\nוראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071147\" data-slug=\"likkutei-sichot\" data-id=\"1300071147\">לקו\"ש ח\"ז ע' 135</a> ואילך, שהנהגה זו דהבעש\"ט היא ע\"ד ההודאה לה' על ההוספה בהתבואה דשנה החמישית."],["2070","59","ראה ד\"ה באתי לגני הנ\"ל (לעיל שם) שם, דענין \"אתה קדוש\" שבסיפור הבעש\"ט הנ\"ל הוא למעלה מהענין ד\"אתה קדוש\" שבלקו\"ת שם."],["2071","60","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2072","61","תניא שם."],["2073","62","המשך תרס\"ו ס\"ע ג. ובכ\"מ – נסמן לעיל ח\"ב ע' שח."],["2074","63","ויש לומר, שעד\"ז הוא בנוגע לספירת העומר, דהגם שמצד עצמה היא בסדר והדרגה [ויתירה מזו, <i>שענינה</i> הוא סדר והדרגה, שהרי ענין הספירה הוא לספור בדיוק ולא לדלג], מ\"מ, ע\"י שספירת העומר באה לאחרי קדימת הגילוי דחג הפסח שלמעלה מהשתלשלות, לכן יש בה גם מעין הענין דלמעלה מהדרגה. ולכן, ע\"י שסופרים מ\"ט יום, נמשך אח\"כ הגילוי דשער הנו\"ן שלמעלה מהשתלשלות."],["2075","64","ולהעיר מזה שת\"ת (בכלל) עולה עד הכתר, למעלה מהשתלשלות. ובפרט שליש העליון שבו, ששייך לשנה <i>החמישית</i>, כנ\"ל בפנים."],["2076","65","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"א ע' תריז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011124\" data-slug=\"likkutei-sichot\" data-id=\"1300011124\">לקו\"ש ח\"א ע' 124</a>. ועוד."],["2077","66","שה\"ש ב, ח."],["2078","67","שהש\"ר עה\"פ (ב)."]]],[1500380038,"<h3>בס\"ד. ש\"פ תזריע-מצורע, ג' אייר ה'תשמ\"ז<sup data-n=\"2079\">*</sup></h3>\n<b>גן</b> נעול אחותי כלה גל נעול מעין חתום<sup data-n=\"2080\">1</sup>, ומביא אדמו\"ר מהר\"ש בעל יום ההולדת דב' אייר בהמאמר דפ' תזו\"מ בהמשך מצה זו תר\"ם<sup data-n=\"2081\">2</sup> פירוש התרגום, דכמו שגן עדן הוא נעול וא\"א ליכנס בו כי אם נפשות הצדיקים, כן ישראל אוגדין פתחיהם לבעלם זה הקב\"ה. ומבאר בהמאמר<sup data-n=\"2082\">3</sup>, דגן הוא תענוג, וענין גן נעול הוא שאין התענוג רק באלקות, ועמך לא חפצתי<sup data-n=\"2083\">4</sup>. ולהעיר שבהמאמר שלפני זה<sup data-n=\"2084\">5</sup> מבאר דגן נעול הוא סור מרע<sup data-n=\"2085\">6</sup>. דענין סור מרע הוא בעיקר בפועל ממש. והחידוש שבמאמר זה (ע\"פ פירוש התרגום) הוא<sup data-n=\"2086\">7</sup>, דגן נעול הוא שגם התענוג שלו הוא רק באלקות<sup data-n=\"2087\">8</sup>.\n<b>והנה</b> במצו\"ד עה\"פ מפרש, שישראל הם כגן הנעול שאין מי שיוכל לבוא בו כי אם בעל הגן. וצריך להבין, הרי זה שגן הוא תענוג הוא גם בגן כפשוטו, וא\"כ, גם מהמשל דגן נעול כפשוטו מובן דענין אוגדין פתחיהן הוא שהתענוג שלו הוא רק באלקות, ומה מיתוסף בהבנת הענין דישראל אוגדים פתחיהם ע\"י הפירוש שגן נעול קאי על גן עדן. ובפרט דגן נעול בפשטות (כפירוש המצו\"ד) מתאים לכאורה יותר להנמשל. דכיון שגן נעול בהנמשל הוא התענוג של <i>האדם</i> (ישראל) שהוא נעול וסגור מלהתענג בתענוגי העולם<sup data-n=\"2088\">9</sup>, הרי המשל המתאים לזה לכאורה הוא מגן סתם, ולמה מפרש התרגום שגן נעול קאי על גן עדן שהוא (מלכתחילה) התענוג באלקות.\nב) <b>ויובן</b> זה ע\"פ מ\"ש בהמאמר, דגן נעול הוא כענין הקידושין. ומבאר זה ע\"פ הידוע<sup data-n=\"2089\">10</sup> בענין קדשנו במצותיך ותן חלקנו בתורתך<sup data-n=\"2090\">11</sup>, דקדשנו במצותיך הוא מלשון קידושין, דענין הקידושין הוא הזמנה, שהאשה המתקדשת היא מזומנת ומיוחדת לבעלה ועי\"ז היא נאסרת על כל העולם<sup data-n=\"2091\">12</sup>, ותן חלקנו בתורתך הו\"עהנישואין, המשכה בפנימיות, ועד שהאדם קולט את ההמשכה, ועד שנעשית חלק<i>נו</i><sup data-n=\"2092\">13</sup> (דישראל). וזהו קדשנו במצותיך ותן חלקנו בתורתך, דההמשכה שע\"י המצוות היא בבחינת מקיף, ופעולתה בהאדם המקיים את המצוה היא (בעיקר<sup data-n=\"2093\">14</sup>) שיהי' מובדל מהתאוות ומכל מדות הרעות, בדוגמת קידושין, דזה שהאשה מתקדשת לבעלה הוא (בעיקר) זה שהיא נאסרת על כל העולם<sup data-n=\"2094\">15</sup>. ועי\"ז הוא נעשה כלי לקלוט אור התורה, ותורתך בתוך מעי<sup data-n=\"2095\">16</sup>, נישואין.\n<b>ויש</b> להוסיף, שהדמיון דמצוות ותורה לאירוסין ונישואין הוא בשני ענינים. באופן ההמשכה, שההמשכה דהמצוות בהאדם המקיים את המצוה היא בבחינת מקיף (אירוסין) וההמשכה דתורה בהאדם העוסק בתורה היא בפנימיות (נישואין) כנ\"ל. וגם בההמשכה עצמה. דההמשכה דתורה היא המשכה נעלית ופנימית יותר מההמשכה דמצוות<sup data-n=\"2096\">17</sup> [ועד שההמשכה דמצוות היא בחינת אחוריים לגבי ההמשכה דתורה<sup data-n=\"2097\">18</sup>], ולכן<sup data-n=\"2098\">19</sup>, ההמשכה דתורה היא דוגמת המשכת הטיפה (נישואין) שהיא המשכה עצמית. ויש לומר, שגם ענין זה מרומז בותן חלקנו בתורתך. דבלשון חלקנו שני ענינים. שהתורה נעשית חלקנו דישראל (כנ\"ל), ושהיא חלק מהקב\"ה<sup data-n=\"2092\">13</sup>, דכשאתה תופס בחלק מן העצם אתה תופס בכולו<sup data-n=\"2099\">20</sup>.\nג) <b>ויש</b> להוסיף, דזה שקדשנו במצותיך הוא הקדמה לותן חלקנו בתורתך, הוא מהטעמים על זה שקודם יציאת מצרים נאמרה פרשת החודש<sup data-n=\"2100\">21</sup>, שיש בה כו\"כ מצוות [שנוהגות לדורות ונמנות במנין המצוות], כי ביציאת מצרים הותחל הענין דמתן תורה<sup data-n=\"2101\">22</sup>, ולכן לפני יציאת מצרים נצטוו בכמה מצוות, שזה הי' הקדמהלהענין דמתן תורה שהתחיל ביציאת מצרים. ולאחרי זה נצטוו עשר מצוות במרה<sup data-n=\"2102\">23</sup> שזה הי' הכנה למתן תורה בפועל. ובכללות יותר יש לומר, דזה שהתורה מתחלת בבראשית משום כח<sup data-n=\"2103\">24</sup> מעשיו הגיד לעמו לתת להם נחלת גוים<sup data-n=\"2104\">25</sup> הוא ע\"ד ההקדמה דמעשה המצוות לתורה, כי רובם של המצוות תלויות בארץ (נחלת גוים).\n<b>ויש</b> לומר, שזהו גם מהטעמים על זה שקודם חג השבועות זמן מתן תורתינו ישנם כו\"כ מצוות מיוחדות, המצוות דחג הפסח ומצות ספירת העומר. דכמו שבכל יום, כשהאדם נעשה ברי' חדשה<sup data-n=\"2105\">26</sup>, (עיקר) לימוד התורה הוא לאחרי קיום כו\"כ מצוות (ק\"ש, תפילין, תפלה וכו')<sup data-n=\"2106\">27</sup>, עד\"ז הוא בזמני השנה, שבחג הפסח בכל שנה ושנה הוא לידת ישראל<sup data-n=\"2107\">28</sup>, שלאחרי קיום המצוות המיוחדות דזמנים אלו (מצוות דחג הפסח ודימי ספירת העומר) הוא זמן מתן תורתינו.\nד) <b>וממשיך</b> בהמאמר, דכמו שקידושי איש ואשה כפשוטם הוא ע\"י שהאיש נותן לה דבר (פרוטה או שוה פרוטה) שבו היא יכולה לקנות חיי נפשה, עד\"ז הוא בנוגע לזה שהקב\"ה קדשנו במצותיו, שע\"י קיום המצוות נמשך חיות להאדם שמקיים המצוות, כמ\"ש<sup data-n=\"2108\">29</sup> אשר יעשה אותם האדם וחי בהם. והגם שהמצוות הם רצון העליון, דרצון הוא בחינת סובב שמצד עצמו הוא קדוש ומובדל מהעולמות, מ\"מ, נמשך מאור זה חיות להאדם שמקיים המצוות, חיות פנימי<sup data-n=\"2109\">30</sup>. וכמובן גם מזה שהאור שנמשך ע\"י המצוות פועל (לא רק במחשבה דיבור ומעשה שלו, אלא) גם בהמדות ועד בהרצון ותענוג שבו, וכמובא לעיל (סעיף א-ב) מהמאמר, שע\"י המצוות נעשה מובדל מהתאוות ומכל מדות הרעות, ושענין אוגדין פתחיהן (שנעשה ע\"י המצוות) הוא שאין לו <i>תענוג</i> אלא באלקות. אלא שכל זה הוא רק בחיצוניות הלב ולא נקלט עדיין בתוך תוך עומק לבבו. ולכן נק' ארוסה<sup data-n=\"2110\">31</sup>.\n<b>ועפ\"ז</b> יש לבאר פירוש התרגום שגן נעול קאי על גן עדן שא\"א ליכנס בו כ\"א נפשות הצדיקים, כי הענין דאוגדין פתחיהן באופן הנ\"ל שגם התענוג שלו הוא רק באלקות, הוא ע\"י המשכת האור מלמעלה (ע\"י קיום המצוות), ולכן המשל על זה הוא מגן עדן, תענוג אלקי (שמלמעלה)<sup data-n=\"2111\">32</sup>. ויש לומר, דזה שמביא בהמאמר(בתחלתו) פירוש התרגום, הוא, כי פירוש זה הוא היסוד להביאור שבהמאמר שאוגדין פתחיהן הו\"ע קדשנו במצותיך.\nה) <b>ובעומק</b> יותר יש לומר בהקדים הביאור בזה שמאריך בהמאמר בענין ותן חלקנו בתורתך (שהו\"ע הנישואין), דלכאורה, הרי במאמר זה הוא מבאר שגן נעול הוא ענין קדשנו במצותיך, ומה נוגע כאן לבאר הענין דותן חלקנו בתורתך. ובפשטות יש לומר, דזה שמבאר כאן הענין דותן חלקנו בתורתך נוגע לגל נעול שבהמשך הכתוב. דאיתא במדרש<sup data-n=\"2112\">33</sup> גן נעול אלו הבתולות גל נעול אלו הבעולות, ומבאר הצ\"צ<sup data-n=\"2113\">34</sup> דגן נעול הוא בחינת ארוסה וגל נעול הוא בחינת נשואה. [ויש לקשר זה עם פירוש הצ\"צ<sup data-n=\"2114\">35</sup> דגל נעול הו\"ע גל<sup data-n=\"2115\">36</sup> עיני ואביטה נפלאות מתורתך, כי עיקר ענין הנישואין יהיו לעתיד לבוא<sup data-n=\"2116\">37</sup>, לפי שאז יהי'<sup data-n=\"2117\">38</sup> הגילוי דפנימיות התורה<sup data-n=\"2118\">39</sup>]. אבל, כיון שבמאמר זה (דההמשך מצה זו) מדבר רק בענין גן נעול (והביאור דגל נעול מתחיל בהמאמר שלאחריו<sup data-n=\"2119\">40</sup>), מסתבר לומר, דזה שמבואר במאמר זה הענין דותן חלקנו בתורתך הוא כי עי\"ז מיתוסף ביאור בהבנת הענין דגן נעול. דזה שע\"י העבודה דגן נעול (קדשנו במצותיך) באים לותן חלקנו בתורתך, קליטה בפנימיות, הוא, לפי שההמשכה דהמצוות שעל ידה נעשה הקידושין היא באופן דוחי בהם בחיות <i>פנימי</i> (כנ\"ל סעיף ד). אלא <i>שגילוי</i> ענין זה הוא בהנישואין דותן חלקנו בתורתך.\nו) <b>וזהו</b> גן נעול גו' גל נעול גו', דגן נעול היא העבודה דקיום המצוות וגל נעול הוא עסק התורה ובפרט פנימיות התורה, ושתי העבודות צריכות להיות באופן דמלכתחילה אַריבער כהוראת בעל יום ההולדת<sup data-n=\"2120\">41</sup>. ועד\"ז הוא בההילוך דילכו מחיל אל חיל<sup data-n=\"2121\">42</sup>, מהדרגא דאירוסין (גן נעול) להדרגא דנישואין (גל נעול), שההילוך והעלי' צ\"ל באופן דלכתחילה אַריבער. ובאתערותא דלתתא אתערותא דלעילא, שגם ההמשכה והגילוי מלמעלה שע\"י עבודות אלו תהי' לכתחילה אַריבער, גם בערך הלכתחילה אַריבער דעבודת האדם. דנוסף לזה שכשהעבודה היא באופן דיגעתי, אזי ומצאתי<sup data-n=\"2122\">43</sup>, דמציאה היא שלא לפי ערך היגיעה, שהרי מציאה באה בהיסח הדעת<sup data-n=\"2123\">44</sup>, המציאה גופא היא באופן דלכתחילה אַריבער.\n<b>ויהי</b> רצון, שע\"י הדיבור בענינים אלה, ובפרט ע\"י העבודה בזה, נזכה בקרוב ממש לגאולה העתידה, שאז יהי' השלימות דקדשנו במצותיך ותן חלקנו בתורתך,שלימות המצוות – ושם נעשה לפניך כמצות רצונך<sup data-n=\"2124\">45</sup>, ושלימות התורה – תורה חדשה מאתי תצא<sup data-n=\"2125\">46</sup>, וכל זה יהי' באופן דלא עכבן אפילו כהרף עין<sup data-n=\"2126\">47</sup>, וזה גופא באופן דלכתחילה אַריבער, שלא עכבן אפילו כהרף עין ממש ממש.\n**********",[["2079","*","יצא לאור ב<b>קונטרס ב' אייר – תש\"נ</b>, \"לקראת ב' אייר, תפארת שבתפארת, יום הולדת כ\"ק אדמו\"ר מהר\"ש נ\"ע – הננו מוציאים לאור . . <i>ל' ניסן</i>,<i> אדר\"ח אייר</i>,<i> שנת ה'תש\"נ</i>\"."],["2080","1","שה\"ש ד, יב."],["2081","2","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770432\" data-slug=\"or-hatorah-hb\" data-id=\"8316770432\">פי\"ד (ע' יט</a>). וראה גם ד\"ה זה באוה\"ת שה\"ש כרך ב (ע' תלב. שם ע' תמג)."],["2082","3","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770432\" data-slug=\"or-hatorah-hb\" data-id=\"8316770432\">פט\"ו (ע' כא</a>). וכ\"ה באוה\"ת שם (ע' תלב)."],["2083","4","תהלים עג, כה."],["2084","5","דפ' שמיני פי\"ג (ע' יח)."],["2085","6","ויש לומר, דבסור מרע נכלל גם תאוות היתר."],["2086","7","להעיר, שגם במאמר זה (פט\"ז – ריש ע' כב) דגן נעול הוא \"שיהי' פיה נעול מלדבר דברים בטלים\". אבל ביאור זה אינו בהמשך לפירוש התרגום עה\"פ גן נעול."],["2087","8","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380492\" data-slug=\"likkutei-torah\" data-id=\"4001380492\">לקו\"ת שלח מה, סע\"א</a> ואילך (ועד\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380623\" data-slug=\"likkutei-torah\" data-id=\"4001380623\">לקו\"ת פינחס עה, ד</a>) \"זנות נק' בחי' התלהבות ורשפי אש זרה כמו זונה הלהוטה אחרי זרים\". דמזה מובן, שענין אוגדין פתחיהן הוא לא רק שאינו עושה בפועל אלא שגם אינו להוט אחרי תאוות."],["2088","9","ובפרט שמהלשון אוגדין פתחיהן מוכח שצריך <i>לפעולה</i>, לאגוד את פתחו, שלא יתענג בתענוגי העולם."],["2089","10","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380374\" data-slug=\"likkutei-torah\" data-id=\"4001380374\">לקו\"ת שמע\"צ צא, א</a> – הובא באוה\"ת שבהערה 2. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת במדבר טז, ג</a>. בלק סח, ב. ועוד."],["2090","11","תפלת שבת ויו\"ט."],["2091","12","קידושין ב, ב ובתוס' שם ד\"ה דאסר לה אכו\"ע כהקדש."],["2092","13","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610242\" data-slug=\"or-hatorah-hb\" data-id=\"8316610242\">אוה\"ת תצא ע' תתעא</a>."],["2093","14","ראה לקו\"ת ברכה שם ובהמאמר שם (ריש ע' כ) שזהו המכוון דמצוות."],["2094","15","ראה גיטין פב, ב \"קידושי דשמעון לא אהנו\", דקידושין שאינם אוסרים על שום אדם אינם קידושין."],["2095","16","תהלים מ, ט. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה (ט, סע\"ב</a> ואילך)."],["2096","17","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a> דבמעלת התורה על המצוות שני ענינים \"שהיא המשכת בחי' עליונה יותר . . וגם . . (ש)ע\"י התורה נמשך הגילוי בבחי' פנימיות\"."],["2097","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת בלק סח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380603\" data-slug=\"likkutei-torah\" data-id=\"4001380603\">שם עא, ב</a>."],["2098","19","כ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת בלק שם (סח, ב</a>)."],["2099","20","המשך תרס\"ו ע' תקכב. המשך תער\"ב ח\"א ע' תקנג. וראה גם שם ע' תטו. ח\"ב ע' א'פא. ועוד. וראה ספר השיחות ה'תש\"א ע' 32 הע' 19."],["2100","21","בא יב, א ואילך."],["2101","22","ראה לעיל ע' קמט, שבהגאולה דיציאת מצרים ניתן הכח גם על הגאולה והחירות דהתחתונים (ביטול הגזירה שלא יעלו למעלה).\nולהעיר משמו\"ר ספט\"ו, שמדבר בענין האירוסין שהיו (בכללות) במתן תורה – ומביא ע\"ז את הפסוק החודש שנאמר לפני (וסמוך ל)יציאת מצרים.\nועפ\"ז יומתק שיציאת ישראל ממצרים היתה בזכות שקבלו התורה (פרש\"י עה\"פ שמות ג, יב. משמו\"ר פ\"ג, ד) – אף שהסיבה (הזכות) צריכה להיות לפני המסובב (היציאה ממצרים)* – כי <i>הענין</i> דמתן תורה התחיל ביציאת מצרים.\n*) <i>ומ\"ש בשו\"ע או\"ח סו\"ס תקעא </i>\"<i>יקבלו עליהם להתענות כו' כשינצלו</i>\"<i> הוא לפי </i><b>שהקבלה</b><i> בפועל להתענות ישנה מקודם</i>."],["2102","23","סנהדרין נו, ב."],["2103","24","תהלים קיא, ו."],["2104","25","פרש\"י ר\"פ בראשית."],["2105","26","ראה שו\"ע אדה\"ז מהדו\"ב או\"ח ס\"ד סי\"ג-יד."],["2106","27","ראה שו\"ע אדה\"ז או\"ח ר\"ס קנה \"מצוה מן המובחר לקבוע אותה מיד אחר התפלה\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו\"ת ברכה צו, ב</a>. וראה לעיל ח\"ב ע' קכח."],["2107","28","יחזקאל קאַפּיטל טז."],["2108","29","אחרי יח, ה. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381137\" data-slug=\"likkutei-torah\" data-id=\"4001381137\">לקו\"ת שה\"ש ב, א</a> [ועד\"ז בדרך חיים פע\"ה (פב, א ואילך)] \"וחי בהם – שמקבל מהם חיות\"."],["2109","30","ראה גם לעיל ע' נח. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו</a> – ראה לעיל שם הערה 50."],["2110","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380664\" data-slug=\"likkutei-torah\" data-id=\"4001380664\">לקו\"ת מטות פה, ג</a>, דכשנקלט האור \"בתוך תוך עומק לבבו\", אז דוקא נק' נשואה."],["2111","32","והלשון <i>אוגדין</i> פתחיהן (ראה לעיל הערה 9) – אף <i>שהתענוג</i> שלו הוא רק באלקות – יש לומר, כי גם בחינה זו נק' אתכפיא (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380660\" data-slug=\"likkutei-torah\" data-id=\"4001380660\">לקו\"ת שם פד, ג</a>). ולהעיר מספהמ\"צ להצ\"צ צו, א-ב, דגם כשיש לו אהבת ה' אלא שהאהבה היא רק בחיצוניות הלב, נכלל זה ב\"כובש את יצרו\"."],["2112","33","שהש\"ר עה\"פ."],["2113","34","אוה\"ת שה\"ש כרך ב' ע' תמג."],["2114","35","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770090\" data-slug=\"or-hatorah-hb\" data-id=\"8316770090\">אוה\"ת שם ע' תנו</a>."],["2115","36","תהלים קיט, יח."],["2116","37","שמו\"ר ספט\"ו."],["2117","38","פרש\"י עה\"פ שה\"ש א, ב."],["2118","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a>."],["2119","40","פי\"ז."],["2120","41","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"א ע' תריז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011124\" data-slug=\"likkutei-sichot\" data-id=\"1300011124\">לקו\"ש ח\"א ע' 124</a>. ועוד."],["2121","42","תהלים פד, ח."],["2122","43","מגילה ו, ב."],["2123","44","סנהדרין צז, א."],["2124","45","נוסח תפלת מוסף דשבת ויו\"ט. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370212\" data-slug=\"torah-or\" data-id=\"3901370212\">תו\"א ויחי מו, ד</a> ואילך. תו\"ח שם (צה, א. צו, ג-ד). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010223\" data-slug=\"or-hatorah-hb\" data-id=\"8159010223\">אוה\"ת ויחי כרך ו</a> תתשכח, ב ואילך. שם כרך ז תתתסח, סע\"ב ואילך. המשך וככה תרל\"ז פי\"ז ואילך. מצה זו תר\"ם פס\"ג. ובכ\"מ."],["2125","46","ישעי' נא, ד. ויק\"ר פי\"ג, ג."],["2126","47","כמו שהי' ביציאת מצרים (מכילתא ופרש\"י עה\"פ בא יב, מא). והרי כימי צאתך מארץ מצרים אראנו נפלאות (מיכה ז, טו)."]]],[1500380039,"<h3>בס\"ד. ש\"פ אחרי-קדושים, י\"ג אייר ה'תשכ\"א<sup data-n=\"2127\">*</sup></h3>\n– בבוקר לפני התפלה, בחדרו –\n<b>דבר</b> אל כל עדת בני ישראל גו' קדושים תהיו כי קדוש אני<sup data-n=\"2128\">1</sup>, ואיתא במדרש<sup data-n=\"2129\">2</sup> יכול כמוני, תלמוד לומר כי קדוש אני, קדושתי למעלה מקדושתכם, וצריך להבין<sup data-n=\"2130\">3</sup> איך שייך אפילו קס\"ד שיהיו כמוני. ולכאורה יש לומר, דהטעם להקס\"ד יכול כמוני (אף שנברא הוא באין ערוך לבורא) הוא, כי מלשון הכתוב קדושים תהיו <i>כי</i> קדוש אני (שקדוש אני הוא <i>הטעם וההסברה</i> על קדושים תהיו) משמע, שהציווי קדושים תהיו הוא שקדושתם של ישראל צריכה להיות בדומה לקדושתו ית' – יכול כמוני [ויש לומר ההסברה בזה, דכיון שישראל וקוב\"ה כולא חד<sup data-n=\"2131\">4</sup>, לכן שייכים ישראל לכל הענינים דלמעלה]. אבל עפ\"ז צריך להבין (לאידך גיסא) מסקנת המדרש קדושתי למעלה מקדושתכם, איך זה מתאים עם לשון הכתוב <i>כי</i> קדוש אני. ומבואר בלקו\"ת<sup data-n=\"2132\">5</sup>, דקדושתכם היא הקדושה שנמשכת ע\"י אתערותא דלתתא (מעשה המצוות), וקדושתי שלמעלה מקדושתכם היא קדושה נעלית ביותר שאין אתערותא דלתתא (דמעשה המצוות) מגעת שם, ונמשכת ע\"י התשובה. וצריך ביאור, הרי גם תשובה היא עבודת האדם, אתערותא דלתתא, ולמה נקראת קדושתי שלמעלה מקדושתכם.ב) <b>והנה</b> ענין יכול כמוני כו' שבמדרש הנ\"ל בא בהמשך למ\"ש שם לפנ\"ז עה\"פ<sup data-n=\"2133\">6</sup> והיית רק למעלה יכול כמוני כו' גדולתי למעלה מגדולתכם. וע\"פ מ\"ש בלקו\"ת בענין קדושתי למעלה מקדושתכם, שביכלתם של ישראל להמשיך גם בחינת קדושתי שלמעלה מקדושתכם אלא שהמשכת קדושה זו היא ע\"י עבודה נעלית יותר (עבודת התשובה שלמעלה מהעבודה דתומ\"צ), צריך לומר, שעד\"ז הוא גם בנוגע לשתי הדרגות דגדולה (גדולתי וגדולתכם), שביכלתם של ישראל להמשיך גם בחינת גדולתי, אלא שלזה צריך עבודה נעלית יותר. ולהוסיף, דקדושה היא למעלה מגדולה. דגדולה הו\"ע ההתפשטות והגילוי<sup data-n=\"2134\">7</sup> [שלכן נקראת החסד בשם גדולה<sup data-n=\"2135\">8</sup>. וגם להביאור שגדולה היא למעלה ממדת החסד, ענין הגדולה היא חסד (התפשטות), אלא שהיא למעלה <i>ממדת</i> החסד, וההתפשטות שמצד הגדולה היא בלי גבול<sup data-n=\"2136\">9</sup>] וקדושה (מלשון קדושה והבדלה) הוא העצם<sup data-n=\"2137\">10</sup> שמובדל מענין ההתפשטות והגילוי<sup data-n=\"2134\">7</sup>. ועפ\"ז יש לומר, שגם המשכת בחינת גדולתי שלמעלה מגדולתכם היא ע\"י עבודת הצדיקים [אלא שבעבודת הצדיקים עצמה היא עבודה נעלית יותר], וזה שצריך לעבודת התשובה דוקא הוא בשביל המשכת בחינת קדושתי.\nג) <b>ויש</b> לבאר זה ע\"פ מ\"ש<sup data-n=\"2138\">11</sup> ויספו ענוים בהוי' שמחה ואביוני אדם בקדוש ישראל יגילו, ומבואר בלקו\"ת<sup data-n=\"2139\">12</sup> דיספו ענוים בהוי' שמחה קאי על עבודת הצדיקים, שע\"י הענוה והביטול שלהם הם מוסיפים שמחה בשם הוי', ועי\"ז נמשך הגילוי דהוי' למטה, ואביוני אדם הם הבעלי תשובה [דתורה ומצוות נק' בשם אדם, ולכן נקראים הבעלי תשובה בשם אביוני אדם כי הם אביונים מבחינת אדם דתורה ומצוות], שהם מגיעים בבחינת קדוש ישראל, שקדוש ומובדל מבחינת ישראל דלעילא, למעלה מהוי'. ויש לומר, שהוספת השמחה בהוי' שעי\"ז מיתוסף בההמשכה והגילוי שלו הוא המשכת בחינת גדולתי שלמעלה מגדולתכם. שהגדולה (ההתפשטות) דהוי'<sup data-n=\"2140\">13</sup> כמו שהוא מצד עצמו, היא גדולה השייכת לעולמות ונבראים, גדולת<i>כם</i>, אלא שיש גבול בההתפשטות והגילוי שלו. וענין ויספו גו' בהוי' הוא שנמשכת בו הגדולה דאוא\"ס שלמעלה משייכות לעולמות, גדולתי, ועי\"ז מיתוסף גם בההתפשטות והגילוי דהוי'. דהמשכה זו היא ע\"י עבודת הצדיקים, ענוים. וענין ואביוני אדם <i>בקדוש</i> ישראל יגילו הוא<sup data-n=\"2141\">14</sup> המשכת בחינת קדושתי (שלמעלה מקדושתכם) ע\"י התשובה.ד) <b>ויובן</b> זה בהקדים<sup data-n=\"2142\">15</sup> מ\"ש<sup data-n=\"2143\">16</sup> מי יתנך כאח לי יונק משדי אמי גו', ופירש רש\"י<sup data-n=\"2144\">17</sup>, מי יתנך כאח לי, שתבוא לנחמני כדרך שעשה יוסף לאחיו שגמלוהו רעה ונאמר בו<sup data-n=\"2145\">18</sup> וינחם אותם. ובמדרש<sup data-n=\"2146\">19</sup> איתא, באי זה אח כו' הוי אומר כיוסף לבנימין. ומבאר הצ\"צ<sup data-n=\"2147\">20</sup>, דהטעם על זה שאנו מבקשים מהקב\"ה (לפירוש המדרש) שיהי' לנו כיוסף לבנימין ולא כיוסף לאחיו<sup data-n=\"2148\">21</sup> [אף שהנהגת יוסף לאחיו הוא רבותא טפי דהגם שלא נהגו עמו כראוי מ\"מ גמל להם טובות גדולות], הוא, כי הנהגת יוסף לאחיו היתה שבתחלה ציער יוסף את אחיו, בכדי<sup data-n=\"2149\">22</sup> שעי\"ז יתכפר להם העון שמכרוהו (ורק אח\"כ גמל להם טוב), וכיון שאנו מבקשים<sup data-n=\"2150\">23</sup> מחוק ברחמיך הרבים אבל לא על ידי יסורים, לכן אומרים שהקב\"ה יהי' לנו כיוסף לבנימין. וצריך להבין, הרי הבקשה מי יתנך כאח לי היא דהגם שהנהגתינו היתה שלא כראוי מ\"מ יהי' הקב\"ה לנו כאח, ואיך שייך על זה הדוגמא דכיוסף לבנימין.\n<b>והנה</b> מבואר בלקו\"ת ד\"ה מי יתנך כאח לי<sup data-n=\"2151\">24</sup>, דמי יתנך כאח לי גו' קאי על צדיקים, ואמצאך<sup data-n=\"2143\">16</sup> בחוץ גו' קאי על בעלי תשובה. ולכאורה יש לומר, דמ\"ש בלקו\"ת שמי יתנך כאח לי קאי על צדיקים הוא לפירוש המדרש שכאח לי הוא כיוסף לבנימין, משא\"כ לפירוש רש\"י שכאח לי הוא כיוסף לאחיו, גם התחלת הכתוב מדבר בבעלי תשובה<sup data-n=\"2152\">25</sup>. אבל לפי המובא לעיל מהצ\"צ דזה שהמדרש מפרש כיוסף לבנימין (ולא כיוסף לאחיו) הוא כי הבקשה היא שהקב\"ה ימחוק את עוונותינו שלא ע\"י יסורים, מובן לכאורה, שגם לפירוש המדרש מדבר הכתוב בבעלי תשובה, ובלקו\"ת מפרש שמי יתנך כאח לי קאי על צדיקים.\nה) <b>והנה</b> ידוע<sup data-n=\"2153\">26</sup> דהכוונה (למעלה) בירידת יוסף למצרים היתה בכדי שילקט את כל ניצוצות הקדושה שהיו במצרים, וילקט יוסף את כל הכסף הנמצאבארץ מצרים<sup data-n=\"2154\">27</sup>, ועי\"ז יוקל להם הגלות. דזה שירידת יוסף למצרים היתה הסיבה לגלות מצרים, הוא בחיצוניות, אבל בפנימיות הוא אדרבה, שע\"י ירידת יוסף למצרים הוקל הגלות. שהגזירה היתה שיהיו בגלות ארבע מאות שנה<sup data-n=\"2155\">28</sup>, וע\"י שירד יוסף למצרים היו בגלות מצרים רק רד\"ו שנה<sup data-n=\"2156\">29</sup> (כי ע\"י שיוסף בירר את הניצוצות שהיו במצרים לפני שירדו בני ישראל למצרים לא הוצרכו לברר כ\"כ), ויתירה מזו, שקושי השעבוד הי' רק פ\"ו שנה<sup data-n=\"2157\">30</sup>. ומזה מובן, דזה שהשבטים מכרו את יוסף למצרים, לא רק שלא הי' היפך הכוונה, אלא אדרבה, כן היתה הכוונה העליונה שיוסף ירד תחלה למצרים בכדי להקל את הגלות. אלא שכיון שהם לא ידעו הכוונה לכן לגבם נחשב זה לחטא.\n<b>ולהעיר</b><b>,</b> שלכאורה, ענין הנ\"ל [דזה שהשבטים מכרו את יוסף למצרים היתה כפי הכוונה] הוא, לכאורה, גם להביאור (כמו שהוא בפשטות) שהכוונה בירידת יוסף למצרים היתה בכדי שעי\"ז יהי' גלות מצרים, [כדרשת חז\"ל<sup data-n=\"2158\">31</sup> עה\"פ<sup data-n=\"2159\">32</sup> וישלחהו מעמק חברון]. אלא, שלפי ביאור זה, ע\"י שהשבטים מכרו את יוסף למצרים נעשה הגלות, ענין בלתי רצוי. דהגם שהכוונה בגלות מצרים היתה בכדי שעי\"ז יזכו לקבלת התורה<sup data-n=\"2160\">33</sup>, מ\"מ, הגלות עצמו הוא ענין בלתי רצוי. משא\"כ להביאור שע\"י ירידת יוסף למצרים הוקל הגלות, זה שהשבטים מכרו (הורידו) את יוסף למצרים הוא ענין רצוי (והחטא שלהם הי' רק מפני שלא זה היתה כוונתם). ועפ\"ז יש לבאר מה שאמר יוסף להשבטים<sup data-n=\"2161\">34</sup> ועתה אל תעצבו ואל יחר בעיניכם כי מכרתם אותי הנה כי למחי' שלחני אלקים לפניכם, דלכאורה, הרי כל החטאים (הגם שהם היפך רצון העליון) הם ע\"פ ההשגחה העליונה וע\"פ רצונו ית'<sup data-n=\"2162\">35</sup>, ואעפ\"כ, כיון שעשיית החטא של האדם היא בבחירתו החפשית [וכמבואר בכ\"מ<sup data-n=\"2163\">36</sup> שההשגחה העליונה (בנוגע להענינים דתומ\"צ) אינה בסתירה לענין הבחירה], נמצא שהאדם החוטא הוא הפסיד את עצמו ולפיכך ראוי לו לבכות ולקונן על חטאיו<sup data-n=\"2164\">37</sup>, ולמה אמר יוסף לאחיו אל תעצבו ואל יחר בעיניכם גו'. ויש לומר הביאור בזה, דבכלהחטאים, הענינים שהאדם עשה הם דברים בלתי רצויים, היפך רצון העליון. דהגם שמזה שגם החטאים הם ע\"פ ההשגחה העליונה מוכרח לומר שיש בהם כוונה, הרי הכוונה היא לא בהחטאים עצמם ח\"ו אלא בזה שע\"י החטאים יבוא אח\"כ לתשובה, אבל החטאים עצמם הם היפך רצון העליון, ולכן צריך לבכות ולקונן עליהם. אבל זה שהשבטים מכרו את יוסף למצרים, כיון שהכוונה בזה היא (לא בכדי שיעשו תשובה על זה, אלא שהכוונה היא) בהירידה עצמה, <i>למחי'</i> שלחני אלקים לפניכם [ובפרט להמובא לעיל שע\"י ירידת יוסף למצרים הוקל הגלות, דיש לומר שענין זה מרומז בהמשך דברי יוסף בכתוב<sup data-n=\"2165\">38</sup> וישלחני אלקים לפניכם לשום לכם שארית בארץ גו'], לכן אל תעצבו גו' כי מכרתם אותי הנה.\n<b>אלא</b> שעדיין מקום לומר, דהגם שלמחי' שלחני אלקים לפניכם מ\"מ בנוגע ליוסף עצמו הי' זה ענין בלתי רצוי, לכן הוסיף<sup data-n=\"2166\">39</sup> לא אתם שלחתם אותי הנה כי האלקים וישימני לאב לפרעה גו' ומושל בכל ארץ מצרים, שירידת יוסף למצרים היתה דבר רצוי גם בנוגע ליוסף. [ולהעיר, שעד\"ז הוא בכל הענינים שבין אדם לחבירו<sup data-n=\"2167\">40</sup>. וכמבואר בתניא<sup data-n=\"2168\">41</sup> שגם כשאדם גומל לחבירו היפך הטוב, האמת היא שמאת <i>ה'</i> היתה זאת לו, ויש להוסיף, דמזה מובן שיהי' לו טובה מזה, שהרי כל דעביד רחמנא לטב עביד<sup data-n=\"2169\">42</sup>. אלא שבמכירת יוסף הי' זה בגילוי].\nו) <b>והנה</b> ע\"פ הידוע שכל הענינים שבתורה הם בתכלית הדיוק, יש לומר, דזה שאנו מבקשים מי יתנך כאח לי כדרך שעשה יוסף לאחיו [דהגם שעשו דבר בלתי רצוי מ\"מ גמל להם טובות גדולות], הוא, כי כל דבר בלתי רצוי שאדם עושה הוא דוגמת הענין שעשו השבטים ליוסף שמכרו אותו למצרים, והבקשה מי יתנך כאח לי היא, דהגם שע\"י מעשינו הלא טובים גרמנו להקב\"ה ענין שבדוגמת מכירת יוסף למצרים (כדלקמן) מ\"מ יגמול לנו טובות כדרך שעשה יוסף לאחיו. והענין הוא, דירידת הנשמה למטה והתלבשותה בגוף ונפש הבהמית היא גלות ממש<sup data-n=\"2170\">43</sup>, ויתירה מזה, שהנשמה היא בשבי' ובמאסר<sup data-n=\"2171\">44</sup> הגוף ונה\"ב. והכוונה בירידת הנשמה למטה היא בכדי לברר ולזכך את הגוף והנה\"ב וחלקו בעולם ולעשותם כלים לאלקות וגם בכדי שע\"י עבודת הנשמה למטה תתעלה למדריגה נעלית יותר מכמו שהיתה קודם ירידתה. ומזה מובן, דכל רגע<sup data-n=\"2172\">45</sup> שהאדם אינו עובד את עבודתו,הצער והיסורים דהנשמה מזה שהיא בגלות ובמאסר הגוף ונה\"ב, הם ללא תכלית. דבשעה שהאדם עובד את ה', כיון שעי\"ז נשלמת הכוונה דירידת הנשמה למטה בנוגע לשני ענינים הנ\"ל [בירור וזיכוך הגוף ונה\"ב וחלקו בעולם והעלי' דהנשמה], הרי התענוג דהנשמה מזה שהיא משלמת רצון הקב\"ה לברר ולזכך את הגוף שעי\"ז נשלמת הכוונה דדירה בתחתונים וכן מהעלי' שלה ע\"י עבודתה למטה הוא תענוג גדול ביותר, שבשביל זה כדאי כל היסורים שלה מהירידה. אבל ברגעים אלה שהאדם אינו עובד עבודתו [ומכש\"כ בהרגעים שהוא עושה ענינים בלתי רצויים], זה שהנשמה היא בגלות ובמאסר בהגוף ונה\"ב, והצער והיסורים שיש לה מזה, הם ללא תכלית. וכיון שהנשמה היא חלק אלוקה ממעל ממש<sup data-n=\"2173\">46</sup>, הרי הגלות והצער דהנשמה הוא (גם) גלות וצער דהשכינה<sup data-n=\"2174\">47</sup>. וזהו שע\"י הנהגה בלתי רצוי' של האדם (כולל גם זה שאינו ממלא שליחותו, גם כשאינו עובר עבירה) הוא עושה כביכול להקב\"ה ע\"ד מה שעשו השבטים ליוסף, שמכרו אותו לעבד וזה גרם אח\"כ שהי' גם במאסר.\n<b>ועוד</b> ענין בזה, שבנוגע מעשה השבטים ליוסף נאמר<sup data-n=\"2175\">48</sup> אשמים אנחנו גו' בהתחננו אלינו ולא שמענו גו', דזה שלא ריחמו עליו בהתחננו אליהם היא אשמה גדולה יותר מהמכירה עצמה<sup data-n=\"2176\">49</sup>, עד\"ז הוא בהנמשל, שהנשמה [והשכינה] מתחננים להאדם שיוציא אותם מהגלות והמאסר, וכשהאדם אינו שומע לקול תחינתם הוא (בענין זה) גרוע יותר מההנהגה הבלתי רצוי' עצמה.\nז) <b>וזהו</b> מי יתנך כאח לי, כדרך שעשה יוסף לאחיו, דכמה ענינים בזה. דכמו שיוסף כלכל את אחיו ואת טפם<sup data-n=\"2177\">50</sup> וגם נתן להם אחוזה <i>במיטב</i> הארץ<sup data-n=\"2178\">51</sup>, כן אנו מבקשים מהקב\"ה דהגם שחטאנו לפניו מ\"מ יתן לנו כל טוב. וכמו שיוסף לא הי' טינא בלבו על אחיו על זה שמכרו אותו לעבד [דנוסף לזה <i>שבפועל</i> גמל להם טובות, גם <i>בלבו</i> לא הי' לו טינא עליהם] ואדרבא השתדל שיתכפר עוונם [וכמובא לעיל (סעיף ד) דזה שציער אותם הוא בכדי שעי\"ז יתמרק עוונם], כן אנו מבקשים מהקב\"ה שימחול לנו על כל עונותינו. שהכפרה דעון מכירת יוסף היתה ע\"י שהי' להם צער, ואנו מבקשים שהקב\"ה יכפר לנו את עונותינו שלא ע\"י יסורים. וכמ\"ש הצ\"צ&lt;20&gt;, שהקב\"ה הוא כל יכול למחול בלי יסורים. והוא ע\"ד שאמרו רז\"ל<sup data-n=\"2179\">52</sup> שאלו להקב\"ה ואמר יעשה תשובה ויתכפר לו. שמצד הקב\"ה שלמעלה מהשתלשלות אפשר להיות הכפרה בלי יסורים (ואפילו בלי קרבן) אלא ע\"י תשובה בלבד. וכמושיוסף השתדל שיעשו תשובה [דמהטעמים שציער אותם הוא בכדי שיעשו תשובה<sup data-n=\"2180\">53</sup>, שלאחר שציער אותם אמרו אבל אשמים אנחנו גו'], כן אנו מבקשים מהקב\"ה שיעורר אותנו לשוב אליו [ושההתעוררות לתשובה תהי' שלא ע\"י יסורים]. וכמו שיוסף ניחם את אחיו ואמר להם אל תעצבו גו' כי מכרתם אותי הנה כי למחי' שלחני אלקים לפניכם, שהודיע וגילה להם הכוונה הפנימית בזה שמכרו אותו למצרים, דלא רק שאין זה היפך רצון העליון אלא אדרבה זה הי' רצון העליון בכדי שעי\"ז יוקל הגלות (כנ\"ל סעיף ה), כן אנו מבקשים מהקב\"ה, דלא רק שימחול לנו את עונותינו אלא יתירה מזה שיתגלה שהכוונה הפנימית דהחטאים היא המעלה דתשובה<sup data-n=\"2181\">54</sup>, וע\"י שמתגלית הכוונה והתכלית דהחטאים, נהפכים הם לזכיות<sup data-n=\"2182\">55</sup>.\nח) <b>והנה</b> אף שבכלל עבודת התשובה היא נעלית יותר מהעבודה דתומ\"צ, שלכן מקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין לעמוד בו<sup data-n=\"2183\">56</sup>, מ\"מ הכוונה דדירה בתחתונים נשלמת ע\"י עבודת הצדיקים דוקא. וזהו שאמרו רז\"ל<sup data-n=\"2184\">57</sup> דהטעם על זה שביהמ\"ק הי' בחלקו של בנימין דוקא הוא כי בנימין לא הי' במכירת יוסף, דלכאורה אינו מובן, הרי השבטים עשו תשובה על זה שמכרו את יוסף, ובמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין לעמוד בו, ולמה נבנה ביהמ\"ק בחלקו של בנימין דוקא. ומבואר בחסידות<sup data-n=\"2185\">58</sup>, שהמעלה דבעלי תשובה על צדיקים היא שע\"י התשובה מגיעים למעלה יותר, אבל בכדי שתהי' המשכת גילוי אלקות למטה, דירה בתחתונים, הוא ע\"י עבודת הצדיקים. וכיון שביהמ\"ק הו\"ע דירה בתחתונים, לכן הי' בחלקו של בנימין.\n<b>והענין</b> הוא, דמעלת הבעלי תשובה לגבי צדיקים היא שהם <i>כובשים</i> את יצרם<sup data-n=\"2186\">59</sup>, המעלה דאתכפיא, ומעלת הצדיקים היא שהם <i>מהפכים</i> את יצרם, המעלהדאתהפכא. ומהחילוקים שבין אתכפיא ואתהפכא הוא<sup data-n=\"2187\">60</sup>, שע\"י אתכפיא הוא המשכת אוא\"ס שלמעלה מהשתלשלות [כמאמר<sup data-n=\"2188\">61</sup> כד אתכפיא סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, המשכת האור שהוא בכולהו עלמין בשוה, אור שלמעלה משייכות לעולמות], אבל הגילוי דההמשכה שע\"י אתכפיא היא באופן שהתחתון אינו כלי לזה [דמזה עצמו שהתחתון הוא במצב שצריך לכפות את עצמו נגד רצונו וטבעו, מובן שאינו כלי לגילוי אלקות], ובכדי שהתחתון יהי' כלי להגילוי הוא ע\"י העבודה דאתהפכא.\n<b>וע\"פ</b> הידוע<sup data-n=\"2189\">62</sup> שכל אחד (גם כשהוא בדרגת בינוני ואפילו למטה מבינוני) שמקיים מצוות נקרא בשם צדיק [כי כללות המצוות נק' בשם צדקה<sup data-n=\"2190\">63</sup>, ולכן המקיים את המצוות נקרא בשם צדיק על שם הצדקה (מצוות<sup data-n=\"2189\">62</sup>)], יש לומר, שהענין דאתהפכא הוא לא רק בצדיקים כפשוטם אלא גם במקיימי מצוות בכלל. דכיון שלא ניתנו המצוות אלא לצרף בהן את הבריות<sup data-n=\"2191\">64</sup> (צירוף מלשון בירור וזיכוך), ובכל פעם כשאדם מקיים מצוה נתברר פרט של הגוף ונה\"ב, הרי בנוגע לפרט זה שנתברר כבר הוא בחינת צדיק, אתהפכא.\nט) <b>ויש</b><sup data-n=\"2192\">65</sup> לקשר זה עם המבואר בהמאמר ד\"ה להבין ענין פסח שני (להצ\"צ)<sup data-n=\"2193\">66</sup>, דהחילוק בין פסח ראשון לפסח שני הוא בהתאם להחילוק שבין חודש ניסן לחודש אייר. שהעבודה דחודש ניסן, שענינו הוא יציאת מצרים, היא העבודה דסור מרע, היינו שהרע הוא בתקפו והעבודה היא להיות סור מרע, לצאת ולברוח מהרע, אתכפיא<sup data-n=\"2194\">67</sup>. והעבודה דחודש אייר היא העבודה דאתהפכא. וכמבואר בלקו\"ת<sup data-n=\"2195\">68</sup> בפירוש הכתוב<sup data-n=\"2196\">69</sup> באחד לחודש השני גו' לצאתם מארץ מצרים, שעבודה הראשונה דיציאת מצרים, חודש הראשון, היא אתכפיא סט\"א, ולאחרי זה באה עבודה שני' ביציאת מצרים, חודש השני, אתהפכא. וזהו שענינו המיוחד של חודש אייר הוא ספירת העומר<sup data-n=\"2197\">70</sup>, שענינו הוא<sup data-n=\"2198\">71</sup> בירור המדות והפיכתם לקדושה, אתהפכא. ועפ\"ז מבאר בהמאמר<sup data-n=\"2199\">72</sup> הטעם על זה שבפסח ראשון חמץ אסור בבל יראה ובל ימצאובפסח שני חמץ ומצה עמו בבית<sup data-n=\"2200\">73</sup>, כי בפסח ראשון, שהמדות עדיין אינן מבוררות (והעבודה אז היא רק אתכפיא), צריך ליזהר ביותר מהרע – בל יראה ובל ימצא, ובפסח שני (אייר), שכבר יצא מהרע<sup data-n=\"2201\">74</sup> (אתהפכא), אפשר לברר לזכך ולהעלות גם את החמץ. [ולהעיר, שעד\"ז הוא החילוק דצדיקים (אתהפכא) ובעלי תשובה (אתכפיא), שצדיק צריך לומר אפשי ומה אעשה ואבי שבשמים גזר עלי<sup data-n=\"2202\">75</sup>, משא\"כ בעל תשובה צריך לומר אי אפשי, שצריך לשמירה יתירה<sup data-n=\"2203\">76</sup>]. ומזה מוכח שהענין דאתהפכא הוא גם בנוגע לענין פרטי. שהרי פסח שני הוא באמצע ימי הספירה ונשארו עדיין מדות שצריך לבררם, ומ\"מ אומר בהמאמר שבפסח שני הוא הענין דאתהפכא, כי בנוגע להמדות שנתבררו בהימים שלפני פסח שני כבר יצא מהרע, אתהפכא.\n<b>והנה</b><sup data-n=\"2204\">77</sup> הטעם על זה שיציאת מצרים היא באופן דאתכפיא וספירת העומר היא באופן דאתהפכא, הוא, כי יציאת מצרים היתה מצד אתערותא דלעילא, והגילוי הנמשך מלמעלה (שלא ע\"י עבודת האדם) אינו נמשך בפנימיות כ\"כ, וספירת העומר היא עבודת האדם, אתערותא דלתתא, והגילוי הנמשך מלמעלה ע\"י עבודת האדם [אתערותא דלעילא שע\"י אתערותא דלתתא] הוא בפנימיות. והגם שהגילוי שבא מלמעלה הוא נעלה יותר מהגילוי שנמשך ע\"י עבודת האדם [כי הנברא בעבודתו יכול להגיע רק עד שרשו<sup data-n=\"2205\">78</sup>], דכמו\"כ הוא גם בנוגע ליצי\"מ וספירת העומר, שהגילוי שהי' ביציאת מצרים הוא שנגלה עליהם מלך מלכי המלכים הקב\"ה בכבודו ובעצמו<sup data-n=\"2206\">79</sup>, וחודש אייר נקרא בשם חודש זיו<sup data-n=\"2207\">80</sup> כי הגילוי שנמשך בחודש זה הוא הארה בלבד [ויש לומר, דנוסף לזה שהגילוי שנמשך ע\"י עבודת האדם הוא למטה מהגילוי שנמשך בדרך אתערותא דלעילא מצד עצמה, בנוגע להגילוי שנמשך ע\"י העבודה דספירת העומר הוא עוד יותר. כי כיון שהעבודה דספירת העומר היא (הכנה ו)<i>קודם</i> מתן תורה, לכן, הגילוי שנמשך ע\"י העבודה דספירת העומר הוא <i>דוגמת</i> הגילוי שע\"י עבודת האבות לפני מתן תורה (כשהיתה הגזירה והמחיצה בין עליונים ותחתונים<sup data-n=\"2208\">81</sup>) שהוא למטה יותר מהגילוי שנמשך ע\"י העבודה לאחרי מתן תורה (אף שגם הגילוי שנמשך ע\"י אתערותא דלתתא עכשיו הוא למטה מהגילוי הנמשך מלמעלה מצד עצמו). וזהו שחודש אייר נקרא בשם זיו לפי שבו נולדו זיותני עולם<sup data-n=\"2209\">82</sup> הם האבות<sup data-n=\"2210\">83</sup>, שהמצוות שלהם <i>ריחות</i>היו<sup data-n=\"2211\">84</sup>], מ\"מ, בנוגע להאדם, הגילוי הבא מלמעלה נרגש (בעיקר) רק בנפש האלקית ואינו נרגש בנפש הבהמית, ולכן העבודה שע\"י גילוי זה היא רק אתכפיא, וע\"י עבודת האדם ובפרט ע\"י הגילוי שנמשך ע\"י העבודה, נעשה הבירור דנפש הבהמית והפיכתה לקדושה, אתהפכא.\nיו\"ד) <b>והנה</b> כמו שהוא בנוגע להגילוי <i>שמביא</i> לאתכפיא ולאתהפכא, שהמעלה בהגילוי שמביא לאתכפיא היא שהוא גילוי נעלה יותר והמעלה בהגילוי שמביא לאתהפכא היא שנמשך בפנימיות בהאדם [שלכן הוא דבר המתקיים<sup data-n=\"2212\">85</sup>], עד\"ז הוא בהגילוי שנמשך ע\"י העבודה דאתכפיא ואתהפכא, דמעלת הגילוי שנמשך ע\"י העבודה דאתכפיא היא גילוי נעלה ביותר [וכנ\"ל סעיף ח שהאור שנמשך ע\"י אתכפיא הוא בכולהו עלמין בשוה, אור שלמעלה משייכות לעולמות], ומעלת הגילוי שנמשך ע\"י העבודה דאתהפכא היא שהמשכתו בהאדם ובהעולם הוא בבחינת פנימיות. ועפ\"ז יש לבאר מ\"ש רש\"י<sup data-n=\"2213\">86</sup> דזה שחודש אייר נקרא בשם זיו לפי שבו נולדו זיותני עולם (אף שהאבות נולדו בניסן<sup data-n=\"2214\">87</sup>) הוא כי כשנתחדש אייר נולדו כבר בניסן, דצריך להבין, הרי זה שבחודש אייר היו זיותני עולם הוא רק תוצאה מזה שנולדו בחודש ניסן, ולמה נקרא אייר בשם זיו<sup data-n=\"2215\">88</sup>. ויש לומר הביאור בזה, דענינו של הזיו, הגילוי שנמשך ע\"י עבודה, הוא שיאיר בעולם בפנימיות ובהתיישבות, והגילוי דהאבות (זיותני עולם) בפנימיות ובהתיישבות בהעולם הי' בהחודש לאחרי שנולדו, כשנתחדש אייר נולדו <i>כבר</i>.\nיא) <b>ועד\"ז</b> הוא החילוק בין הגילוי שנמשך ע\"י עבודת הצדיקים להגילוי שנמשך על ידי עבודת התשובה, דבנוגע לדרגת הגילוי – הגילוי שנמשך ע\"י עבודת התשובה הוא נעלה יותר, אבל ההמשכה למטה בעולם (בפנימיות ובהתיישבות) היא ע\"י עבודת הצדיקים. והענין הוא, דכיון שענין התשובה הוא שהאדם יוצא מהמציאות שלו, לכן, ע\"י התשובה הוא המשכת עצמות אוא\"ס שלמעלה מגדר מציאות. דהאור שנמשך ע\"י עבודת הצדיקים הוא אור שבגדר גילוי. וגם כשהעבודה שלהם היא בביטול, דההמשכה שע\"י עבודה זו היא המשכה נעלית יותר, מ\"מ, היא בגדר גילוי. וזהו ויספו ענוים בהוי', דע\"י הענוה והביטול של הצדיקים נמשך תוספת אור בהוי' לפי שההמשכה היא מאוא\"ס שלמעלה מהוי', אבל מ\"מ גם המשכה זו היא בגדר גילוי [וכנ\"ל סעיף ג דיש לומר שענין ויספו ענוים בהוי' הוא המשכת בחינת גדולתי שלמעלה מגדולתכם, דענין הגדולה (גם בחינת גדולתי) שייך להתפשטות וגילוי], וענינה של ההמשכה הוא שעל ידה יתוסף בהגילוי דהוי' (ויספו גו' בהוי'). והמשכת בחינת <i>קדוש</i> ישראל, העצםשמובדל מגילוי, הוא ע\"י עבודת התשובה. ויש לבאר זה ע\"פ הידוע<sup data-n=\"2216\">89</sup> דענין הענוה הוא (לא שאינו יודע את המעלות שלו אלא) שהגם שיודע את המעלות שלו מ\"מ אינו מחזיק טובה לעצמו מפני שיודע שהמעלות שיש לו ניתנו לו מלמעלה. וכיון שהביטול דענוה אינה שוללת את מציאותו (שהרי הוא יודע את המעלות שלו) אלא שמציאותו היא לא מצד עצמו ורק מצד האלקות, לכן גם ההמשכה שע\"י הביטול דענוה היא גילוי בעולם (מציאות), אלא שהגילוי בעולם הוא כמו שהוא מצד שרשו, בחינת גדולתי. ובכדי להמשיך בחינת קדוש ישראל שמובדל מגילוי, הוא ע\"י הביטול דאביוני אדם, דע\"י ההרגש שהוא אביון, שאין בו שום מעלה<sup data-n=\"2217\">90</sup>, הוא <i>בטל</i> ממציאותו, ועי\"ז נמשך בחינת קדוש ישראל.\nיב) <b>והנה</b> כל זה הוא בנוגע לההמשכה עצמה. אבל בכדי שיהי' הגילוי בעולם, דירה בתחתונים, הוא ע\"י עבודת הצדיקים<sup data-n=\"2218\">91</sup>. כי ענין דירה בתחתונים הוא שיהי' גילוי אלקות כמו שהוא <i>במציאותו</i>, וכיון שענין התשובה הוא <i>שיוצא</i> ממציאותו [נוסף לביטול המציאות שלו, כנ\"ל], לכן הענין דדירה בתחתונים הוא ע\"י עבודת הצדיקים. וזהו מי יתנך כאח לי כיוסף לבנימין, דהגם שהבקשה היא שהקב\"ה יהי' לנו כאח אף שהנהגתינו היתה <i>שלא</i> כראוי, מ\"מ מבקשים שיהי' כיוסף <i>לבנימין</i>, דיש לומר, שבזה מרמז, שגם עבודת התשובה תהי' באופן שהגילוי שע\"י התשובה (שלמעלה מגדר מציאות) יומשך בעולם בהתיישבות, מעלת הצדיקים, כיוסף <i>לבנימין</i>. וזהו גם הקשר דשני הפירושים במי יתנך כאח לי שקאי על צדיקים ושקאי על בעלי תשובה (כנ\"ל סעיף ד), שיהי' החיבור וההתכללות דשני הענינים.\nיג) <b>וזהו</b> קדושים תהיו כי קדוש אני, קדושתי למעלה מקדושתכם, ומבאר בלקו\"ת דקדושתי שלמעלה מקדושתכם נמשכת שלא על ידי אתערותא דלתתא, הגם שהיא נמשכת על ידי עבודת התשובה, כי ענין עבודת התשובה הוא <i>שאינו</i> מציאות, ובמילא אין זה ענין של אתערותא <i>דלתתא</i>. וזהו מה שמקדים במדרש הענין דגדולתי שלמעלה מגדולתכם (אף שאין זה שייך לכאורה לפסוק זה), דכמו שגדולתי, אף שהיא למעלה מגדולתכם, היא ענין הגילוי (ושייכת להמטה), עד\"ז יהי' גם בההמשכה דבחינת קדושתי, שתהי' בגילוי בהעולם (ושיהי' בזה גם המעלה דאתערותא דלתתא), שעי\"ז תושלם הכוונה דדירה בתחתונים.\n**********",[["2127","*","יצא לאור ב<b>קונטרס י\"ג אייר – תנש\"א</b>, \"לקראת ש\"פ אחרי-קדושים י\"ג אייר, יום היאָרצייט* של הוו\"ח עוסק בצ\"צ רב פעלים וכו' ישראל ארי' לייב**, אחיו של – יבדל לחיים טובים – כ\"ק אדמו\"ר שליט\"א . . <i>ב' אייר</i>,<i> תפארת שבתפארת</i>,<i> שנת ה'תנש\"א</i>\".\n[לכללות המאמר – ראה ד\"ה המלאך הגואל תרפ\"ד שהוא ד\"ה מי יתנך כאח לי תרפ\"ד (סה\"מ תרפ\"ד ע' קסז ואילך). והוא מיוסד על ד\"ה מי יתנך כאח לי תרנ\"ד המצויין לקמן בהמאמר]."],["2128","1","פרשתנו (קדושים) יט, ב."],["2129","2","ויק\"ר פרשתנו פכ\"ד, ט. וראה גם ב\"ר פ\"צ, ב."],["2130","3","כמו שמדייק ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">לקו\"ת נצבים נ, ב</a>. ובאוה\"ת ריש פרשתנו (ע' קה) \"והוא תמוה\". וראה לקמן ע' רסא."],["2131","4","ראה זח\"ג עג, א."],["2132","5","שם נא, ג.\n*) <i>ראה בארוכה שיחת ש\"פ אחרי-קדושים</i>,<i> י\"ג אייר ה'תשמ\"ה [התוועדויות תשמ\"ה ח\"ג ע' 1942 ואילך] – ביאור בשמו של בעל היאָרצייט</i>,<i> והשייכות דשמו לפ' אחרי-קדושים</i>.<i> שיחת פסח שני ה'תשמ\"ז [התוועדויות תשמ\"ז ח\"ג ע' 256 ואילך]</i>.<i> ש\"פ אחרי-קדושים ה'תנש\"א [התוועדויות תנש\"א ח\"ג ע' 184 ואילך]</i>.\n**) <i>נולד ג' (?) סיון תרס\"ט בעיר ניקאָלאַיעוו</i>.<i> תקופה מסויימת שהה בלענינגראַד</i>.<i> התחבב מאוד על כ\"ק אדמו\"ר מוהריי\"צ – שהי' מקרב אותו</i>,<i> ואף הי' אהוב על החסידים – שהיו סובבים אותו ומתנגחים אתו בדברי הלכה וחסידות</i>.<i> שאלות שונות הופנו אליו</i>,<i> בנגלה ובנסתר</i>.<i> בשנת תר\"צ עזב את בריה\"מ והתיישב באירופא (ברלין)</i>,<i> אח\"כ עלה לאה\"ק – שם התחתן</i>.<i> בשנותיו האחרונות שהה בעיר ליווערפול שבאנגלי'</i>.<i> נפטר בדמי ימיו ביום י\"ג אייר ה'תשי\"ב</i>,<i> וע\"פ בקשת – יבלחט\"א – כ\"ק אדמו\"ר שליט\"א – הועלה ארונו לאה\"ק</i>,<i> ומנ\"כ בעיה\"ק צפת ת\"ו</i>.\n<i>תולדותיו – ראה ספר </i>\"<i>ימי מלך</i>\"<i> ח\"א (קה\"ת תשמ\"ט) ע' 68 ואילך [קובץ י\"ג אייר ארבעים שנה (קה\"ת</i>,<i> תשנ\"ב)]</i>."],["2133","6","תבוא כח, יג."],["2134","7","אוה\"ת לך לך כרך ד תרצו, ב."],["2135","8","ראה שעהיוה\"א פ\"ד (עט, א) \"הגדול היא מדת חסד והתפשטות\". וראה ספר הליקוטים – דא\"ח צ\"צ ערך גדול, גדולה בתחלתו."],["2136","9","ראה בארוכה אוה\"ת ויצא צא, סע\"א ואילך. וראה שם צה, א-ב בענין גדולתי שלמעלה מגדולתכם."],["2137","10","באוה\"ת לך לך שם \"וכן המאור הגדול על שם גדולת הזיו והאור המתפשט ממנו\". ולכאורה הכוונה, דגדולה קאי לא רק על ההתפשטות בפועל (אור), אלא גם על <i>המאור</i> שממנו מתפשט האור. ומזה מובן דקדושה היא בהעצם שלמעלה גם מה\"מאור\", שמובדל <i>מענין</i> ההתפשטות."],["2138","11","ישעי' כט, יט."],["2139","12","נצבים מח, א. שם, ד. וראה גם ד\"ה מי יתנך תרנ\"ד (סה\"מ תרנ\"ד ע' קז ואילך)."],["2140","13","ראה שעהיוה\"א שם השייכות ד\"הגדול (והגבור)\" להוי' (ואלקים)."],["2141","14","כ\"ה להדיא בסה\"מ תרנ\"ד שם ס\"ע קט."],["2142","15","בסה\"מ תרנ\"ד שם השייכות דענינים הנ\"ל להפסוק מי יתנך גו'."],["2143","16","שה\"ש ח, א."],["2144","17","עה\"פ. וראה גם יל\"ש עה\"פ (רמז תתקצג). זהר ח\"א קפד, א."],["2145","18","ויחי נ, כא."],["2146","19","שהש\"ר עה\"פ. וכ\"ה בשמו\"ר רפ\"ה."],["2147","20","באוה\"ת מקץ שמ, סע\"ב ואילך."],["2148","21","הטעם על זה <i>שהמדרש</i> מפרש \"כיוסף לבנימין\" ולא \"כיוסף לאחיו\" הוא, כמפורש בשהש\"ר שם, \"באי זה אח <i>יונק שדי אמי</i>, הוי אומר כיוסף לבנימין\" (וראה אוה\"ת שם). אבל צע\"ק מדוע <i>הבקשה דכנס\"י</i> היא שהקב\"ה יהי' לנו כיוסף לבנימין, דלכאורה היתה צריכה להיות הבקשה שיהי' לנו \"כיוסף לאחיו\", שהוא רבותא טפי."],["2149","22","ראה גם אלשיך עה\"פ (מקץ מב, ו) ויוסף הוא השליט. – הובא באוה\"ת שם."],["2150","23","בה\"רבונו של עולם\" שבסדר ק\"ש שעל המטה."],["2151","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381305\" data-slug=\"likkutei-torah\" data-id=\"4001381305\">לקו\"ת שה\"ש מד, סע\"ב</a> ואילך. והוא משנת תקס\"ה – נדפס (בשינויים וכו') בסה\"מ תקס\"ה ח\"א ע' תפז ואילך, ועם הגהות וכו' – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770306\" data-slug=\"or-hatorah-hb\" data-id=\"8316770306\">אוה\"ת שה\"ש כרך ב ס\"ע תרעד</a> ואילך. וראה גם סה\"מ תרכ\"ו (קה\"ת תשמ\"ט) ע' קג ואילך. ד\"ה מי יתנך תרנ\"ד (סה\"מ תרנ\"ד ס\"ע קד ואילך)."],["2152","25","בד\"ה מי יתנך תרנ\"ד הנ\"ל, דמי יתנך כאח לי הוא כיוסף לבנימין (צדיקים), ואמצאך בחוץ שקאי על בעלי תשובה הוא כענין השבטים שמכרו את יוסף. וצריך ביאור, כי המקור שפסוק זה מדבר ביוסף ואחיו הוא (לכאורה) בפרש\"י ובמדרשי חז\"ל שבהערה 17, ושם קאי זה על מי יתנך כאח לי."],["2153","26","אוה\"ת מקץ שם (שמג, ב). סה\"מ תרנ\"ד ע' קז."],["2154","27","ויגש מז, יד."],["2155","28","לך לך טו, יג."],["2156","29","פרש\"י עה\"פ לך לך שם. מקץ מב, ב."],["2157","30","שהש\"ר פ\"ב, יא."],["2158","31","סוטה יא, רע\"א, הובא בפרש\"י עה\"פ. ב\"ר עה\"פ (פפ\"ד, יג). זח\"א קפד, רע\"א*."],["2159","32","וישב לז, יד."],["2160","33","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370221\" data-slug=\"torah-or\" data-id=\"3901370221\">תו\"א ר\"פ שמות (מט, א</a>. ועם הגהות וכו' – באוה\"ת שמות ע' ז ואילך). תו\"ח ר\"פ שמות. ובכ\"מ."],["2161","34","ויגש מה, ה."],["2162","35","לשון כ\"ק מו\"ח אדמו\"ר בד\"ה ויחלום ה'תש\"ח ספ\"ט (סה\"מ ה'תש\"ח ע' 88). וממ\"ש שם לאח\"ז \"וזהו\"ע הבחירה בקיום התומ\"צ\", מוכח שג\"ז הוא \"ע\"פ ההשגחה כו'\". וראה ד\"ה באתי לגני ה'תשל\"א ס\"ה ואילך, ובהנסמן שם הערה 41 (לעיל ח\"ב ע' שנה)."],["2163","36","ראה בארוכה תו\"ח פ' תולדות ד\"ה ויתן לך פ\"י ואילך (יב, ד ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051078\" data-slug=\"likkutei-sichot\" data-id=\"1300051078\">לקו\"ש ח\"ה ע' 66</a>. ועוד."],["2164","37","לשון הרמב\"ם הל' תשובה פ\"ה ה\"ב.\n*) <i>חילוקי הלשונות בין הזהר והש\"ס (ורש\"י) נתבארו בס' </i>\"<i>תורת מנחם – תפארת לוי יצחק</i>\"<i> (ח\"א</i>,<i> בראשית) סנ\"ב ס\"ג ואילך (ע' קפו-קפז)</i>."],["2165","38","ויגש מה, ז. ולהעיר, שעפ\"ז יומתק שפסוק זה (וישלחני גו' לפליטה גדולה) נאמר <i>לאחרי</i> כי זה שנתים הרעב גו' (ויגש שם, ו) – כי \"שנתים הרעב גו'\" הוא ביאור על \"למחי' שלחני אלקים לפניכם\" (שאמר לפנ\"ז) בשנות הרעב, ואח\"כ הוסיף וישלחני גו' שזה נוגע להזמן שלאח\"ז."],["2166","39","ויגש שם, ח."],["2167","40","ועפ\"ז יובן מ\"ש בתניא ספי\"ב \"וכן דברים שבין אדם לחבירו כו' ללמוד מיוסף עם אחיו\" – ראה בארוכה לקו\"ש ח\"ה ע' 247."],["2168","41","אגה\"ק סכ\"ה (קלח, ב). ולהעיר, דהחיוב לברך על הרעה כשם שמברך על הטובה (ברכות נד, א) הוא (בפשטות) גם כשזה בא ע\"י אדם שהוא בעל בחירה."],["2169","42","ברכות ס, סע\"ב."],["2170","43","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, סע\"א</a>)."],["2171","44","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, סע\"א</a>) \"כמשל בן מלך שהי' בשבי' וטוחן בבית האסורים כו'\"."],["2172","45","בהבא לקמן – ראה בארוכה לקו\"ש ח\"ה ע' 434 ואילך."],["2173","46","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["2174","47","ראה אגה\"ת ספ\"ו ורפ\"ז. ובכ\"מ. וראה סנהדרין מו, א: בשעה שאדם מצטער שכינה מה לשון אומרת כו'."],["2175","48","מקץ מב, כא."],["2176","49","רמב\"ן עה\"פ שם."],["2177","50","ויגש מז, יב. ויחי נ, כא."],["2178","51","ויגש שם, יא."],["2179","52","ירושלמי מכות פ\"ב ה\"ו. יל\"ש יחזקאל רמז שנח. יל\"ש תהלים רמז תשב. וראה בארוכה ד\"ה וכל אדם גו' ה'תשכ\"ג ס\"ד ואילך (לעיל ח\"א ס\"ע עו ואילך)."],["2180","53","ראה כלי יקר עה\"פ מקץ מב, טז \"וכל זה עשה כדי שיכירו בחטאם ויתוודו\"."],["2181","54","אף שאין זה דומה ממש, כנ\"ל סעיף ה."],["2182","55","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יב, א</a>).\nבתניא שם, דזה שזדונות נעשים כזכיות הוא בתשובה מאהבה רבה. אבל ע\"פ מ\"ש בתניא שם שהטעם על זה הוא \"הואיל ועל ידי זה בא לאהבה רבה\", יש לומר, דכיון שכל בעל תשובה (גם כשהתשובה שלו אינה מאהבה רבה) הוא נעלה יותר מצדיק [כמובן מפס\"ד הרמב\"ם שבהערה הבאה*], הרי הטעם שבתניא \"הואיל ועי\"ז בא כו'\" הוא בכל הדרגות דתשובה, ולכן י\"ל שבכללות, הענין דהפיכת זדונות הוא בכל תשובה**, אלא שעיקר הענין הוא בתשובה מאהבה רבה."],["2183","56","רמב\"ם הל' תשובה פ\"ז ה\"ד – כדעת ר' אבהו (ברכות לד, ב)."],["2184","57","ספרי עה\"פ ברכה לג, יב."],["2185","58","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770282\" data-slug=\"or-hatorah-hb\" data-id=\"8316770282\">אוה\"ת שה\"ש כרך ב</a> (ד\"ה מי יתנך) ע' תרנ. סה\"מ תרכ\"ו ע' קיא. ועוד."],["2186","59","רמב\"ם שם.\n*) <i>דמזה שבהדין שבע\"ת הוא למעלה מצדיק אינו אומר שום תנאי</i>,<i> מובן שמדבר בכל בעל תשובה</i>.<i> ועוד</i>,<i> דהטעם על זה שמעלת בע\"ת גדולה יותר ממעלת הצדיקים הוא </i>\"<i>מפני שהם כובשין יצרם יותר</i>\"<i> וטעם זה הוא בכל בע\"ת (ואדרבה</i>,<i> כשהתשובה שלו היא </i>\"<i>באהבה רבה וחשיקה ונפש שוקקה</i>\"<i> (לשון אדה\"ז בתניא שם) אינו כובש את יצרו)</i>.\n**) <i>והא דאיתא בגמרא (יומא פו</i>,<i> ב) שדוקא בתשובה מאהבה נעשים זדונות כזכיות משא\"כ בתשובה מיראה – בדוחק אולי י\"ל שהכוונה שם היא בתשובה מיראת העונש</i>,<i> שבתשובה זו אין גם העילוי דכובש את יצרו</i>.<i> ועצ\"ע</i>."],["2187","60","בהבא להלן ראה גם ד\"ה באתי לגני ה'תשל\"א סעיף יו\"ד ואילך (לעיל ח\"ב ע' שסא ואילך). <i>וש\"נ</i>."],["2188","61","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a> ולקו\"ת ר\"פ פקודי (מזח\"ב קכח, ב. וראה גם שם סז, ב. קפד, א). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370403\" data-slug=\"torah-or\" data-id=\"3901370403\">תו\"א ויקהל פט, ד</a>. לקו\"ת חוקת סה, ג. וראה ד\"ה באתי לגני ה'שי\"ת פ\"א (סה\"מ ה'שי\"ת ע' 111 ואילך)."],["2189","62","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">לקו\"ת שה\"ש טז, ג</a>. ד\"ה מי יתנך ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770266\" data-slug=\"or-hatorah-hb\" data-id=\"8316770266\">אוה\"ת שה\"ש (כרך ב ס\"ע תרלד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770307\" data-slug=\"or-hatorah-hb\" data-id=\"8316770307\">שם ע' תרעה</a>). ובסה\"מ תרנ\"ד (ע' קה). ובכ\"מ."],["2190","63","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>), הובא בלקו\"ת שם. וראה בהנסמן לעיל ח\"א ע' רנח הערה 33."],["2191","64","ב\"ר רפמ\"ד. וש\"נ."],["2192","65","כמה מהענינים דלקמן בנוגע לפסח שני – נעתקו (בקיצור) ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041300\" data-slug=\"likkutei-sichot\" data-id=\"1300041300\">לקו\"ש ח\"ד ס\"ע 1301</a> ואילך."],["2193","66","נדפס באוה\"ת בהעלותך ע' שסז ואילך. וראה ד\"ה זה ה'תשל\"ח – לקמן ע' רסד ואילך."],["2194","67","<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>)."],["2195","68","במדבר ג, א."],["2196","69","במדבר א, א."],["2197","70","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011277\" data-slug=\"likkutei-sichot\" data-id=\"1300011277\">לקו\"ש ח\"א ע' 263</a> ואילך. ובכ\"מ."],["2198","71","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>. ובכ\"מ. – נסמנו לקמן שם הערה 4."],["2199","72","אוה\"ת שם ע' שסח."],["2200","73","פסחים צה, א."],["2201","74","כ\"ה הלשון באוה\"ת שם. וראה לקמן בסוף הסעיף."],["2202","75","תו\"כ, הובא בפרש\"י עה\"פ פרשתנו (קדושים) כ, כו."],["2203","76","לקו\"ת ואתחנן ט, ד. ועוד."],["2204","77","בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381227\" data-slug=\"likkutei-torah\" data-id=\"4001381227\">לקו\"ת שה\"ש כד, ג</a>."],["2205","78","כידוע הראי' על זה ממעין עין עיטם (יומא לא, א. סה\"מ ה'תש\"ג ע' 23. ובכ\"מ)."],["2206","79","הגש\"פ פיסקא \"מצה זו\", מפסחים קטז, ב. שם פיסקא \"ויוציאנו\"."],["2207","80","מלכים-א ו, א. ר\"ה ב, ב."],["2208","81","ראה תנחומא וארא טו. שמו\"ר פי\"ב, ג. ועוד."],["2209","82","ר\"ה יא, א."],["2210","83","ולהעיר מזה שאייר הוא ר\"ת <i>א</i>ברהם <i>י</i>צחק <i>י</i>עקב <i>ר</i>חל (מאו\"א א, פד. בית שמואל לשו\"ע אה\"ע סקכ\"ו ס\"ו)."],["2211","84","שהש\"ר פ\"א, ג (א)."],["2212","85","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380084\" data-slug=\"likkutei-torah\" data-id=\"4001380084\">לקו\"ת ויקרא שם ב, ג</a>."],["2213","86","ד\"ה שנולדו – ר\"ה יא, א."],["2214","87","ר\"ה שם."],["2215","88","ולהעיר מירח שבו נולד משה (מגילה יג, ב), שהגאולה היא בהחודש שבו נולד (אדר) ולא בהחודש שלאחריו."],["2216","89","ראה ד\"ה ויספו ענוים בהוי' שמחה תקס\"ב (סה\"מ תקס\"ב ח\"א ע' נא ואילך). בהנסמן לעיל ח\"א ע' רפב הערות 61-60."],["2217","90","שלכן האביון תאב <i>לכל</i> דבר (פרש\"י עה\"פ ראה טו, ד. תצא כד, יד. ובכ\"מ) כי אין לו שום דבר."],["2218","91","ראה גם לעיל ס\"ח. אלא ששם מדובר בבע\"ת שהוא במדריגה נמוכה שעבודתו היא רק באופן דאתכפיא – והטעם שעי\"ז לא נשלם הענין דדירה בתחתונים כי אינו כלי לאלקות; וכאן מדובר בבע\"ת שהוא במדריגה נעלית – והטעם שאינו משלים הענין דדירה בתחתונים הוא לפי שהוא <i>למעלה</i> מענין המציאות."]]],[1500380040,"<h3>בס\"ד. ש\"פ אמור, י\"ג אייר ה'תשכ\"ה<sup data-n=\"2219\">*</sup></h3>\n<b>ונקדשתי</b> בתוך בני ישראל אני ה' מקדישכם<sup data-n=\"2220\">1</sup>, ומבאר אדמו\"ר הזקן בלקו\"ת ד\"ה זה<sup data-n=\"2221\">2</sup>, דונקדשתי בתוך בני ישראל (גילוי קדושתו ית' בתוך הלב<sup data-n=\"2222\">3</sup> דישראל) הוא באופן דמלמטה למעלה, שלבם של ישראל בוער כרשפי אש ליכלל בקדושתו ית', ועי\"ז נמשך אח\"כ אני הוי' מקדישכם, המשכת קדושתו ית' מלמעלה למטה. ובזה עצמו (בההמשכה מלמעלה למטה) שני ענינים, ההמשכה ע\"י תורה וההמשכה ע\"י מצוות<sup data-n=\"2223\">4</sup>. דההמשכה שע\"י תורה היא בפנימיות העולמות (ברוחניות), ובכדי שתהי' ההמשכה בחיצוניות העולמות (בגשמיות), הוא ע\"י מעשה המצוות<sup data-n=\"2224\">5</sup>. וזהו מ\"ש ג' פעמים קדוש<sup data-n=\"2225\">6</sup>, דקדוש הא' הוא העלאה מלמטה למעלה, וקדוש הב' והג' הם המשכות מלמעלה למטה, ע\"י תורה וע\"י מצוות<sup data-n=\"2224\">5</sup>.\nב) <b>וממשיך</b> ב(הביאור ל)המאמר<sup data-n=\"2226\">7</sup>, שג' פעמים קדוש הם ג' מדריגות. קדוש הא' הוא כתר (שלמעלה מחכמה), קדוש הב' הוא כתר דז\"א, וקדוש הג' הוא כתר דמלכות. ויש לומר הביאור בזה ע\"פ הידוע<sup data-n=\"2227\">8</sup> שקדוש (בכלל) קאי על אור הסובב שהוא קדוש ומובדל מהשתלשלות. ולכן עיקר הענין דקדוש (קדוש ה<i>א'</i>) הוא בכתר שלמעלה מהחכמה (כי חכמה היא ראשית ההשתלשלות<sup data-n=\"2228\">9</sup>). וזה שגם הכתר דז\"א וכתר דמלכות נק' בשם קדוש, הוא, כי השתלשלות הכתרים היא לא כהשתלשלות עילה ועלול שהעלול הוא מהות אחר מהעילה, כי אם, שכל הכתרים הם מהות אחד<sup data-n=\"2229\">10</sup>, וגם לאחרי ירידת הכתר להיות כתר לז\"א או למלכות, הוא במהותו כמו שהי' קודם(כתר שלמעלה מחכמה). ויש לומר, דזה שמבאר בהמאמר שג' פעמים קדוש הם חלוקים במדריגתם (שקדוש הא' הוא הכתר שלמעלה מחכמה, וקדוש הב' והג' הם הכתר דז\"א ודמלכות), הוא גם ביאור על החילוק באופנם (שקדוש הא' הוא באופן דמלמטה למעלה וקדוש הב' והג' הם באופן דמלמעלה למטה). דהסובב (כתר) עצמו, כיון שהוא קדוש ומובדל לגמרי, הגילוי שלו באדם הוא באופן שהוא מכיר ומרגיש שזהו ענין שמופלא ומובדל ממנו, ולכן הוא משתוקק לצאת ממציאותו וליכלל בהענין המופלא, וכאשר הסובב יורד להיות כתר לז\"א או למלכות, אז הגילוי שלו הוא באופן שנמשך למטה. ועד\"ז הוא בנוגע לקדוש הב' והג', שהחילוק באופן המשכתם הוא מפני שהם חלוקים במדריגתם. דקדוש הב', כיון שהירידה שלו הוא שנעשה כתר לז\"א (דז\"א הוא סוף האצילות<sup data-n=\"2230\">11</sup>), המשכתו היא (רק) בפנימיות העולמות (ע\"י תורה), וקדוש הג', שיורד להיות כתר למלכות (דמלכות היא שרש הנבראים<sup data-n=\"2230\">11</sup>), המשכתו היא (גם) בחיצוניות העולמות (ע\"י מעשה המצוות).\nג) <b>וממשיך</b> ב(הביאור ל)המאמר<sup data-n=\"2231\">12</sup>, דזהו מה דאיתא במדרש<sup data-n=\"2232\">13</sup> (בענין ג' פעמים קדוש), משל לבני מדינה שעשו שלש עטרות למלך, מה עשה המלך, הניח בראשו אחת ושתים בראש בניו, כך בכל יום העליונים מכתירים לפני הקב\"ה שלש קדושות, מה הקב\"ה עושה, נותן בראשו אחת ושתים בראשן של ישראל, הה\"ד<sup data-n=\"2233\">14</sup> כי קדוש אני והתקדישתם והייתם קדושים. היינו דכי קדוש אני הוא העטרה שנותן בראשו, והתקדישתם והייתם קדושים הם שתי העטרות שנתן בראשן של ישראל. ולהעיר, דבמדרש שלפנינו איתא הה\"ד דבר אל כל עדת בני ישראל קדושים תהיו והתקדישתם והייתם קדושים, דלכאורה מזה משמע דשתי העטרות שנתן בראשן של ישראל הם קדושים תהיו (שבסמיכות לכי קדוש אני) ווהתקדישתם והייתם קדושים<sup data-n=\"2234\">15</sup> (שנחשבים שניהם לעטרה אחת). אבל בלקו\"ת מפרש, דשתי העטרות שנתן בראשן של ישראל הם והתקדישתם והייתם קדושים, וקדושים תהיו (שבסמיכות לכי קדוש אני) אינה נמנית בהעטרות.\nד) <b>ויש</b> לבאר זה ע\"פ מה דאיתא במדרש שם<sup data-n=\"2235\">16</sup>, קדושים תהיו יכול כמוני תלמוד לומר כי קדוש אני, קדושתי למעלה מקדושתכם. וכתב הצ\"צ (באוה\"ת ר\"פ קדושים<sup data-n=\"2236\">17</sup>) שזה תמוה. והכוונה בזה (בפשטות) היא, כי איך שייך אפילו קס\"ד שישראל יהיו כמוני. ובלקו\"ת פ' נצבים<sup data-n=\"2237\">18</sup> מבואר, דקדושתכם היא הקדושה שנמשכת ע\"י אתערותא דלתתא דמעשה המצוות, וקדושתי שלמעלה מקדושתכם היא קדושה נעלית ביותר שאין אתערותא דלתתא דמעשה המצוות מגעת שם, ונמשכת ע\"י התשובה.וזהו מה שבעלי תשובה הם למעלה מצדיקים גמורים<sup data-n=\"2238\">19</sup>, כי ע\"י התשובה הם ממשיכים מבחינת קדושתי שלמעלה מקדושתכם, כמבואר בלקו\"ת שם.\n<b>ולכאורה</b> צריך לומר, דהמעלה שבבעלי תשובה על צדיקים גמורים, אף שגם בצדיקים ישנה העבודה דג' פעמים קדוש וקדוש הא' הוא קדוש אני (קדושתי שלמעלה מקדושתכם), הוא, שהגילוי דקדוש הא' בצדיקים הוא באופן דהעלאה למעלה, שמשתוקקים לצאת ממציאותם וליכלל בקדושתו ית' (וזה שנמשך להם כמו שהם למטה הוא רק קדוש הב' והג'), ובבעלי תשובה, גם קדוש הא' הוא באופן דהמשכה למטה. וצריך להבין, איך אפשר שתומשך הקדושה דקדוש אני למטה<sup data-n=\"2239\">20</sup>. וביותר אינו מובן, דבאוה\"ת איתא, שאפילו קס\"ד שיהיו כמוני הוא תמוה, ובלקו\"ת איתא (גם להמסקנא), שע\"י התשובה ממשיכים הקדושה דקדוש אני, דלכאורה הם סברות הפוכות.\n<b>ויש</b> לומר הביאור בזה, דמ\"ש הצ\"צ שזה תמוה, הכוונה בזה היא, שאין לזה מקום בשכל, גם לא בחכמה שלמעלה. דכיון שע\"פ סדר ההשתלשלות [שנקבע כפי שגזרה חכמתו ית'] נברא הוא באין ערוך לבורא, אין שייך אפילו קס\"ד שיהיו כמוני. אבל לגבי עצמות אוא\"ס אין שייך שום גדרים, דמי יאמר לו מה תעשה<sup data-n=\"2240\">21</sup>. וכיון שע\"י התשובה מגיעים בעצמות אוא\"ס שלמעלה מחכמה [כידוע בענין שאלו לתורה כו' שאלו להקב\"ה כו' אמר יעשה תשובה ויתכפר לו<sup data-n=\"2241\">22</sup>, דהמענה יעשה תשובה כו' בא דוקא מהקב\"ה שלמעלה מחכמה דתורה], לכן, ע\"י התשובה, יכול כמוני. ועפ\"ז יומתק מה שמפשטות לשון הכתוב קדושים תהיו <i>כי</i> קדוש אני (שקדוש אני הוא <i>הטעם וההסברה</i> על קדושים תהיו) משמע שהציווי קדושים תהיו הוא שקדושתם של ישראל צריכה להיות בדומה לקדושתו ית', כי ע\"י עבודת התשובה מגיעים לקדושה זו. ולהעיר מהפירוש<sup data-n=\"2242\">23</sup> ביכול כמוני – יכול כמוני בניחותא.\nה) <b>ויש</b> לומר, דשני הביאורים בנוגע להפסוקים שבהם נרמזים שתי העטרות שנתן בראש בניו (אם נכלל בזה גם הפסוק קדושים תהיו) ושני הפירושים ביכול כמוני, תלויים זה בזה. דלהפירוש שיכול כמוני הוא בלשון תמי' – הקדושה דקדושים תהיו נכללת בקדושתכם שלמטה מקדושתי, ולכן, קדושים תהיו הוא בכלל העטרות שנתן בראש בניו, ולהפירוש יכול כמוני בניחותא – הקדושה דקדושים תהיו היא הקדושה דקדוש אני (שהיא העטרה שנטל לעצמו), ושתי העטרות שנתן בראש בניו הם והתקדישתם והייתם קדושים. ומ\"ש במדרש שהקדושה דקדוש אניהיא העטרה שנטל לעצמו, אף שגם קדושה זו נמשכת לישראל, יש לומר, כי המשכת הקדושה דקדוש אני בבעלי תשובה היא (לא מצד המציאות שלהם<sup data-n=\"2243\">24</sup> אלא) לפי שע\"י התשובה מתגלה שרש הנשמה שהוא חד עם העצמות, ונמצא, דגם לאחרי שהעטרה ישנה בישראל, היא בראשו של המלך (ולא ניתנה לאחר, גם לא לבניו).\nו) <b>ויש</b> לומר, דזה שענין ההמשכה דקדושתי שלמעלה מקדושתכם מבואר להדיא בהדרושים דפרשת נצבים משא\"כ בהדרושים דפרשתנו בא ענין זה רק ברמז (ומ\"ש להדיא בדרושים אלה הוא שהגילוי דקדוש הא' באדם הוא באופן דהעלאה מלמטה למעלה, שרוצה לצאת ממציאותו וליכלל בקדוש), הוא, כי בפרשת אתם נצבים היום, שקורין קודם ר\"ה<sup data-n=\"2244\">25</sup>, הוא זמן התשובה. ובפרט להמבואר בלקו\"ת<sup data-n=\"2245\">26</sup> שהתשובה דאתם נצבים היום כולכם לפני הוי' גו' הוא שכל הנשמות מתעלות למעלה במקור חוצבם. ולכן בהדרושים דפ' נצבים מבואר להדיא ההמשכה דקדושתי שלמעלה מקדושתכם<sup data-n=\"2246\">27</sup>, כי ע\"י שנש\"י מתעלות למקור חוצבם נמשך להם גם העטרה שנטל לעצמו (כנ\"ל סעיף ה). ובהדרושים דהפרשיות שקורין בימי ספירת העומר, שהעבודה דספירת העומר היא (לא באופן דדילוג (תשובה<sup data-n=\"2247\">28</sup>) אלא אדרבא) בסדר והדרגה (יום אחד, שני ימים, וכו'), בא ענין זה דהמשכת קדושתי שלמעלה מקדושתכם רק ברמז. ויש לומר, דזה שמובא בדרושים אלה ענין זה ברמז עכ\"פ, הוא, כי ספירת העומר הו\"ע בירור נפש הבהמית<sup data-n=\"2248\">29</sup>, ובירור נפש הבהמית הוא כענין התשובה<sup data-n=\"2249\">30</sup>. ויש להוסיף, דפרשת אמור קורין ברוב השנים בהשבת שבסמיכות לפסח שני, דפסח שני הו\"ע התשובה. וכמבואר בארוכה במק\"א<sup data-n=\"2250\">31</sup> דפסח ראשון הו\"ע עבודת הצדיקים ופסח שני הו\"ע עבודת התשובה. ולכן גם בהדרושים דפרשת אמור מרומז הענין דהמשכת קדושתי שלמעלה מקדושתכם, יכול כמוני בניחותא.\n**********",[["2219","*","יצא לאור ב<b>קונטרס י\"ג אייר – תש\"נ</b>, \"לקראת י\"ג אייר, יום היאָרצייט של הוו\"ח וכו' הרב ישראל ארי' לייב, אחיו של – יבדל לחיים טובים – כ\"ק אדמו\"ר שליט\"א, – לפני מלחה\"ע האחרונה עלה לארץ הקודש. נסתלק בי\"ג אייר ה'תשי\"ב, בליווערפול, אנגלי', ומנ\"כ בעיה\"ק צפת תובב\"א* . . <i>יום ג</i>,<i> יג אייר</i>,<i> שנת ה'תש\"נ</i>\"."],["2220","1","פרשתנו כב, לב."],["2221","2","סעיף ט (לג, ב)."],["2222","3","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380216\" data-slug=\"likkutei-torah\" data-id=\"4001380216\">לקו\"ת שם סעיף ה (לב, ג</a>) דתוך בני ישראל הוא נקודה הפנימית דהלב."],["2223","4","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת שם</a> סוף סעיף ו (לב, ד)."],["2224","5","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380218\" data-slug=\"likkutei-torah\" data-id=\"4001380218\">לקו\"ת שם סעיף ח (לג, א</a>). ושם, ש\"לכן הן ב' בחי' קדוש\" (כדלקמן בפנים)."],["2225","6","ישעי' ו, ג."],["2226","7","לג, סע\"ב ואילך."],["2227","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. ובכ\"מ."],["2228","9","שער היחוד והאמונה רפ\"ט. ובכ\"מ."],["2229","10","ראה המשך תער\"ב ח\"א פע\"ט. ח\"ב פש\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380524\" data-slug=\"likkutei-torah\" data-id=\"4001380524\">לקו\"ת קרח נב, ג</a>. ובכ\"מ.\n*) <i>תולדותיו – ראה ספר </i>\"<i>ימי מלך</i>\"<i> ח\"א (קה\"ת תשמ\"ט) ע' 68 ואילך [קובץ י\"ג אייר ארבעים שנה (קה\"ת, תשנ\"ב)]</i>.\n<i>וראה בארוכה שיחת ש\"פ אחרי-קדושים</i>,<i> י\"ג אייר ה'תשמ\"ה [התוועדויות תשמ\"ה ח\"ג ע' 1942 ואילך] – ביאור בשמו של בעל היאָרצייט</i>,<i> והשייכות דשמו לפ' אחרי-קדושים</i>.<i> שיחת פסח שני ה'תשמ\"ז [התוועדויות תשמ\"ז ח\"ג ע' 256 ואילך]</i>.<i> [ש\"פ אחרי-קדושים ה'תנש\"א (התוועדויות תנש\"א ח\"ג ע' 184 ואילך)]</i>."],["2230","11","תו\"א תרומה פא, ב. המשך תרס\"ו ס\"ע רפד ואילך. ובכ\"מ."],["2231","12","סעיף ו (לה, א ואילך)."],["2232","13","ויק\"ר פכ\"ד, ח."],["2233","14","קדושים יט, ב. כ, ח."],["2234","15","וכ\"מ בסה\"מ עזר\"ת ע' קצד. ה'תש\"ח ע' 201."],["2235","16","ויק\"ר שם, ט."],["2236","17","ע' קה."],["2237","18","נא, ג."],["2238","19","ראה ברכות לד, ב. רמב\"ם הל' תשובה פ\"ז ה\"ד."],["2239","20","ולהעיר, שב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380929\" data-slug=\"likkutei-torah\" data-id=\"4001380929\">לקו\"ת נצבים</a> מדבר בדרגא נעלית יותר מבלקו\"ת בפרשתנו. דבלקו\"ת בפרשתנו שקדוש הא' הוא כתר (דבפשטות הוא אריך), ובלקו\"ת נצבים (נב, ג) שקדושתכם שנמשך ע\"י המצוות הוא אריך וקדושתי שלמעלה מקדושתכם הוא עתיק. ואעפ\"כ מבואר שם שגם קדושתי נמשכת למטה."],["2240","21","ע\"פ לשון הכתוב – איוב ט, יב."],["2241","22","יל\"ש תהלים רמז תשב. ועוד. וראה ד\"ה שובה ישראל תרכ\"ט (סה\"מ תרכ\"ט ע' שלח ואילך). ד\"ה טוב וישר תרס\"ד (סה\"מ תרס\"ד ע' רעא ואילך). ד\"ה ביוהשמע\"צ תער\"ב (סה\"מ תער\"ב-תרע\"ו ע' לב). ועוד."],["2242","23","מאור עינים עה\"פ (מז, ב)."],["2243","24","כי הגילוי דקדוש הא' (קדוש אני) ששייך למציאות האדם הוא רק באופן דהעלאה (שירצה ליכלל) ולא באופן דהמשכה."],["2244","25","תוס' – מגילה לא, סע\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380895\" data-slug=\"likkutei-torah\" data-id=\"4001380895\">לקו\"ת ר\"פ נצבים (מד, א</a>)."],["2245","26","שם."],["2246","27","ואולי י\"ל, דזהו גם מהביאורים ע\"ז שבלקו\"ת נצבים גם הדרגא דקדושתכם שע\"י המצוות היא נעלית יותר (ראה לעיל הערה 20) – כי ע\"י התשובה, התומ\"צ הם באופן נעלה יותר."],["2247","28","ראה לקו\"ת דרושים לשבת שובה סה, א. ד\"ה שובה ישראל ה'תשל\"ו (לעיל ח\"א ע' פג ואילך)."],["2248","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380229\" data-slug=\"likkutei-torah\" data-id=\"4001380229\">פרשתנו לה, ד</a>. הנסמן לקמן ע' רסד הערה 4."],["2249","30","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו\"א מקץ לג, ב</a>. ושם, שלכן ע\"י בירור נה\"ב נמשך הגילוי דקדושתי שלמעלה מקדושתכם. וראה שם לד, ריש ע\"ג בענין ספירת העומר."],["2250","31","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101119\" data-slug=\"likkutei-sichot\" data-id=\"1300101119\">לקו\"ש חלק ח\"י ע' 119</a> ואילך. ובכ\"מ."]]],[1500380041,"<h3>בס\"ד. מוצאי ש\"ק פ' אמור, י\"ג אייר<sup data-n=\"2251\">*</sup>, אור לי\"ד אייר, פסח שני, ה'תשל\"ח<sup data-n=\"2252\">**</sup></h3>\n<b>להבין</b> ענין פסח שני, ומבאר אדמו\"ר הצ\"צ במאמרו ד\"ה זה<sup data-n=\"2253\">1</sup>, דענין פסח שני יובן ע\"פ שלשה הקדמות. הקדמה הא' היא ההפרש בין חודש הראשון (ניסן) וחודש השני (אייר) בעבודת האדם. דבחודש ניסן, שהנקודה בו היא יציאת מצרים, היא העבודה דסור מרע, היינו שהרע הוא בתקפו והעבודה היא להיות סור מרע, לצאת ולברוח מהרע, אתכפיא<sup data-n=\"2254\">2</sup>. והעבודה דחודש אייר [דענינו המיוחד של חודש זה שבו הוא נבדל משאר החדשים הוא שבכל יום בו ישנה מצוה מיוחדה (דספירת העומר)<sup data-n=\"2255\">3</sup>] היא העבודה דספירת העומר, שענינה הוא<sup data-n=\"2256\">4</sup> בירור המדות והפיכתם לקדושה, אתהפכא. וזהו מ\"ש<sup data-n=\"2257\">5</sup> באחד לחודש השני גו' לצאתם מארץ מצרים, דעבודה הראשונה דיציאת מצרים, חודש הראשון, היא אתכפיא סט\"א, ולאח\"ז באה העבודה דאתהפכא, עבודה שני' ביציאת מצרים, חודש השני<sup data-n=\"2258\">6</sup>. והקדמה הב' היא החילוק בין שני חדשים אלו בענין הספירות. דחודש הראשון הוא במלכות, ספירה הראשונה מלמטה למעלה, וחודש השני הוא ביסוד, ספירה השני'<sup data-n=\"2259\">7</sup>. ומבאר בהמאמר, דשני הקדמות אלו [ענינם של ניסן ואייר בעבודת האדם, וענינם בספירות] שייכים זה לזה, כמבואר בתו\"א ד\"ה והנה אנחנו מאלמים אלומים<sup data-n=\"2260\">8</sup> דהבירור שע\"י השבטים (שהיו מרכבה לבחינת המלכות), בירור ראשון, הוא רק ביטול היש (דוגמת אתכפיא<sup data-n=\"2261\">9</sup>), והבירור שע\"י יוסף הצדיק, בחינת יסוד, בירור שני, הוא שיהי' נכלל באלקות, ביטול במציאות (דוגמת אתהפכא<sup data-n=\"2261\">9</sup>). והקדמה הג' היא, דענין פסח, פסח מלשון דילוג וקפיצה<sup data-n=\"2262\">10</sup>, הוא המשכה נעלית ביותר שאינה יכולה לבוא בדרך השתלשלות ורק בדרך דילוג, כמבואר בלקו\"ת<sup data-n=\"2263\">11</sup>. ומבאר בהמאמר, דמזה מובן, שגם ענינו של פסח שני<sup data-n=\"2264\">12</sup>הוא דילוג, המשכה שלמעלה מהשתלשלות. והחילוק בין פסח ראשון ופסח שני הוא בהמקום ובהענין שבו נמשכת המשכה זו. דבפסח ראשון כתיב<sup data-n=\"2265\">13</sup> ופסח הוי' על הפתח, שההמשכה שבדרך דילוג (ופסח) היתה בפתח, ספירת המלכות<sup data-n=\"2266\">14</sup>, ובנפש האדם – ביראה תתאה (זה השער להוי'<sup data-n=\"2267\">15</sup>) שהיא השורש דסור מרע<sup data-n=\"2268\">16</sup>, וההמשכה שבדרך דילוג שבפסח שני היא בספירת היסוד, שענינה בנפש האדם הוא ההתקשרות והאהבה<sup data-n=\"2269\">17</sup>, שעי\"ז נהפכים המדות שלו לקדושה, אתהפכא.\nב) <b>ואולי</b> יש להוסיף, שהמעלה דפסח שני לגבי פסח ראשון היא לא רק שהדילוג דפסח שני נמשך במקום נעלה יותר, אלא שגם הדילוג עצמו הוא דילוג נעלה יותר. וכמובן גם מזה שנקרא בשם פסח שני, דפירוש הפשוט דפסח שני הוא לא (רק) שהפסח (הדילוג) נמשך בדרגא דשני אלא ש(גם) <i>הפסח</i> (הדילוג) הוא שני, דילוג נעלה יותר מהדילוג דפסח ראשון. ומ\"ש בהמאמר דפירוש פסח שני הוא שהדילוג דפסח שני נמשך בהדרגא דשני (יסוד), הוא, כי מעלת הדילוג דפסח שני (שהדילוג הוא נעלה יותר) נראה (גם) בזה שהדילוג נמשך בהדרגא דשני (כדלקמן סעיף ה).\n<b>ועפ\"ז</b> יש לקשר הביאור הנ\"ל (דהצ\"צ) שפסח שני הוא דרגא שני' ונעלית בעבודה הבאה <i>לאחרי</i> הקדמת העבודה דפסח ראשון, עם הענין דפסח שני כמו שהוא בפשטות, שהוא תיקון והשלמה למי שלא הקריב פסח<sup data-n=\"2270\">18</sup>, כי זה שפסח שני מתקן ומשלים החסרון דזה שלא הקריב פסח הוא מפני שהגילוי דפסח שני הוא דילוג שלא בהדרגה, שאין בו מדידות והגבלות, גם לא המדידות וההגבלות של הדילוג דפסח (ראשון)<sup data-n=\"2271\">19</sup>, ולגבי גילוי זה – \"איז ניטאָ קיין פאַרפאַלן\"<sup data-n=\"2272\">20</sup>.\nג) <b>ויובן</b> זה בהקדים הידוע<sup data-n=\"2273\">21</sup> דמהחילוקים בין ז\"א למלכות הוא, שהמלכות היא קצה העליון (מקור) דבי\"ע, וז\"א הוא קצה התחתון דאצילות. וכיון שבאצילות לא יגורך רע<sup data-n=\"2274\">22</sup>, מובן דזה שע\"י היסוד (ז\"א) נעשה שלימות הבירור, העניןדאתהפכא, הוא כמו שהוא נמשך לברר<sup data-n=\"2275\">23</sup>, ועיקר העבודה שמצד ז\"א הוא (לא ענין הבירורים, אלא) להמשיך אור<sup data-n=\"2276\">24</sup>. וכמו שהוא בנוגע לספירת היסוד (ענינו של חודש השני בספירות), עד\"ז הוא גם בנוגע להעבודה דספירת העומר (ענינו של חודש השני בעבודת האדם), שעיקר ענינה (לפי ביאור אחד<sup data-n=\"2277\">25</sup>) הוא לא בירור המדות דנפש הבהמית אלא המשכת מ\"ט שערי בינה, ועד שעי\"ז נמשך גם שער הנו\"ן<sup data-n=\"2278\">26</sup>. ויש לומר, דזהו גם מה שאייר הוא ר\"ת אברהם יצחק יעקב רחל<sup data-n=\"2279\">27</sup>, שהם ד' רגלי המרכבה, שהביטול דמרכבה הוא באופן שמלכתחילה אין מקום לענין של ישות ומכ\"ש לרע שצריך לפעול בו ביטול, וכמבואר בתניא<sup data-n=\"2280\">28</sup> בענין האבות הן הן המרכבה<sup data-n=\"2281\">29</sup> שלא נעשו מרכבה רק לרצון העליון לבדו <i>כל ימיהם</i>.\nד) <b>ומכל</b> זה מובן, דבחודש אייר, חודש השני, שני ענינים. העבודה דאתהפכא, תכלית השלימות דסור מרע<sup data-n=\"2282\">30</sup>, והעבודה דילכו מחיל אל חיל<sup data-n=\"2283\">31</sup> בקדושה עצמה, ועשה טוב<sup data-n=\"2284\">32</sup>. ויש לומר, דזהו שהמנין דבנ\"י בחודש השני בשנה השנית לצאתם מארץ מצרים הי' ע\"י משה ואהרן<sup data-n=\"2285\">33</sup>, כי הענין דסור מרע (שבחודש השני) שייך לאהרן שענינו הוא אוהב שלום ורודף שלום כו'<sup data-n=\"2286\">34</sup>, דענין השלום הוא לשלול המחלוקת והפירוד, והענין דועשה טוב (שבחודש אייר) שייך למשה שענינו הוא תורה<sup data-n=\"2287\">35</sup>, שמלכתחילה אין שייך בה נתינת מקום לענין הפכי ח\"ו<sup data-n=\"2288\">36</sup>, דזהו גם מ\"ש<sup data-n=\"2289\">37</sup> ותרא אותו כי <i>טוב</i> הוא שמיד כשנולד נתמלא הבית כולו אורה<sup data-n=\"2290\">38</sup>.<b>ויש</b> לומר, דזה שיציאת מצרים היתה ע\"י אהרן ומשה<sup data-n=\"2291\">39</sup>, אף שהעבודה דיציאת מצרים היא סור מרע, ובסור מרע גופא באופן דאתכפיא, הוא, כי גם העבודה דאתכפיא צריכה להיות באופן שתביא לא רק לאתהפכא, אלא גם להעבודה בהקו דועשה טוב שלמעלה מענין הבירורים. וי\"ל שהוא ע\"ד המבואר בתניא<sup data-n=\"2292\">40</sup> שגם אלו שעיקר עבודתם הוא אל תהי רשע<sup data-n=\"2293\">41</sup>, צריכים להשתדל לקיים את השבועה<sup data-n=\"2293\">41</sup> תהי צדיק, הן בנוגע להיות מואס ברע (הענין דאתהפכא) והן בנוגע להתענג ולשמוח בה' ע\"י התבוננות בגדולת א\"ס ב\"ה (העבודה דקדושה שלמעלה מענין הבירורים).\nה) <b>והנה</b> עד\"ז הוא לאידך גיסא, שגם כשנמצאים בהעבודה דחודש אייר (העבודה דאתהפכא, ולמעלה יותר העבודה דמרכבה) צריך להיות רושם מהחיות וההתפעלות של העבודה דאתכפיא, שלכן מזכירין<sup data-n=\"2294\">42</sup> יציאת מצרים גם לימות המשיח<sup data-n=\"2295\">43</sup>. והענין הוא, דכשהרע הוא בתקפו, הנה היראה מהרע גורמת הבריחה ממנו באופן דחפזון<sup data-n=\"2296\">44</sup>. וע\"י החפזון דישראל נעשה גם חפזון השכינה<sup data-n=\"2297\">45</sup> כביכול, מדלג על ההרים מקפץ על הגבעות<sup data-n=\"2298\">46</sup>. דחפזון מביא לדילוג שלמעלה מסדר והדרגה. משא\"כ העבודה דאתהפכא לאחרי שיצא כבר מהרע, ומכ\"ש העבודה דועשה טוב, היא בסדר והדרגה. ולכן צריך להמשיך בה ענין הדילוג דיציאת מצרים. וזהו\"ע פסח שני, המשכת הדילוג בהעבודה דועשה טוב, העבודה דחודש השני. שלאחרי הדילוג שהי' בהעבודה דסור מרע (פסח ראשון), נמשך הדילוג גם בהעבודה דועשה טוב (פסח שני). וע\"ד מ\"ש<sup data-n=\"2299\">47</sup> משכני אחריך נרוצה, דע\"י שנפש האלקית פועלת שנפש הבהמית יהי' לה אהבת ה', שהאהבה דנפש הבהמית היא בדרך מרוצה, עי\"ז נעשה מרוצה גם בנפש האלקית<sup data-n=\"2300\">48</sup>,נרוצה לשון רבים<sup data-n=\"2301\">49</sup>. אבל, לאחרי שנמשך הדילוג בהעבודה דועשה טוב, דילוג זה הוא נעלה יותר מהדילוג דפסח. כי הוא מחמת היראה מהרע (ענין בפ\"ע), משא\"כ הדילוג שבתומ\"צ (העבודה דועשה טוב) הוא מפני שהם חכמתו ורצונו של הקב\"ה, בלי גבול האמיתי. ולכן, לאחרי שמתגלה הבל\"ג שבהם ע\"י הדילוג דסור מרע, הדילוג (ענין הבל\"ג שלמעלה מהדרגה) דהעבודה דועשה טוב הוא דילוג גדול יותר<sup data-n=\"2302\">50</sup>.\n<b>ועפ\"ז</b> יובן גם הפתגם של כ\"ק מו\"ח אדמו\"ר<sup data-n=\"2303\">51</sup> שפסח שני שייך לנפש השנית, כי מעלת הדילוג דפסח שני על הדילוג דפסח ראשון הוא, שהדילוג דפסח ראשון הוא מצד ההעלם וההסתר דנפש הבהמית (נפש הראשונה), והדילוג דפסח שני הוא שמתגלה הבל\"ג דנפש השנית שהיא חלק אלוקה ממעל ממש<sup data-n=\"2304\">52</sup>. שגם בהיותה מלובשת בגוף, היא חלק אלוקה ממעל ממש מלשון מישוש<sup data-n=\"2305\">53</sup>.\nו) <b>ואולי</b> יש להוסיף, שמעלת הדילוג דפסח שני על הדילוג דפסח ראשון הוא באין ערוך, ועד שהוא דילוג גם לגבי הדילוג דפסח (ראשון). וע\"ד מ\"ש<sup data-n=\"2306\">54</sup> כימי צאתך מארץ מצרים אראנו נפלאות, שהגילויים דגאולה העתידה יהיו נפלאות גם לגבי הנפלאות שהיו ביציאת מצרים<sup data-n=\"2307\">55</sup>. וביאור הענין (השייכות דפסח שני לגאולה העתידה<sup data-n=\"2308\">56</sup>) בפרטיות יותר, הנה איתא במדרש<sup data-n=\"2309\">57</sup> שגאולת מצרים [וכן הגאולה מגלות בבל ושאר הגאולות עד להגאולה דלעתיד] היא דוגמת אור הנר, וגאולה העתידה היא כמו אור השמש שאינו נכבה. ומבואר בחסידות<sup data-n=\"2310\">58</sup>, דזה שגאולת מצרים נמשלה לאור הנר, הוא, כי נר הוא בחינת מלכות, והגילוי שהי' בגאולת מצרים, עם היותו גילוי שלמעלה מהשתלשלות, הי' בהתלבשות בבחינת המלכות, כמ\"ש ופסח הוי' על הפתח, דפתחהוא מלכות (כנ\"ל סעיף א). ומזה מובן, דזה שהגאולה העתידה נמשלה לאור השמש הוא כי הגילוי דלמעלה מהשתלשלות שיהי' אז יהי' בבחינת ז\"א<sup data-n=\"2311\">59</sup>. וזוהי השייכות דפסח שני לגאולה העתידה, כי הגילוי דפסח שני הוא ביסוד ז\"א, כנ\"ל.\nז) <b>ויהי</b> רצון, שמעשינו ועבודתינו<sup data-n=\"2312\">60</sup>, ובפרט בהענינים השייכים לפסח שני, יקרבו וימהרו עוד יותר הגאולה העתידה, שגם הגאולה העתידה תהי' באופן של דילוג, כדאיתא במדרש<sup data-n=\"2313\">61</sup> דקול דודי גו' מדלג על ההרים זה מלך המשיח, ואדרבא, בגאולה העתידה יהי' דילוג גדול יותר (דוגמת (אבל למעלה מ)הדילוג דפסח שני שהוא דילוג גדול יותר מהדילוג דפסח ראשון), שלא תהי' בסדר והדרגה מדרגא לדרגא כלל<sup data-n=\"2314\">62</sup>, כהפס\"ד<sup data-n=\"2315\">63</sup> <i>מיד</i> הן נגאלין, בביאת משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n**********",[["2251","*","יאָרצייט דהוו\"ח וכו' הרב ישראל ארי' לייב, אחיו של – יבדל לחיים טובים – כ\"ק אדמו\"ר שליט\"א."],["2252","**","יצא לאור ב<b>קונטרס פסח שני – תשמ\"ט</b>, \"לקראת פסח שני הבעל\"ט – הננו מוציאים לאור . . <i>מוצש\"ק אמור תשמ\"ט</i>\"."],["2253","1","נדפס באוה\"ת בהעלותך ע' שסז ואילך."],["2254","2","<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>)."],["2255","3","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011277\" data-slug=\"likkutei-sichot\" data-id=\"1300011277\">לקו\"ש ח\"א ע' 263</a> ואילך. ובכ\"מ."],["2256","4","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380086\" data-slug=\"likkutei-torah\" data-id=\"4001380086\">לקו\"ת ויקרא ג, א</a>. אמור ד\"ה וספרתם (לה, ד). במדבר ביאור לד\"ה ואהי' אצלו אמון (יט, א ואילך). <i>ועוד</i>. מאמרי אדמו\"ר האמצעי במדבר ח\"ב ד\"ה להבין ענין הספירה (ע' תמו. שם ע' תפט ואילך). <i>ועוד</i>."],["2257","5","במדבר א, א."],["2258","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380320\" data-slug=\"likkutei-torah\" data-id=\"4001380320\">לקו\"ת במדבר ג, א</a>."],["2259","7","זהר ח\"ג קיז, ב – הובא בלקו\"ת שם ובאוה\"ת בהעלותך שם."],["2260","8","וישב כח, א-ב."],["2261","9","ראה סה\"מ תקס\"ה ח\"ב ע' א'יד (הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת בהעלותך שם</a>) שמ\"ן (בירור ראשון) הוא אתכפיא, וע\"י המשכת מ\"ד (בירור שני) נעשה אתהפכא."],["2262","10","פרש\"י עה\"פ בא יב, יא. שם, יג. וראה מכילתא עה\"פ שם, יג."],["2263","11","שה\"ש ד\"ה קול דודי פ\"ג (טו, סע\"א ואילך). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380131\" data-slug=\"likkutei-torah\" data-id=\"4001380131\">לקו\"ת צו יג, ד</a>. ובכ\"מ."],["2264","12","כשמו – פסח שני."],["2265","13","בא שם, כג. וראה לקו\"ת שה\"ש שם, ב. ד\"ה כימי צאתך ה'תש\"ח פי\"א (סה\"מ ה'תש\"ח ע' 164)."],["2266","14","זהר ח\"ב לו, סע\"א. לקו\"ת וסה\"מ ה'תש\"ח שם."],["2267","15","תהלים קיח, כ. זהר ח\"א ז, ב. קונטרס העבודה ספ\"ב (ע' 17)."],["2268","16","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא ריש פמ\"א</a>. וראה גם שם פ\"ד בתחלתו. ובכ\"מ."],["2269","17","כ\"ה באוה\"ת בהעלותך שם (ע' שסח). וראה אגה\"ק סט\"ו (קכג, ב). ובכ\"מ."],["2270","18","ראה פסחים צג, א. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181135\" data-slug=\"likkutei-sichot\" data-id=\"1300181135\">לקו\"ש חי\"ח</a> שיחה ג' לפ' בהעלותך (ע' 126 ואילך), שגם לדעת רבי (פסחים שם), וכ\"ה ההלכה (רמב\"ם הל' קרבן פסח רפ\"ה) שפסח שני רגל בפני עצמו הוא – <i>ענינו</i> של פסח שני הוא תשלומין לחסרון דראשון, שלכן כל מי שעשה את הראשון <i>אינו</i> עושה את השני."],["2271","19","ועפ\"ז יובן זה שלדעת רבי (וכ\"ה ההלכה) גר שנתגייר בין פסח ראשון לפסח שני מביא פסח שני – אף שגם לדעת רבי עיקר הזמן דהקרבת הפסח הוא בפסח ראשון (והענין דפסח שני הוא רק תשלומין להחסרון דפסח ראשון, כבהערה הקודמת), ואז (בפסח ראשון) לא הי' שייך לענין פסח – כי מכיון שע\"י הדילוג דפסח שני מתבטלים גם המדידות וההגבלות דפסח ראשון, לכן היכולת להשלים החסרון הוא גם בזה שבעת פסח ראשון לא הי' זה אצלו בגדר \"חסרון\"."],["2272","20","\"היום יום\" יד אייר, פסח שני (משיחת פסח שני ה'תש\"א ס\"ה – סה\"ש ה'תש\"א ע' 115)."],["2273","21","תו\"א תרומה פא, ב. המשך תרס\"ו ס\"ע תרפד ואילך. ובכ\"מ."],["2274","22","תהלים ה, ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, סע\"ג</a>. מאמרי אדמו\"ר האמצעי דברים ח\"ד ע' א'תצג. <i>וש\"נ</i>."],["2275","23","ראה המשך תער\"ב ח\"ב ע' א'מט. שם ע' א'עא."],["2276","24","להעיר מאגה\"ק סכ\"ו (קמד, ב ואילך), שאפילו מצד המלכות – ענין הבירורים הוא דוקא \"בזמן גלות השכינה\", \"אבל בצאת השכינה מקליפת נוגה . . אזי לא יהי' עסק התורה והמצוות לברר בירורין כ\"א . . להמשיך אורות עליונים\"."],["2277","25","ראה ד\"ה להבין ענין ספה\"ע ה'תשמ\"ז (התוועדויות תשמ\"ז ח\"ג ע' 310 ואילך), שבהדרושים המדברים בענין ספה\"ע – ג' ביאורים: א) שהעבודה דספה\"ע יש בה ב' הקוין, דסור מרע ודועשה טוב. ב) שהעבודה דספה\"ע היא רק בהקו דסור מרע. ג) שהיא רק בהקו דועשה טוב."],["2278","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">לקו\"ת במדבר יב, א</a>. ובכ\"מ."],["2279","27","מאורי אור מערכת א' אות פד. ב\"ש לאה\"ע סקכ\"ו ס\"כ. מגלה עמוקות אופן קכא."],["2280","28","פכ\"ג (כח, ב)."],["2281","29","ב\"ר פמ\"ז, ו. פפ\"ב, ו. וראה מאמרי אדמו\"ר האמצעי דברים ח\"א ע' רטו. וש\"נ."],["2282","30","וכנ\"ל ס\"א (מלקו\"ת) שהיא עבודה השני' <i>ביציאת מצרים</i>. ובאוה\"ת שם (ע' שסז) דהיציאה ממצרים בחודש הראשון הוא \"סור מרע <i>גמור</i>\", ובאייר \"הוא בחי' שנית, לצאת אפילו <i>מק\"נ</i>\"."],["2283","31","תהלים פד, ח."],["2284","32","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380612\" data-slug=\"likkutei-torah\" data-id=\"4001380612\">לקו\"ת בלק עג, סע\"ג</a> ואילך, שע\"י העבודה דועשה טוב ממשיכים \"טוב העליון שהוא <i>היסוד</i>\" (ענינו של חודש אייר).\nוע\"פ המבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380613\" data-slug=\"likkutei-torah\" data-id=\"4001380613\">לקו\"ת שם (עג, ד</a>) שע\"י העבודה דועשה טוב \"מתקן ההסתר הנמשך מהצמצום דשם אלקים\", ו\"כשאין עושה טוב כדבעי גורם התגברות הדינין\" – יומתק זה שהעבודה בחודש אייר (גם להביאור שהעבודה דאייר היא ועשה טוב) היא עבודה שני' <i>ביציאת מצרים</i>."],["2285","33","כמ\"ש (במדבר א, ג) תפקדו אותם לצבאותם <i>אתה ואהרן</i>."],["2286","34","אבות פ\"א מי\"ב."],["2287","35","כמ\"ש \"זכרו תורת משה עבדי\" – מלאכי ג, כב. וראה שבת פט, א. שמו\"ר פ\"ל, ד. וש\"נ."],["2288","36","דדברי תורה אינן מקבלין טומאה – ברכות כב, א."],["2289","37","שמות ב, ב."],["2290","38","פרש\"י עה\"פ, מסוטה יב, א. שמו\"ר פ\"א, כ. ועוד."],["2291","39","ראה וארא ו, כו-כז. וראה ספר הערכים-חב\"ד ערך אהרן ביחס למשה ס\"י (ע' קעג ואילך). <i>וש\"נ</i>."],["2292","40","פי\"ד (כ, א)."],["2293","41","נדה ל, סע\"ב."],["2294","42","ברכות יב, סע\"ב."],["2295","43","וכמשנת\"ל בד\"ה ובראשי חדשיכם דמוצאי ש\"פ אחרי, מבה\"ח וער\"ח אייר שנה זו (תשל\"ח)."],["2296","44","וכמו שהי' ביציאת מצרים, כמ\"ש (ראה טז, ג) \"כי בחפזון יצאת מארץ מצרים\". וראה ד\"ה וככה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460302\" data-slug=\"or-hatorah-hb\" data-id=\"8316460302\">אוה\"ת בא ס\"ע רצא</a> ואילך. שם ס\"ע שב ואילך. כרך ח ס\"ע ב'תתקמ ואילך. המשך וככה תרל\"ז בתחילתו (פ\"ב). סד\"ה וככה תער\"ב (סה\"מ תער\"ב-ע\"ו ע' קסו). ד\"ה כימי צאתך ה'תש\"ח פי\"ג (סה\"מ ה'תש\"ח ע' 167)."],["2297","45","ראה ברכות ט, א. מכילתא עה\"פ בא שם, יא. יל\"ש עה\"פ (רמז קצט). יל\"ש ישעי' עה\"פ (ישעי' נב, יב) כי לא בחפזון תצאו (רמז תעו). ובתיב\"ע עה\"פ בא שם: בבהילו דשכינת מארי עלמא. וראה ד\"ה וככה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460291\" data-slug=\"or-hatorah-hb\" data-id=\"8316460291\">אוה\"ת שם ע' רצא</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460298\" data-slug=\"or-hatorah-hb\" data-id=\"8316460298\">שם ע' רחצ</a> ואילך. כרך ח ע' ב'תתקלד ואילך. המשך וככה הנ\"ל בתחילתו (פרקים א-ג) ובסופו (פקכ\"ט ואילך). ד\"ה וככה תער\"ב (סה\"מ תער\"ב-ע\"ו ע' קנח ואילך). ד\"ה כי בחפזון ה'תש\"ח פ\"א-ב (סה\"מ ה'תש\"ח ע' 151 ואילך). ד\"ה וככה ה'תשל\"ז (סה\"מ תשל\"ז ע' 192 ואילך)."],["2298","46","שה\"ש ב, ח. מדרשים שבהערה הקודמת."],["2299","47","שה\"ש א, ד."],["2300","48","להעיר ש\"משכני\" (דקאי על יצי\"מ*) הוא לשון יחיד, וכן \"הביאני המלך חדריו\" (דקאי על מ\"ת*) הוא לשון יחיד – כי הגילוי דיצי\"מ ודמ\"ת הוא בנפש האלקית. ולכן יש לומר, שגם \"אחריך נרוצה\" (שבאמצע), אף ש\"נרוצה\" הוא לשון רבים – ההדגשה בזה שנעשה \"מרוצה\" (גם) בנפש האלקית.\nולהעיר שעפ\"ז יומתק זה ש\"אחריך נרוצה\" לשון רבים (דקאי על ספה\"ע*) הוא הקדמה למתן תורה* –\n*) <i>אוה\"ת שה\"ש עה\"פ ע' נט</i>.<i> ד\"ה משכני ה'תש\"א הא' והב' (סה\"מ ה'תש\"א ע' 93</i>.<i> שם ע' 119)</i>.אף שהבירור דלעו\"ז מגיע רק בבחינת לבוש מלכות ולא בבחינת כתר מלכות (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370411\" data-slug=\"torah-or\" data-id=\"3901370411\">תו\"א מג\"א צא, ב</a>), והרי הגילוי דמ\"ת, \"בעטרה שעטרה לו אמו\" (שה\"ש ג, יא) הוא בחי' כתר מלכות (כמבואר בתו\"א שם) – דיש לומר הביאור בזה, דזה שע\"י \"אחריך נרוצה\" באים ל\"הביאני המלך חדריו\" הוא (לא מצד הבירור והמרוצה דנפש הבהמית, אלא) מצד המרוצה <i>דנפש האלקית</i> (שנעשה ע\"י המרוצה דנה\"ב)."],["2301","49","ד\"ה ציון במשפט ה'תשמ\"א ס\"ו, ובהנסמן שם הערה 47 (לקמן ח\"ד ע' קנ)."],["2302","50","ראה עד\"ז אוה\"ת שמע\"צ ע' א'תתו, דהגם שהעלי' דנפש האלקית היא ע\"י בירור נה\"ב, מ\"מ, העלי' דנפש האלקית היא למעלה מהשרש דנה\"ב, לכי לך לעצמותך."],["2303","51","שיחת פסח שני ה'תש\"א הנ\"ל שם (סה\"ש שם ע' 114)."],["2304","52","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["2305","53","אגרות-קודש כ\"ק אדמו\"ר מוהריי\"צ ח\"ד אגרת א'נו (ע' תז). וראה \"היום יום\" כג מנחם אב (מאגרת הנ\"ל – ע' תד). מכתב כ\"ב אייר ה'תשי\"א*."],["2306","54","מיכה ז, טו."],["2307","55","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600487\" data-slug=\"or-hatorah-hb\" data-id=\"8316600487\">אוה\"ת נ\"ך</a> עה\"פ סק\"ח (ע' תפז), מפע\"ח שער חג המצות פ\"ז (בד\"ה מהר\"י ז\"ל). וראה ד\"ה כימי צאתך מארץ מצרים דאחש\"פ ה'תשל\"ט (לעיל ע' רד ואילך), ה'תשמ\"ב (לעיל ע' קמז ואילך)."],["2308","56","להעיר שבגאולה העתידה כתיב (ישעי' יא, יא) \"<i>שנית</i>\". וראה רש\"י ורד\"ק שם."],["2309","57","מדרש תהלים עה\"פ (לו, י) כי עמך מקור חיים (הובא בקיצור ביל\"ש עה\"פ (רמז תשכז)). הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460300\" data-slug=\"or-hatorah-hb\" data-id=\"8316460300\">אוה\"ת</a> (יהל אור) עה\"פ (ע' קלח). ד\"ה וככה באוה\"ת בא ע' ש. כרך ח ע' ב'תתקלה. ד\"ה כי בחפזון ה'תש\"ח פ\"ב (סה\"מ ה'תש\"ח ע' 153)."],["2310","58","ד\"ה כימי צאתך ה'תש\"ח (שבהמשך לד\"ה כי בחפזון הנ\"ל) פי\"ב (סה\"מ שם ע' 164 ואילך).\n*) <i>נעתק בליקוט פירושים וכו' לתניא שם אות יא</i>.<i> אגרות-קודש כ\"ק אדמו\"ר שליט\"א ח\"ד ע' רצא</i>. <b>המו\"ל</b>."],["2311","59","ראה גם אוה\"ת (יהל אור) לתהלים שם, ד\"נר\" הוא מלכות ו\"אור\" הוא ז\"א. ולהעיר גם מקונטרס עץ החיים פ\"ב."],["2312","60","לשון התניא רפל\"ז."],["2313","61","שהש\"ר עה\"פ קול דודי (ב)."],["2314","62","להעיר, שגם בענין זה הדילוג שיהי' בגאולה העתידה הוא דילוג גדול יותר. דבגאולת מצרים ארז\"ל (ר\"ה יא, רע\"א) \"בר\"ה בטלה עבודה מאבותינו במצרים\", וברש\"י שם \"ששה חדשים לפני גאולתם פסק השעבוד\". ונמצא שהגאולה דיציאת מצרים לא היתה באופן דמן הקצה אל הקצה [ועד שביטול העבודה שהיתה בר\"ה נק' בשם \"אתחלתא דגאולה\" (רד\"ה החודש עטר\"ת (סה\"מ עטר\"ת ע' שכג) וה'ש\"ת (סה\"מ ה'ש\"ת ע' 20))]. משא\"כ גאולה העתידה תהי' [כפס\"ד הרמב\"ם] באופן של \"מיד\". וי\"ל – למעלה מגדר דקצה."],["2315","63","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1500380042,"<h3>בס\"ד. ל\"ג בעומר ה'תשכ\"ב<sup data-n=\"2316\">*</sup></h3>\n<b>שיר</b> המעלות לדוד הנה מה טוב ומה נעים שבת אחים גם יחד<sup data-n=\"2317\">1</sup>, ומדייק כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"2318\">2</sup>, הרי שבת אחים הוא שיושבים יחד באחוה ובאהבה, ומה מוסיף גם יחד. ומבאר, דאחים הם הנשמות דדכר ונוקבא השייכים זל\"ז<sup data-n=\"2319\">3</sup> (חתן וכלה), ושבת אחים הוא הקירוב וההתקשרות שלהם בקישורי תנאים, וזהו הכנה להנשואין, שאז נעשה (גם) יחד, נוסף על התקשרות גם יחוד.\n<b>וממשיך</b> בהמאמר, דאיתא בזהר<sup data-n=\"2320\">4</sup> שבת אחים גם יחד, קוב\"ה וכנסת ישראל, גם לרבות ישראל דלתתא. ויש לומר, שהשייכות דהפירוש שאחים הם חתן וכלה עם מאמר הזהר דקאי על קוב\"ה וכנסת ישראל, הוא, כי חתן וכלה שלמטה משתלשלים מחתן וכלה שלמעלה<sup data-n=\"2321\">5</sup>, הקב\"ה וכנסת ישראל<sup data-n=\"2322\">6</sup>, ולכן מביא בהמאמר מ\"ש בזהר (שבת) אחים הם הקב\"ה וכנס\"י, כי זהו היסוד להפירוש שאחים הם חתן וכלה.\n<b>ולכאורה</b><sup data-n=\"2323\">7</sup> יש להוסיף, דהביאור שבהמאמר (בשני הענינים דשבת אחים וגם יחד) הוא גם להפירוש<sup data-n=\"2324\">8</sup> שאחים קאי על בני ישראל, שבהאהבה והאחוה שלהם שתי מדריגות בכללות. התקשרות (בדוגמת קישורי תנאים), ועי\"ז באים אח\"כ להתאחדות. ועפ\"ז יש לומר, דזה שמביא בהמאמר פירוש הזהר דשבת אחים גם יחד קאי על היחוד דקוב\"ה וכנס\"י, הוא, כי בכדי שהאהבה והאחוה דישראל תהי' באופן דיחד (דוגמת היחוד דנשואין), הוא<sup data-n=\"2325\">9</sup> ע\"י גילוי היחוד דישראל עם קוב\"ה<sup data-n=\"2326\">10</sup>. ועפ\"ז יש לבאר גם מה שהכתוב<sup data-n=\"2327\">11</sup> ממשיך (דשבת אחים גם יחד הוא) כשמן הטוב על הראש יורד על הזקן זקן אהרן שיורד על פי מדותיו, כי בכדי שהיחוד דקוב\"ה וישראל יפעול בישראל אהבה ואחוה אמיתית עד באופן דיחד, הוא ע\"י ירידת והמשכת שמן הטוב, כדלקמן (סעיף ח).ב) <b>ויובן</b> זה בהקדים דאיתא בזהר<sup data-n=\"2328\">12</sup> זמנא חדא הוה צריכא עלמא למיטרא, אתו לקמי' דרשב\"י, וע\"י שאמר דרוש בפסוק הנה מה טוב ומה נעים שבת אחים גם יחד ירד מטר. וידוע הדיוק בזה<sup data-n=\"2329\">13</sup>, הרי מצינו שבכדי לפעול ירידת גשמים היו מוסיפים שש ברכות בשמו\"ע<sup data-n=\"2330\">14</sup> וגוזרים י\"ג תעניות<sup data-n=\"2331\">15</sup>, וחוני המעגל עג עוגה ועמד בתוכה והתפלל<sup data-n=\"2332\">16</sup>, ורשב\"י פעל זה ע\"י אמירת דרוש בלי יגיעה כלל.\n<b>ונקודת</b> הביאור בזה (כמובן מהדרושים), דזה שצריך להשתדלות מיוחדה לפעול ירידת גשמים הוא בתפלה. דכיון שתפלה היא מלמטה למעלה, לכן בכדי שהעבודה (תפלה) דהתחתונים תעורר ותמשיך גשמים (דשורש הגשמים הוא למעלה מהשתלשלות<sup data-n=\"2333\">17</sup>) צריכה להיות השתדלות מיוחדה. ורשב\"י המשיך ירידת גשמים ע\"י אמירת תורה, דתורה היא מלמעלה למטה, ולכן לא הי' צריך לעבודה וליגיעה.\n<b>והטעם</b> על זה שרשב\"י דוקא המשיך ירידת גשמים ע\"י אמירת תורה, הוא, כי ירידת גשמים (לאחרי שהי' תחלה עצירת גשמים) הוא <i>שינוי</i> בהעולם, דזה שנעשה שינוי בעולם הוא (בדרך כלל) ע\"י תפלה, כמבואר בתניא<sup data-n=\"2334\">18</sup>. אלא שברשב\"י, גם בעסק התורה שלו היתה (גם) המעלה דתפלה, ולכן המשיך ירידת גשמים ע\"י אמירת תורה.\nג) <b>והענין</b> הוא, דהחילוק בין תורה ותפלה הוא ע\"ד החילוק בין ברכה ותפלה<sup data-n=\"2335\">19</sup>. דתפלה היא מלמטה למעלה (כנ\"ל), שהמתפלל הוא למטה ומבקש שישפיעו לו מלמעלה, וברכה היא מלמעלה למטה, שהמברך [זה שיש לו כח לברך, וע\"ד אברהם אבינו שאמר לו הקב\"ה הברכות נתונות לך<sup data-n=\"2336\">20</sup>] הוא למעלה מהשורש שממנו נמשכת הברכה וממשיך אותה מלמעלה למטה. וזהו שברכה היא בדרך ציווי, כי המברך הוא למעלה מהשורש שמשם נמשכת הברכה ולכן בכחו לצוות.\n<b>והנה</b> המעלה דברכה לגבי תפלה היא בנוגע להאדם המברך והמתפלל, אבל בנוגע לההמשכה עצמה, ההמשכה שע\"י תפלה היא נעלית יותר. דענין הברכה הוא להמשיך מה שכבר נמצא בהמקור ולא דבר חדש, וענין התפלה הוא בקשה מהקב\"ה שגם באם לא ישנה ח\"ו ההשפעה גם בהמקור, ולא עוד אלא <i>שנגזר</i> עליו שיהי' חולהח\"ו וכיו\"ב, מ\"מ, תומשך לו השפעה חדשה מאוא\"ס שלמעלה מהשתלשלות. דזהו שאומרים בכמה תפלות יהי רצון, דפירוש <i>יהי</i> רצון הוא שיהי' רצון חדש. והטעם על זה שהמשכת אור חדש הוא ע\"י התפלה דוקא, כי למעשה ידיך תכסוף<sup data-n=\"2337\">21</sup>, ולכן, ע\"י התפלה, עבודת המטה, מגיעים לאוא\"ס שלמעלה מהשתלשלות.\nד) <b>והנה</b> ענין זה שבתפלה (שעל ידה נמשכת השפעה חדשה) הוא בכללות גם בתורה. דזה שע\"י הפסק דין שבתורה נעשה <i>שינוי</i> בעולם<sup data-n=\"2338\">22</sup> [שנעשה דבר חדש שלא הי' גם בשורש ומקור העולם], הוא, כי התורה היא למעלה משורש העולם (כי התורה היא חכמתו ית' שלמעלה מהחכמה דמעשה בראשית), ולכן, ע\"י הפס\"ד דתורה נעשה שינוי וחידוש בהעולם. ונמצא, שבתורה ישנם ב' המעלות, המעלה דתפלה – המשכת ענין חדש, והמעלה דברכה<sup data-n=\"2339\">23</sup>. דהשינוי והחידוש שנעשה בעולם ע\"י הפס\"ד דהת\"ח העוסק בתורה הוא (לא בדרך בקשה כבתפלה, אלא) בדרך ממילא. וכידוע<sup data-n=\"2340\">24</sup> בענין מאן מלכי רבנן<sup data-n=\"2341\">25</sup>, דלהיות שלימוד התורה שלהם הוא בביטול, הרי הפסקי דינים שלהם הוא שהמלך עצמו (מלך מלכי המלכים הקב\"ה) גוזר ואומר את הפסק דין, וכיון שזהו גזירת המלך, נעשה כן ממילא. ועד\"ז הוא בנוגע להמופתים שעשו התנאים ואמוראים ע\"י עסק התורה שלהם<sup data-n=\"2342\">26</sup>, כמו רפב\"י שאמר גינאי נהרא חלוק לי מימיך<sup data-n=\"2343\">27</sup>, שישנם בזה שתי המעלות. שינוי וחידוש בהנהר (שאינו גם בשרשו ומקורו<sup data-n=\"2344\">28</sup>) – המעלה דתפלה, ושהשינוי בהנהר נעשה ע\"י <i>הציווי</i> של רפב\"י – המעלה דברכה.\nה) <b>אלא</b> שאעפ\"כ מעלה בתפלה לגבי תורה, כי תורה היא חכמה, וחכמה (גם החכמה דתורה שלמעלה מהחכמה דמעשה בראשית) היא באין ערוך לגבי אוא\"ס, וע\"י התפלה ממשיכים רצון חדש מאוא\"ס שלמעלה גם מהחכמה דתורה<sup data-n=\"2345\">29</sup>. ועפ\"ז יש לומר, דהחידוש בזה שרשב\"י המשיך ירידת גשמים ע\"י אמירת תורה לגבי המופתים העצומים<sup data-n=\"2346\">30</sup> שעשו כמה תנאים ואמוראים ע\"י עסק התורה שלהם, הוא, שהשינוי בעולם שעשו כל התנאים והאמוראים הוא ע\"י שהמשיכו וגילו שכן הוא ע\"פחכמת התורה<sup data-n=\"2347\">31</sup>, והחידוש דירידת מטר ע\"י שרשב\"י אמר דרוש בפסוק הנה מה טוב ומה נעים שבת אחים גם יחד, הוא, דהגם שהדרוש שאמר שייך רק לענין המטר<sup data-n=\"2348\">32</sup> בכלל אבל לא הי' בו רמז שהעולם הי' ראוי אז למטר, ונמצא שגם ע\"פ חכמת התורה (שלמעלה משורש העולם) לא הי' העולם ראוי למטר, וזה שירד אז מטר ע\"י אמירת הדרוש הוא לפי שע\"י אמירת הדרוש המשיך מאוא\"ס שלמעלה מהחכמה דתורה, בדוגמת ההמשכה שע\"י תפלה.\n<b>ויש</b> לומר, דזה שע\"י אמירת תורה דהרשב\"י נמשך מאוא\"ס שלמעלה מהחכמה דתורה, הוא, כי בפנימיות התורה מאיר בגילוי אוא\"ס<sup data-n=\"2349\">33</sup>, ולהיות שרשב\"י הי' מקור פנימיות התורה [וגם בלימוד הנגלה שלו האיר הפנימיות<sup data-n=\"2350\">34</sup>], לכן ע\"י אמירת תורה שלו המשיך בגילוי אוא\"ס שלמעלה מהתורה.\nו) <b>והנה</b> זה שבכדי לפעול שינוי בהנבראים הוא (בדרך כלל) ע\"י תפלה (כמובא לעיל סעיף ב מתניא), הוא מצד שני טעמים. דזה שנעשה שינוי בהנבראים הוא ע\"י המשכת אוא\"ס שלמעלה מהשתלשלות, והמשכה זו היא ע\"י העלאת מ\"ן דתפלה (כנ\"ל סוף סעיף ג), וגם כי בכדי שיהי' שינוי בהנבראים שלמטה ע\"י האור שלמעלה מהשתלשלות שנמשך בהם צריכים הם להיות כלים להאור, וע\"י העלאת מ\"ן מלמטה נעשה המטה כלי להאור<sup data-n=\"2351\">35</sup>. ועפ\"ז צריך לומר, דזה שרשב\"י המשיך ירידת גשמים ע\"י אמירת תורה הוא מפני שבאמירת תורה שלו היו שני הענינים, המשכת אוא\"ס שלמעלה מהשתלשלות, וגם הזיכוך דהמטה<sup data-n=\"2352\">36</sup> (כדלקמן).\n<b>ויש</b> לומר, דזהו גם מה דאיתא בזהר שההשפעה שהמשיך רשב\"י ע\"י אמירת תורה היתה ירידת גשמים, כי בזה מודגש דזה שבתורתו של רשב\"י היתה גם המעלה דתפלה הוא לא רק המעלה דהמשכה מלמעלה מהשתלשלות אלא גם המעלה דזיכוך המטה. והענין הוא, דזה שהשפעת הגשמים באה ע\"י אתערותא דלתתא שייך להגשם עצמו. דכמו שבגשמיות הגשם בא מהעננים שנעשים מלחות הארץ, ואד יעלה מןהארץ והשקה את פני האדמה<sup data-n=\"2353\">37</sup>, כמו\"כ הוא ברוחניות, דגשם הוא ענין שנעשה<sup data-n=\"2354\">38</sup> (נמשך) ע\"י אתערותא דלתתא<sup data-n=\"2355\">39</sup>. וכיון <i>שענין הגשם</i> הוא המשכה שע\"י אתערותא דלתתא, מובן, דזה שע\"י אמירת תורה דרשב\"י ירד גשם, הוא, מפני שבתורתו של רשב\"י ישנה נוסף על המעלה הבאה <i>על ידי</i> אתערותא דלתתא (המשכה מלמעלה מהשתלשלות) גם המעלה דאתערותא דלתתא עצמה, זיכוך המטה.\n<b>ויש</b> לומר הביאור בזה, דזה שתורה [המשכה מלמעלה] ותפלה [עבודת האדם] הם שני ענינים [ובכל אחד מהם יש מעלה] הוא בדרגת הנשמות כמו שנעשות מציאות, אבל מצד שורש הנשמות כמו שמושרשות בהעצמות אין לחלק בין המשכה מלמעלה ובין עבודת האדם<sup data-n=\"2356\">40</sup>, דישראל וקוב\"ה כולא חד<sup data-n=\"2357\">41</sup>. דגילוי ענין זה (שישראל וקוב\"ה הם חד ממש) הוא בפנימיות התורה, תורתו של רשב\"י, ולכן בתורתו של רשב\"י יש גם ענין התפלה (זיכוך המטה).\nז) <b>ויש</b> לומר, דזה שאמירת התורה דרשב\"י היתה בפסוק הנה מה טוב ומה נעים שבת אחים גם יחד הוא מצד שני ענינים. לפי שזה שייך לירידת גשמים (כנ\"ל סעיף ה), וגם לפי שזה שפעל ירידת גשמים (שענינם הוא אתערותא דלתתא, עבודת האדם) ע\"י אמירת תורה (המשכה מלמעלה, תורתו של הקב\"ה), הוא לפי שישראל וקוב\"ה כולא חד, ולכן אמירת התורה שלו היתה עה\"פ שבת אחים גם יחד שקאי על היחוד דקוב\"ה וישראל (כמובא לעיל בתחלת המאמר). ויש להוסיף, דזהו גם מה שבדרוש שלו (שעל ידו פעל ירידת גשמים) מדובר בענין אהבת ישראל, שגם אלה שבתחלה היו מגיחי קרבא דבעו לקטלא דא לדא, לבתר אתהדרו ברחימותא דאחוה, כי ע\"י האהבה והאחדות דישראל מתגלה האהבה והאחדות דישראל והקב\"ה. דע\"י שבת אחים (האהבה והאחוה דישראל) נמשך להיות גם יחד, גם לאכללא עמהון שכינתא.\nח) <b>וזהו</b> כשמן הטוב גו', שמן הוא חכמה, תורה, ושמן הטוב הוא פנימיות התורה<sup data-n=\"2358\">42</sup>. ויש לקשר זה עם מ\"ש במפרשי הזהר<sup data-n=\"2359\">43</sup>, דשמן הטוב הוא הארת יסוד דעתיק, כי גליא דתורה שייך לאריך ופנימיות התורה לעתיק. וזהו שבת אחים גם יחד כשמן הטוב גו', שבכדי להיות שבת אחים הוא ע\"י לימוד פנימיות התורה.וממשיך בכתוב יורד על הזקן זקן אהרן שיורד על פי מדותיו, שהם שתי ירידות. זקן הוא הבנת והשגת התורה, זקן שקנה חכמה<sup data-n=\"2360\">44</sup>, ומדותיו הם לבושי המצוות<sup data-n=\"2361\">45</sup>. שהלימוד דפנימיות התורה צריך לחדור (דורכנעמען) כל הכחות שלו, הן ההבנה וההשגה והן המעשה בפועל. ועי\"ז נעשה שבת אחים גם יחד, שהאהבת ישראל שלו היא באופן דשבת אחים (התקשרות, דוגמת קישורי תנאים) ויתירה מזו באופן דגם יחד (יחוד דנשואין), ועי\"ז קוב\"ה אצית למילולייהו ונעשים כלים לקבל ההשפעה מאוא\"ס שאין בו הגבלות, גם לא ההגבלה דחכמת התורה, שהקב\"ה עצמו משפיע לכאו\"א מישראל רב טוב בטוב הנראה והנגלה, בבני חיי ומזוני רויחא.\n**********",[["2316","*","יצא לאור ב<b>קונטרס ל\"ג בעומר – תש\"נ</b>, \"לקראת ל\"ג בעומר הבעל\"ט – הננו מוציאים לאור . . <i>עש\"ק פ' אמור גו' ואמרת</i>,<i> שנת ה'תש\"נ</i>\"."],["2317","1","תהלים קלג, א."],["2318","2","דל\"ג בעומר תרצ\"ב, בתנאים של בתו הרבנית וכו' מרת שיינא עם בעלה הרה\"ח וכו' ר' מנחם מענדל הכהן האָרענשטיין הי\"ד."],["2319","3","ראה בארוכה מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרצו ואילך."],["2320","4","ח\"ג ז, ב."],["2321","5","ראה ד\"ה אשר ברא ה'תשל\"ט ס\"ב (לעיל ח\"ב ס\"ע סו), ובהנסמן שם הערה 9."],["2322","6","וראה בד\"ה זה תרצ\"ב הנ\"ל, שבהקב\"ה וכנס\"י ישנם הענינים דקישורי תנאים וחתונה, דבחגה\"ש הוא החתונה דהקב\"ה וישראל כמרז\"ל (תענית כו, ב – במשנה) ביום חתונתו זה מתן תורה ובל\"ג בעומר הוא הקישורי תנאים \"ומאז עד חגה\"ש הם מועדי שילוח סבלונות מהחתן לכלה\"."],["2323","7","ד\"לכאורה\" הוא גם בענין דהוא למסקנא (ראה שד\"ח כללי הפוסקים סט\"ז אות ח)."],["2324","8","מפרשים לתהלים שם. וראה זח\"ג נט, ב – הובא לקמן ס\"ז."],["2325","9","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["2326","10","ועפ\"ז יומתק מה שמדייק בהמאמר מ\"ש בזהר \"גם לרבות ישראל דלתתא\"."],["2327","11","תהלים שם, ב."],["2328","12","ח\"ג נט, ריש ע\"ב."],["2329","13","ד\"ה זח\"ג כו' דעלמא הוה צריך למיטרא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940254\" data-slug=\"or-hatorah-hb\" data-id=\"8159940254\">אוה\"ת ויקרא</a> (הוספות) ע' רנד ואילך [נדפס גם בביאורי הזהר להצ\"צ כרך ב אחרי ע' תתקכא ואילך]. ד\"ה בזהר פ' אחרי כו' זימנא חדא תרכ\"ז (סה\"מ תרכ\"ז ע' רסז ואילך). סה\"מ עטר\"ת ס\"ע קל ואילך. סה\"מ תרפ\"ז ע' צא."],["2330","14","משנה תענית טו, א. רמב\"ם הל' תעניות פ\"ג ה\"ז. שם פ\"ד ה\"ז ואילך. טושו\"ע או\"ח הל' תענית סתקע\"ה."],["2331","15","משנה שם יב, ב. רמב\"ם שם פ\"ג ה\"ב ואילך. טושו\"ע שם."],["2332","16","תענית כג, א."],["2333","17","ראה תענית (ב, א) דגשמים לא נמסרו ביד שליח. וראה סה\"מ תרמ\"ד ע' קנה."],["2334","18","קו\"א רד\"ה להבין מ\"ש בפע\"ח (קנה, א)."],["2335","19","בהבא לקמן ראה בהמצויין בהערה 13. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101038\" data-slug=\"likkutei-sichot\" data-id=\"1300101038\">לקו\"ש ח\"י ס\"ע 38</a> ואילך, ובהנסמן שם."],["2336","20","במדב\"ר פי\"א, ב (בסופה)."],["2337","21","איוב יד, טו."],["2338","22","כידוע הראי' לזה מירושלמי (נדרים פ\"ו סוף ה\"ח. ועוד. הובא בשו\"ע אדה\"ז הל' נדה סקפ\"ט סקכ\"ג), דכאשר ב\"ד מעברין את השנה – בתולי' חוזרין."],["2339","23","כ\"מ באוה\"ת ויקרא ובסה\"מ תרכ\"ז שבהערה 13. וראה גם סה\"מ תרכ\"ט ע' ג', שבברכת כהנים ישנם ב' המעלות (דברכה ותפלה), ובהמשך הענין שם בנוגע לתורה."],["2340","24","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א וישב כז, ב</a>. וראה אוה\"ת ויקרא שם (ע' רנו). סה\"מ תרכ\"ז שם (ע' רעא)."],["2341","25","כ\"ה בתו\"א שם (ובכ\"מ), ע\"פ גיטין סב, א."],["2342","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. סה\"מ ה'ש\"ת ע' 116."],["2343","27","חולין ז, א."],["2344","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת שם כג, א</a>, דזה שע\"י התורה פעל חלוקת הנהר הוא לפי שהגילוי שנמשך ע\"י התורה הוא <i>מלמעלה</i> מהשתלשלות."],["2345","29","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830275\" data-slug=\"or-hatorah-hb\" data-id=\"8158830275\">אוה\"ת נשא ע' ערה</a>, דההמשכה שע\"י תורה, גם במי שתורתו אומנתו, היא מבחינת חכמה, וע\"י התפלה \"ממשיך יהי רצון שלמעלה מהחכמה, ולכן אף שע\"פ החכמה אין יסורים בלא עון עכ\"ז ע\"י הרצון נמשך המחילה\"."],["2346","30","כ\"ה הלשון בלקו\"ת שבהערה 26."],["2347","31","להעיר מתורת הה\"מ (לקו\"א נז, ד. או\"ת ר\"פ בשלח לא, ג) דזה שהקב\"ה גוזר וצדיק מבטל (מו\"ק טז, ב. וש\"נ) הוא \"כמשל אב שאומר חידוש בתורה והבן מגודל חריפותו ופלפולו סותר את דבריו\" – דמזה מובן, שזה שצדיק מבטל הוא מפני שמגלה (ע\"ד נצחוני בני נצחוני (ב\"מ נט, ב)) שכ\"ה ע\"פ חכמת התורה. ובהמשך הענין שם, דזה שאמר רפב\"י אם אין אתה חולק מימיך גוזרני עליך שלא יעברו בך מים לעולם (חולין שם) הוא (לא גזירה בעלמא אלא) <i>הסברה</i>. עיי\"ש."],["2348","32","ראה אוה\"ת ויקרא (ע' רנד. רנו). סה\"מ תרכ\"ז (ע' רעג)."],["2349","33","ראה המשך תער\"ב ח\"ב פשס\"ד (ע' תשמז)."],["2350","34","המשך תער\"ב שם. וראה גם המשך תרס\"ו ע' מה. שם ע' שו. ובכ\"מ. וראה ד\"ה פתח ר\"ש ה'תשל\"ד ס\"ו (לקמן ע' רפט), שע\"י הגילוי דפנימיות התורה הגיע רשב\"י להקשר דישראל וקוב\"ה שלא ע\"י אמצעות התורה."],["2351","35","כ\"ה להדיא בסה\"מ עטר\"ת שם (ע' קלו). וראה עד\"ז סה\"מ תרע\"ח ס\"ע תב.\nולהעיר שעפ\"ז יומתק הלשון ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא (קו\"א קנה, סע\"א</a>) \"כדי להמשיך אור א\"ס ב\"ה למטה א\"א בלי העלאת מ\"ן מלמטה דוקא\" – דלכאורה, זה שצריך להעלות מ\"ן \"כדי להמשיך אור א\"ס ב\"ה\" הוא מצד ההמשכה עצמה [דהמשכת אור שלמעלה מהשתלשלות הוא ע\"י העלאת מ\"ן שלמטה דוקא], וההוספה \"להמשיך אור א\"ס ב\"ה <i>למטה</i>\", יש לומר, שבתיבת \"למטה\" מרמז הטעם שבסה\"מ עטר\"ת שם."],["2352","36","ראה <i>עד\"ז</i> סה\"מ תרע\"ח שם (ריש ע' תב)."],["2353","37","בראשית ב, ו."],["2354","38","להעיר מפרש\"י עה\"פ שם, ה \"לא המטיר לפי שאדם אין לעבוד את האדמה כו' וכשבא אדם כו' התפלל עליהם וירדו\".\nולהעיר מרמב\"ם הל' תעניות ספ\"ג, \"שאין גוזרין על הציבור תענית כו' אלא בא\"י בלבד ובגלל המטר\". ובמגיד משנה שם \"שבשאר הצרות אפילו בא\"י אין להם חומר זה\". ואולי י\"ל כי בשאר הענינים – עבודת המטה (תענית וכיו\"ב) היא רק בשביל השפעתם, ובמטר הוא בשביל המציאות שלו."],["2355","39","המשך וככה תרל\"ז פס\"ו, עיי\"ש בארוכה."],["2356","40","ראה עד\"ז לעיל ע' קכד ואילך."],["2357","41","ראה זח\"ג עג, א."],["2358","42","ראה גם ד\"ה כשמן הטוב תרע\"ח (סה\"מ תרע\"ח ע' רצ) דשמן הטוב הוא פנימיות ח\"ס כו' טעמי תורה שיתגלו לעתיד."],["2359","43","הובא באוה\"ת (יהל אור) לתהלים עה\"פ ע' תקה."],["2360","44","ראה קידושין לב, ב."],["2361","45","אוה\"ת שם. סה\"מ תרע\"ח שם."]]],[1500380043,"<h3>בס\"ד. ל\"ג בעומר ה'תשמ\"ה<sup data-n=\"2362\">*</sup></h3>\n<b>להבין</b> ענין רשב\"י, הנה ידוע המאמר דל\"ג בעומר של אדמו\"ר מהר\"ש<sup data-n=\"2363\">1</sup> (בעל ההוראה דלכתחילה אַריבער<sup data-n=\"2364\">2</sup>), דזה שמצינו בזהר<sup data-n=\"2365\">3</sup> ששיבחו את רשב\"י בשבחים נוראים<sup data-n=\"2366\">4</sup>, כמו ר' יהודה הוה קרי לי' שבת<sup data-n=\"2367\">5</sup>, ומאן פני<sup data-n=\"2368\">6</sup> האדון ה' דא רשב\"י<sup data-n=\"2369\">7</sup>, יובן זה מענין השבחים שמשבחים את הבורא ית', דלכאורה תמוה, וכי הוא ית' צריך לשבחים שלנו<sup data-n=\"2370\">8</sup>, וידוע הביאור בזה<sup data-n=\"2371\">9</sup>, דלהיות שכל העולמות הם באין ערוך אליו ית', וההשפעה לעולמות היא ירידה לגבי' ית', לכן בכדי לעורר אצלו ית' הרצון להשפיע בעולמות הוא ע\"י השבחים. וזהו מה שארז\"ל<sup data-n=\"2372\">10</sup> לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל, דהגם שתפלה היא מצות עשה מן התורה לבקש צרכיו מהקב\"ה<sup data-n=\"2373\">11</sup>, וציווי התורה הוא נתינת כח, מ\"מ, צריך להיות תחילה סידור שבחו של מקום, שעי\"ז מעוררים אצלו ית' הרצון להשפיע צרכי המשבח. ועד\"ז הוא גם בנוגע לרשב\"י, שמצד עוצם מעלתו של רשב\"י לגבי שאר התנאים, שהי' מובדל מהם באופן דאין ערוך, לכן, בכדי לעורר השפע שלו, הוצרכו לשבחו. ויש לומר, דמ\"ש בהמאמר דענין שבחי רשב\"י יובן מענין שבחו של מקום, הוא בנוסף על הבאת ראי' שבכדי לעורר השפעה שבאין ערוך צריך לשבחים, אלא גם, שהאין ערוך דשאר התנאים לגבי רשב\"י הוא <i>בדוגמת</i> האין ערוך דנברא לבורא. וזהו גם מ\"ש בהמאמר שהיו משבחים אותו בשבחים נוראים, דלשון נורא מורה על ענין שמובדל בערך לגמרי, עד שמטיל אימה.ב) <b>והענין</b> הוא, דהנה כתיב<sup data-n=\"2374\">12</sup> והאיתנים מוסדי ארץ, איתנים אותיות תנאים<sup data-n=\"2375\">13</sup>, והם המייסדים<sup data-n=\"2376\">14</sup> את התושבע\"פ שנקראת בשם ארץ<sup data-n=\"2377\">15</sup>, היינו שממשיכים בחינת איתן בתושבע\"פ. וי\"ל שהמשכת איתן להתנאים הוא ע\"י רשב\"י, שהוא הי' הממוצע בין בחינת איתן להתנאים, כמבואר בארוכה בהמאמר<sup data-n=\"2378\">16</sup>.\n<b>וביאור</b> הענין (השייכות דבחינת איתן לרשב\"י), הנה ידוע, דאיתן קאי על עצם הנשמה<sup data-n=\"2379\">17</sup>, בחינת יחידה, שהיא מיוחדת באלקות בתכלית היחוד. וזוהי השייכות דאיתן לרשב\"י, כי רשב\"י הי' בתכלית היחוד, כמו שאמר על עצמו אנא סימנא בעלמא<sup data-n=\"2380\">18</sup>, בחד קטירא אתקטרנא בי' בקוב\"ה, בי' אחידא בי' להיטא בי' אתדבקת<sup data-n=\"2381\">19</sup> [כמבואר בהערות אאמו\"ר<sup data-n=\"2382\">20</sup> ענין ג' הלשונות], שהוא הביטול והיחוד שמצד היחידה. וזהו גם שרשב\"י הי' מקור פנימיות התורה, רזין דאורייתא שהם נשמתא דאורייתא<sup data-n=\"2383\">21</sup> ורזין דרזין שהם נשמתא דנשמתא<sup data-n=\"2384\">22</sup>, שבנשמתא לנשמתא נכלל גם בחינת יחידה<sup data-n=\"2385\">23</sup>. ולא עוד אלא שגם לימוד הנגלה שלו (שבזה הי' רוב לימודו<sup data-n=\"2386\">24</sup>), הי' באופן דלימוד פנימיות התורה, המשכת אלקות מלמעלה למטה<sup data-n=\"2387\">25</sup>. דהנה החילוק בין נגלה דתורה לפנימיות התורה הוא<sup data-n=\"2388\">26</sup>, שנגלה דתורה נתלבשה בדברים גשמיים בכדי לברר בירורים<sup data-n=\"2389\">27</sup>, משא\"כ פנימיות התורה היא למעלה מהתלבשות, והלימוד דפנימיות התורה הוא (בעיקר לא בכדי לברר בירורים, כי אם), להמשיך אורות עליונים. ואצל רשב\"י, הנה גם בלימוד הנגלה האיר הפנימיות, ועד שגם לימוד הנגלה שלו הי' המשכת אלקות מלמעלה<sup data-n=\"2390\">28</sup>. וזהו העילוי דרשב\"י על שאר התנאים, דכל התנאים, עיקר עסקם הי' או בנגלה דתורה או בנסתר דתורה. דרוב התנאים, עיקר עסקם הי' בנגלה דתורה, דמארי קבלה מועטים היו<sup data-n=\"2391\">29</sup>, ורב יהודה כולי תנוייבנזיקין הוה<sup data-n=\"2392\">30</sup>, דחלק זה שבתורה נתלבש בדברים הכי תחתונים שבעוה\"ז הגשמי גופא (עניני נזיקין, טענות של שקר וכו'), בכדי לברר גם הניצוצות שבדברים אלו<sup data-n=\"2393\">31</sup>. ואלו שעיקר עסקם הי' בנסתר דתורה, מעשה מרכבה, לא היו עוסקים בנגלה כ\"כ. כמו ר' נחוניא בן הקנה שחיבר ספר הקנה<sup data-n=\"2394\">32</sup>, הרי בנגלה דתורה מובא ממנו רק מעט. משא\"כ רשב\"י, הנה נוסף על זה שעסקו בפנימיות התורה הי' באופן נעלה הרבה יותר<sup data-n=\"2395\">33</sup>, המשיך האור דפנימיות גם בנגלה, כידוע<sup data-n=\"2396\">34</sup> בענין מחצתי ואני ארפא<sup data-n=\"2397\">35</sup> שע\"י רשב\"י נתרפאה ונתבטלה המחיצה שבין גליא דתורה לסתים דאורייתא, ועד שהנגלה והנסתר הם חד.\nג) <b>ועפ\"ז</b> יובן שהעילוי דרשב\"י על כל התנאים הוא עילוי שבאין ערוך, שלכן, בכדי לעורר השפע ממנו הוצרכו לשבחו. דהנה העילוי דיחידה על נרנ\"ח הוא עילוי שבאין ערוך, וכמובן גם מזה שנקראת יחידה לשון יחיד, דתואר יחיד מורה שאין שני לו<sup data-n=\"2398\">36</sup>. דהגם שגם יחידה היא (ניצוץ) נברא, וכל ה' הדרגות (גם יחידה) שייכים להנפש שמלובשת בהגוף ובאופן דשם כמאמר<sup data-n=\"2399\">37</sup> חמשה שמות נקראו לה (להנפש שבגוף), אעפ\"כ, הרי ענינה של יחידה הוא מה שהיא מקבלת מבחינת יחיד<sup data-n=\"2400\">38</sup>, ניצוץ נברא שענינו הוא מה שבו מתלבש ניצוץ בורא<sup data-n=\"2401\">39</sup>. ומזה מובן במכ\"ש בענין יחידה הכללית (דכלללות ההשתלשלות ומכ\"ש) דתורה, שהיא נעלית באין ערוך אפילו מנשמתא דאורייתא, ועאכו\"כ מגופא דאורייתא, היינו ההלכות דתורה שנק'<sup data-n=\"2402\">40</sup> גופי תורה. ולכן, בכדי לעורר השפע דרשב\"י (בחינת איתן, יחידה), ובפרט בחינת הפנימיות שבזה (העלם שלצורך עצמו<sup data-n=\"2403\">41</sup>), שיומשך בלימוד התורה (נגלה דתורה, ועד לנזיקין) דהתנאים שהלימוד שלהם<sup data-n=\"2404\">42</sup> הי' באופן דהתלבשות לברר בירורים, הוצרכו לשבחו, כי בכדי לעורר השפעה שבאין ערוך הוא ע\"י קדימת השבחים, כנ\"ל.\nד) <b>אך</b> צריך להבין, מכיון שרשב\"י הי' מובדל בערך משאר התנאים איך יפעלו עליו השבחים שלהם ועד לעורר ולחדש ההשפעה אליהם. וביותר אינו מובןמענין השבחים שמשבחים את הבורא, בכדי לעורר הרצון להשפיע לנבראים, הרי התעוררות הרצון הוא בעצמות אוא\"ס שלמעלה מהשתלשלות [כמובן מהמבואר בכ\"מ<sup data-n=\"2405\">43</sup> דע\"י השבחים מעוררים הרצון שיומשך ויתלבש בהספירות], והיאך שייך שהשבחים שלנו יתפסו מקום בעצמות אוא\"ס. וידוע הענין בזה<sup data-n=\"2406\">44</sup>, דזה שהעלאת מ\"ן דהנבראים (כולל ענין השבחים<sup data-n=\"2407\">45</sup>) מעוררת ההמשכה, הוא לפי שכן עלה ברצונו ית' שהעלאת מ\"ן דהנבראים תתפוס מקום אצלו ית'. ולא עוד אלא שע\"י העלאת מ\"ן דהנבראים יהי' שינוי כביכול בהאור, שיומשך למטה למקום שאין ערוך כלל, אף שמצד עצמו הוא מובדל מזה. ויש לומר הביאור בזה, דמכיון שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"2408\">46</sup>, דענין נתאוה הוא למעלה מהטעם כמאמר אדה\"ז<sup data-n=\"2409\">47</sup> אויף אַ תאוה איז קיין קשיא, הנה להיות שהתאוה והתענוג דלמעלה הוא דירה בתחתונים, בתחתון שאין תחתון למטה ממנו<sup data-n=\"2410\">48</sup>, לכן העלאת מ\"ן דהנבראים פועלת בהאור<sup data-n=\"2411\">49</sup>. ולכאורה יש להוסיף, דזהו גם מה שרובם ככולם של השבחים (בסידור שבחו של מקום בפסוקי דזמרה קודם התפלה) הם בענין השפעתו ית' בנבראים, כי [נוסף לזה שהשבח צ\"ל מעין השפע שרוצים לעורר, ובכדי לעורר ההשפעה למטה צ\"ל השבחים בענין זה, הנה] ע\"י שמשבחים לפניו ית' השפעתו לנבראים התחתונים, עי\"ז מעוררים ומגלים התענוג בדירה בתחתונים.\n<b>ועד\"ז</b> הוא גם בענין השבחים דרשב\"י, דזה שע\"י השבחים עוררו שיומשך השפע שלו (בחינת איתן, יחידה) בלימוד התורה דהתנאים שהלימוד שלהם הי' לברר בירורים, הוא מצד היתרון שבענין הבירורים (על ענין הגילויים), דהרצון והתענוג שלמעלה הוא בענין הבירורים דוקא. דזהו מ\"ש והאיתנים (אותיות תנאים) מוסדי ארץ, ארץ מלשון רצון<sup data-n=\"2412\">50</sup>, ויתירה מזו שארץ שייך גם לתשוקה כמ\"ש<sup data-n=\"2413\">51</sup> פקדת הארץ ותשוקקי', דהרצון ותשוקה ותענוג שלמעלה הוא בארץ דוקא, בבירור דברים הגשמיים, ובפרט בבירור הענינים דנזיקין, שנעשה ע\"י האיתנים מוסדי ארץ<sup data-n=\"2414\">52</sup>. וע\"י המשכת האור דפנימיות התורה שלמעלה מענין הבירורים, תורתו של רשב\"י, להאיתנים מוסדי ארץ (שעי\"ז נמשך להם תוספות גם בענין הבירורים), עי\"ז נעשה יתרון בהאור<sup data-n=\"2415\">53</sup>,כי יתרון האור הוא מן (בירור) החושך<sup data-n=\"2416\">54</sup>. ולא עוד אלא שע\"י שנמשך להאיתנים מוסדי ארץ (ענין הבירורים) השפע דרשב\"י (אור שלמעלה מענין הבירורים), ישנם ב' המעלות, המעלה דאור ישר והמעלה דאור חוזר, וע\"ד לאתבא צדיקייא בתיובתא<sup data-n=\"2417\">55</sup>, המעלה דצדיקים והמעלה דבעלי תשובה.\nה) <b>ויש</b> לקשר זה עם מאמר הזהר<sup data-n=\"2418\">56</sup> זמנא חדא הוה צריך עלמא למיטרא, אתו לקמי' דר\"ש ר' ייסא ור' חזקי' ושאר חברייא, וע\"י שדרש להם בפסוק<sup data-n=\"2419\">57</sup> הנה מה טוב ומה נעים שבת אחים גו' ירד מטר, ומבואר בדרושי אדמו\"ר הצ\"צ<sup data-n=\"2420\">58</sup> ואדמו\"ר מהר\"ש<sup data-n=\"2421\">59</sup>, דהגם שרשב\"י המשיך ירידת הגשמים ע\"י אמירת תורה בדרך מלמעלה למטה, מ\"מ הי' צריך לזה גם העלאת מ\"ן דהחברייא והשבחים ששיבחו אותו, שעי\"ז פעלו יתרון ברשב\"י ע\"ד מתלמידי<sup data-n=\"2422\">60</sup> יותר מכולן. ויש לומר, שהשייכות דענין זה לירידת גשמים היא, כי במטר כתיב<sup data-n=\"2423\">61</sup> כי לא המטיר גו' ואדם אין לעבוד את האדמה, דירידת המטר הוא ע\"י עבודת האדם, ובפרט ע\"י עבודת התשובה כמארז\"ל<sup data-n=\"2424\">62</sup> עה\"פ<sup data-n=\"2425\">63</sup> יערוף כמטר לקחי גו' שברו הבריות את ערפן מיד מטר יורד, ובירידת המטר ע\"י אמירת תורה דרשב\"י (מלמעלה למטה) והעלאת מ\"ן דתלמידיו (מלמטה למעלה) היו ב' המעלות, המעלה דצדיקים והמעלה דבעלי תשובה.\n<b>ולכאורה</b> יש להוסיף, דהמשכת השפע דרשב\"י (בחינת איתן, יחידה) להאיתנים מוסדי ארץ בשביל ענין הבירורים, הוא ע\"ד המבואר במקום אחר<sup data-n=\"2426\">64</sup> בענין יחידה שבנפש, דזה שהיחידה מתפשטת בד' אמותיו של אדם<sup data-n=\"2427\">65</sup>, שלכן<sup data-n=\"2428\">66</sup> ד' אמות של אדם קונות לו בכל מקום<sup data-n=\"2429\">67</sup> גם שלא מדעתו<sup data-n=\"2430\">68</sup>, הוא דוקא בכדי לקנות חפץ שמונח בהם<sup data-n=\"2431\">69</sup>, הקנאת דבר גשמי (שמחוץ לאדם) לרשותו של האדם, בכדי לבררו ולזככועל ידי שישתמש בו לשם שמים, כי הבירור דדברים גשמיים דוקא מגיע בהעצם. ועד\"ז הוא גם ביחידה דתורה (תורת רשב\"י), שהיא מתעוררת ונמשכת בשביל ענין הבירורים.\nו) <b>וע\"פ</b> כל הנ\"ל יובן גם זה שהשבחים שהיו משבחים את רשב\"י (שמביא בהמאמר) בכדי לעורר את ההשפעה הם ר\"י קארי לי' שבת ומאן פני האדון הוי' דא רשב\"י, כי בשבחים אלו מרומז המשכת העליון (שמובדל בערך) למטה, ויתירה מזו שההמשכה היא ע\"י עבודת התחתון. דהנה<sup data-n=\"2432\">70</sup> בשבת כתיב<sup data-n=\"2433\">71</sup> כי קודש היא, קודש מלה בגרמי'<sup data-n=\"2434\">72</sup>, היינו ששבת הוא מובדל ושלא בערך לששת ימי המעשה, ואעפ\"כ נמשך מקדושת השבת בימים שלפניו ושלאחריו, דמיום ד' ואילך הוא קמי שבתא ועד יום ד' הוא בתר שבתא<sup data-n=\"2435\">73</sup>, נוסף לזה ששבת מיני' מתברכין כולהו יומין<sup data-n=\"2436\">74</sup>. ועד\"ז הוא בנוגע להאדם, דעם היות ששבת היא מקדשא וקיימא<sup data-n=\"2437\">75</sup>, דמכיון שקדושת השבת היא קדושה נעלית ביותר, קודש מלה בגרמי' (כנ\"ל), אין שייך בה תפיסת ידי אדם, אעפ\"כ ניתן כח לישראל להוסיף בקדושת השבת<sup data-n=\"2438\">76</sup>, זכור את יום השבת לקדשו<sup data-n=\"2439\">77</sup>, ועד שישראל מוסיפים גם בהתענוג דשבת, כלשון רז\"ל<sup data-n=\"2440\">78</sup> כל המענג את השבת.\n<b>ועד\"ז</b> הוא גם בענין מאן פני האדון הוי', דהוי' הוא שם העצם שם המפורש ושם המיוחד<sup data-n=\"2441\">79</sup>, משא\"כ זה שהוא ית' נקרא בשם אדון הוא כמרז\"ל<sup data-n=\"2442\">80</sup> לך נאה לקרות אדנ' שאתה אדון לכל בריותיך, דנוסף לזה ששם אד' הוא בספירת המלכות<sup data-n=\"2443\">81</sup>, ובמלכות גופא – כמו שיורדת בבריאה<sup data-n=\"2444\">82</sup>, להוות את העולמות ולהיות אדון עליהם, הנה מלשון רז\"ל שאתה אדון לכל בריותיך (בריותיך דוקא) משמע שהשם אד'<sup data-n=\"2445\">83</sup> הוא על נבראים אלו שהם בריות בעלמא<sup data-n=\"2446\">84</sup> [ובדוגמת אדון בפשטות, שהתואר אדון הואעל עבדים דוקא]. וענין פני האדון הוי' הוא ההתאחדות דהוי' (שם העצם) עם בחי' אד' (אדון לכל בריותיך). וזהו גם מה שבמצות ראי' כתיב<sup data-n=\"2447\">85</sup> יראה כל זכורך את פני האדון הוי'. דהנה ארז\"ל<sup data-n=\"2448\">86</sup> כשם שבא ליראות כך בא לראות, דנוסף לזה שבעת העלי' לרגל היו רואים אלקות במוחש (דראי' הוא למעלה מהשגה) והראי' היתה גם בבחינת הפנימיות דאלקות כמ\"ש יראה גו' את פני גו', הנה יתירה מזו, שראיית האדם באלקות (מלמטה למעלה) היתה באותו האופן כמו הראי' דלמעלה, כשם שבא ליראות כך בא לראות, ישר יחזו פנימו<sup data-n=\"2449\">87</sup>, שהראי' שלמטה והראי' שלמעלה הם ישר, בהשוואה<sup data-n=\"2450\">88</sup>. ולכן נאמר בזה יראה גו' את פני האדון הוי', כי בכדי שתהי' ההתאחדות דהראי' שלמטה עם הראי' שלמעלה, הוא ע\"י המשכת בחינת האדון הוי', התאחדות דאדון עם הוי'.\n<b>ויש</b> להוסיף, דבמצות ראי' נכלל גם הבאת קרבן (עולת ראי') כמ\"ש<sup data-n=\"2451\">89</sup> ולא יראו פני ריקם. שבזה נראה גודל העילוי דעבודת הבירורים, שע\"י הבאת קרבן גשמי [ועד שלדיעה אחת<sup data-n=\"2452\">90</sup> צ\"ל הקרבן לא מן העוף אלא מן הבהמה<sup data-n=\"2453\">91</sup>], עי\"ז דוקא יראו פני, גילוי הפנימיות דאלקות ובאופן דראי', ועד לבחינת ישר יחזו פנימו.\nז) <b>וע\"פ</b> כל הנ\"ל יובן גם הקשר דהסתלקות רשב\"י עם ספירת העומר, ועד שיום הסתלקותו נק' (ע\"פ מנהג ישראל תורה היא<sup data-n=\"2454\">92</sup>) בשם ל\"ג בעומר<sup data-n=\"2455\">93</sup>. והענין הוא, דהעבודה דספירת העומר היא בירור המדות דנפש הבהמית<sup data-n=\"2456\">94</sup>, ואעפ\"כ (ואדרבא, מצד זה), דוקא במצוה זו אומרים<sup data-n=\"2457\">95</sup> ועל ידי זה יושפע שפע רב בכל העולמות, כי עבודת הבירורים דוקא מגעת למעלה מעלה, וממשכת משם שפע, לא אור שהוא הארה בלבד אלא שפע שהוא מהות הדבר<sup data-n=\"2458\">96</sup>, ויתירה מזו – שפע רב, ולהיותו שפע רב לכן<sup data-n=\"2459\">97</sup> (מצד הריבוי שבו) הוא נמשך ונשפע בכל העולמות, עד לעולם הזההתחתון, ובעוה\"ז גופא למקום הכי תחתון שאין תחתון למטה ממנו. וי\"ל שזהו הקשר דימי הספירה [ובהם גופא, דיום הל\"ג בעומר, סוף ותשלום העבודה דספה\"ע בעיקרי המדות<sup data-n=\"2460\">98</sup>] להסתלקות רשב\"י, כי עבודתו של רשב\"י היתה לרפא ולבטל את המחיצות שבין כל הענינים, ולהמשיך מלמעלה מעלה עד למטה מטה, מבחינת איתן בבחינת ארץ. וענין זה עומד בגלוי ביום הסתלקותו בל\"ג בעומר, כמבואר באגרת הקודש לאדה\"ז<sup data-n=\"2461\">99</sup> שביום ההסתלקות הנה כל עבודת האדם אשר עבד במשך ימי חייו עומדת בגלוי כפי שהיא בשרשה ומקורה, וכמבואר בארוכה בדרושי ל\"ג בעומר בסידור לאדמו\"ר האמצעי<sup data-n=\"2462\">100</sup>.\n<b>וענין</b> זה נמשך למטה מטה עד לשמחה כפשוטה<sup data-n=\"2463\">101</sup>. ועד שמזה נמשכת שמחה גדולה ביותר, עד לשמחה הפורצת גדר<sup data-n=\"2464\">102</sup>, שמחת עולם<sup data-n=\"2465\">103</sup>, הפורצת את גדרי הגלות, ומביאה את הגאולה האמיתית והשלימה ע\"י משיח צדקנו, דמשיח אתא לאתבא צדיקייא בתיובתא&lt;55&gt;. וזה קשור גם עם ענין הפצת המעינות, אימתי אתי מר לכשיפוצו מעינותיך חוצה<sup data-n=\"2466\">104</sup>, במהרה בימינו ממש, ובעגלא דידן<sup data-n=\"2467\">105</sup>.\n**********",[["2362","*","יצא לאור ב<b>קונטרס ל\"ג בעומר – תשמ\"ח</b>, \"לקראת ל\"ג בעומר הבעל\"ט – הננו מוציאים לאור . . <i>פסח שני</i>,<i> שנת הקהל</i>, <i>שנת תשמ\"ח</i>\"."],["2363","1","ד\"ה וביאור ענין נחל איתן בהמשך והחרים תרל\"א (ע' מט ואילך). – קרוב לומר שע\"ד כמה מאמרים <i>שבתוך</i> \"המשכי\" רבותינו נשיאינו, הרי בעת <i>אמירתו</i> נתוספו לו פתיחה וסיום ולא הגיעו אלינו."],["2364","2","ראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"א ע' תריז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011124\" data-slug=\"likkutei-sichot\" data-id=\"1300011124\">לקו\"ש ח\"א ע' 124</a>. ועוד."],["2365","3","שהוא \"ספרו\" של רשב\"י, כמאמר רעיא מהימנא לרשב\"י (זח\"ג קכד, ב. וראה גם שם קנג, ב. ועוד) והמשכילים יזהירו כזהר הרקיע (דניאל יב, ג) בהאי חיבורא דילך דאיהו ספר הזהר. ויש לומר, שזהו גם מהטעמים על זה שהתחלת התקו\"ז והזהר היא בפסוק זה דוהמשכילים יזהירו גו'."],["2366","4","כן הוא בד\"ה הנ\"ל. וראה ספר \"שבחין דרשב\"י\" להריא\"ז מרגליות."],["2367","5","זח\"ג קמד, ב."],["2368","6","משפטים כג, יז. תשא לד, כג."],["2369","7","זח\"ב לח, א. נתבאר בסה\"מ תקס\"ד ע' קו. תרנ\"ה ע' נב ואילך."],["2370","8","כ\"ה הלשון בסהמ\"צ להצ\"צ שרש מצות התפלה פ\"ו (דרמ\"צ קיח, א ואילך)."],["2371","9","שרש מצות התפלה שם. ובארוכה – במצות הלל (קמח, א ואילך). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370451\" data-slug=\"torah-or\" data-id=\"3901370451\">תו\"א</a> (בהוספות) ויחי קב, א (ושם קג, ג ואילך)."],["2372","10","ברכות לב, א. שו\"ע אדה\"ז או\"ח ר\"ס נא."],["2373","11","רמב\"ם ריש הלכות תפלה. וראה חידושים על הרמב\"ם להצ\"צ, נדפסו בפסקי דינים שלו ח\"ב שמ, ג ואילך. סהמ\"צ להצ\"צ שרש מצות התפלה בתחלתו (דרמ\"צ קטו, א)."],["2374","12","מיכה ו, ב."],["2375","13","תקו\"ז תכ\"א (מג, סע\"ב). וראה גם זח\"ב קט, ב ואילך."],["2376","14","ראה המשך והחרים שם ע' מח, דפירוש \"מוסדי\" הוא לא יסוד, כי אם, שהם המייסדים."],["2377","15","תו\"א בתחילתו."],["2378","16","שם ע' מח."],["2379","17","סה\"מ ה'תש\"ג ע' 73. ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, א</a>. ובכ\"מ."],["2380","18","זח\"א רכה, א."],["2381","19","זח\"ג (אדר\"ז) רפח, א. שם רצב, א."],["2382","20","בלקוטי לוי\"צ לזח\"ג שם (רצב, א) – ע' תסב ואילך."],["2383","21","ראה זח\"ג קנב, א."],["2384","22","המשך חייב אדם לברך תרל\"ח פכ\"ג (לט, סע\"א)."],["2385","23","המשך הנ\"ל שם. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830004\" data-slug=\"or-hatorah-hb\" data-id=\"8158830004\">אוה\"ת במדבר ע' ד</a>. ובכ\"מ."],["2386","24","ראה אגה\"ק סכ\"ו (קמג, א). וראה \"שיעורים בספר התניא\" לאגה\"ק כאן הערה 24."],["2387","25","המשך תרס\"ו ע' מה. שם ע' שו (וראה גם שם ע' ריט). ושם ע' מה מקשר זה עם \"בחד קטירא אתקטרנא כו' בי' אחידא בי' להיטא\"."],["2388","26","ראה אגה\"ק שם (קמד, ב ואילך). ובארוכה – קונטרס עה\"ח פי\"א ואילך."],["2389","27","ואף שהבירור דתורה הוא בדרך ממילא, הרי מ\"מ צ\"ל התלבשות בענינים הגשמיים (ולאחרי ההתלבשות, הבירור הוא בדרך ממילא), משא\"כ הבירור שנעשה ע\"י פנימיות התורה (וברשב\"י הי' כן גם בלימוד הנגלה שלו) הוא שלא ע\"י התלבשות – המשך תרס\"ו ע' שו-ז. וראה גם המשך תער\"ב ח\"ב פשע\"ז. סה\"מ עטר\"ת ע' קלז. וראה בארוכה ד\"ה פדה בשלום תשמ\"א ס\"ג-ד (לעיל ח\"ב ס\"ע מו ואילך)."],["2390","28","המשך תרס\"ו שבהערה 25."],["2391","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380093\" data-slug=\"likkutei-torah\" data-id=\"4001380093\">לקו\"ת ויקרא ד, ד</a>. ולהעיר מחגיגה יד, ב. רמב\"ם הל' יסוה\"ת ספ\"ד."],["2392","30","ברכות כ, א."],["2393","31","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370176\" data-slug=\"torah-or\" data-id=\"3901370176\">תו\"א מקץ לח, ד</a>. מאמרי אדהאמ\"צ דברים ח\"ב ע' שעד. <i>וש\"נ</i>."],["2394","32","ראה שם הגדולים להחיד\"א ח\"ב ערך ספר הקנה."],["2395","33","\"שהי' יחיד בדורו בנסתר\" (ד\"ה להבין ענין הילולא דרשב\"י בס' מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ריש ע' תרסז)."],["2396","34","המשך חייב אדם לברך תרל\"ח פכ\"ה."],["2397","35","האזינו לב, לט."],["2398","36","כידוע החילוק בין אחד ליחיד (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380598\" data-slug=\"likkutei-torah\" data-id=\"4001380598\">לקו\"ת בלק ע, א</a>. אמ\"ב שער הק\"ש פ\"ח. ובלקו\"ת ובאמ\"ב שם מובא זה לענין <i>יחידה</i>)."],["2399","37","ב\"ר פי\"ד, ט. ראה שערי זהר לב\"ר שם."],["2400","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>. ובכ\"מ."],["2401","39","ראה ע\"ח שער מב (שער דרושי אבי\"ע) פ\"א, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת ראה כז, א</a>. ובכ\"מ."],["2402","40","זח\"ג שבהערה 21. חגיגה י, א (במשנה)."],["2403","41","ראה המשך והחרים הנ\"ל ע' נב."],["2404","42","משא\"כ ברשב\"י, שגם לימוד הנגלה שלו הי' בבחינת המשכת אלקות, כנ\"ל בפנים."],["2405","43","דרמ\"צ דלעיל הערה 9."],["2406","44","דרמ\"צ קנג, א-ב. קנט, ב ואילך. ד\"ה אדון עולם תש\"ג פ\"ו (סה\"מ ה'תש\"ג ע' 16)."],["2407","45","המשך תער\"ב ח\"ב ע' תתקעא."],["2408","46","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2409","47","הובא בהמשך תרס\"ו ס\"ע ז. וראה גם אוה\"ת בלק ע' תתקצז."],["2410","48","תניא שם."],["2411","49","להעיר מהמשך תער\"ב שם ש\"החקיקה באוא\"ס שיהי' תופס מקום ההעלאת מ\"ן\" היא מצד ענין במי נמלך. שבבחינה זו – הנמלך קודם לההתעוררות."],["2412","50","ב\"ר פ\"ה, ח ובפי' מהרז\"ו שם."],["2413","51","תהלים סה, י. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830226\" data-slug=\"or-hatorah-hb\" data-id=\"8158830226\">אוה\"ת</a> (יהל אור) לתהלים שם (ע' רכו)."],["2414","52","משא\"כ בבירור שבדרך ממילא ע\"י עסק התורה הנגלית דהרשב\"י \"אינו נשלם עדיין אמיתית הכוונה\" (המשך תרס\"ו ס\"ע שמח ואילך)."],["2415","53","ראה עד\"ז ד\"ה וכל בניך תשמ\"א (לעיל ח\"ב ס\"ע פד ואילך) סעיף ט, שע\"י ההמשכה דפנימיות התורה לנגלה דתורה, נעשה עילוי בפנימיות התורה."],["2416","54","ע\"פ לשון הכתוב קהלת ב, יג. וראה ספר הערכים-חב\"ד ערך אור ביחס לחושך ס\"ח. <i>וש\"נ</i>."],["2417","55","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. ובהנסמן במאמרי אדהאמ\"צ דברים ח\"ג ע' א'קכט. וראה זח\"ג קנג, ב."],["2418","56","ח\"ג נט, ריש ע\"ב."],["2419","57","תהלים קלג, א. –השייכות דאמירת תורה על פסוק זה דוקא לירידת גשמים נתבארה באוה\"ת וסה\"מ תרכ\"ז דלהלן. לקוטי לוי\"צ לזהר שם (ע' רצו ואילך)."],["2420","58","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940257\" data-slug=\"or-hatorah-hb\" data-id=\"8159940257\">אוה\"ת ויקרא ע' רנז</a> [נדפס גם בביאורי הזהר להצ\"צ כרך ב אחרי ע' תתקכד]."],["2421","59","סה\"מ תרכ\"ז ע' עדר."],["2422","60","תענית ז, א."],["2423","61","בראשית ב, ה."],["2424","62","ב\"ר פי\"ג, יד."],["2425","63","האזינו לב, ב."],["2426","64","קונטרס ענינה של תורת החסידות סעיף כ. עיי\"ש."],["2427","65","אמ\"ב שער הק\"ש פמ\"ב-מג (מד, ג ואילך). שער הציצית פכ\"א (יג, סע\"ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550453\" data-slug=\"torat-chaim\" data-id=\"2300550453\">תו\"ח שמות רנה, א</a> [בהוצאה החדשה – בשלח ח\"א קעט, ב]. שם, סע\"ב ואילך. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תמד. דברים ח\"ד ע' א'שעו. <i>וש\"נ</i>."],["2428","66","מאמרי אדהאמ\"צ ויקרא שם."],["2429","67","ב\"מ יו\"ד, א."],["2430","68","ראה רמ\"א חו\"מ ר\"ס רסח: ולא גרע משום דנפל עלי' (אף דגלי דעתי' עי\"ז שנפל עלי' דלא ניחא לי' לקנות בתורת קנין ד' אמות)."],["2431","69","שלכן ס\"ל להתוס' (ב\"מ שם ד\"ה ארבע) והרא\"ש (ב\"מ שם – סכ\"ח) שד' אמות אינן קונות בגניבה(ובמכירה ומתנה – ראה ש\"ך חו\"מ סרמ\"ג סק\"ט) – אף שעשאום חכמים כחצירו – כי לא עשאום כחצירו <i>לכל דבר</i>, כ\"א לצורך קנין החפץ באופנים מסויימים (מציאה וכיו\"ב)."],["2432","70","בהבא להלן ראה המשך והחרים הנ\"ל ע' נב-נג."],["2433","71","תשא לא, יד."],["2434","72","זח\"ג צד, ב."],["2435","73","פסחים קו, סע\"א. גיטין עז, א. וראה רמב\"ם הל' גירושין פ\"ט הכ\"ג. שו\"ע אה\"ע סקמ\"ג ס\"ו. ובשו\"ע אדה\"ז או\"ח סרצ\"ט ס\"ח: שג' ימים הראשונים של השבוע נקראים ימים שאחר השבת . . אבל ג' ימים האחרונים נקראים ימים שלפני השבת הבאה."],["2436","74","זח\"ב סג, ב. פח, א."],["2437","75","ביצה יז, א."],["2438","76","ראה עד\"ז אוה\"ת וסה\"מ תרכ\"ז שבהע' 9-58, דע\"י העבודה שבששת ימי המעשה נעשה יתרון אור ביום השבת – ע\"ד שע\"י העלאת מ\"ן דהחברייא נעשה יתרון ברשב\"י."],["2439","77","יתרו כ, ח."],["2440","78","שבת קיח, סע\"א."],["2441","79","נסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151246\" data-slug=\"likkutei-sichot\" data-id=\"1300151246\">לקו\"ש חט\"ו ע' 234</a>."],["2442","80","ב\"ר פי\"ז, ד."],["2443","81","שעהיוה\"א רפ\"ז."],["2444","82","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380215\" data-slug=\"likkutei-torah\" data-id=\"4001380215\">לקו\"ת אמור לב, ב</a>, ממק\"מ ר\"פ בראשית."],["2445","83","שבזה מדובר במדרש שם. ועאכו\"כ \"האדון\" (שבפסוק מאן פני האדון) שאינו מז' שמות הקדושים ורק \"כינוי\" שמותר למוחקו (ראה רמב\"ם הל' יסוה\"ת פ\"ו ה\"ה)."],["2446","84","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."],["2447","85","תשא לד, כג. וראה משפטים כג, יז."],["2448","86","חגיגה ב, א. וראה תוד\"ה יראה שם."],["2449","87","תהלים יא, ז."],["2450","88","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת ראה כג, ד</a> ואילך. וראה אוה\"ת וירא קג, ב ואילך."],["2451","89","משפטים שם, טו. רמב\"ם ריש הל' חגיגה."],["2452","90","ראה חגיגה ז, א. אבל ברמב\"ם שם פ\"א ה\"א \"בין מן העוף ובין מן הבהמה\". וראה כס\"מ שם, שלהרמב\"ם היתה גירסא אחרת."],["2453","91","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380443\" data-slug=\"likkutei-torah\" data-id=\"4001380443\">לקו\"ת בהעלותך (לג, ב</a>) שהעופות \"הם למעלה מבחי' בשר בהמה\". וראה מאמרי אדה\"ז ענינים ע' תי. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041294\" data-slug=\"likkutei-sichot\" data-id=\"1300041294\">לקו\"ש ח\"ד ע' 1295</a>."],["2454","92","ראה תוד\"ה נפסל – מנחות כ, ב. ושם: מנהג <i>אבותינו</i> תורה היא. ועד\"ז במהרי\"ל הובא ברמ\"א יו\"ד סשע\"ו ס\"ד. ובמנהגים ישנים מדורא ע' 153: והמנהג תורה היא. וראה ירושלמי פסחים פ\"ד ה\"א."],["2455","93","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071349\" data-slug=\"likkutei-sichot\" data-id=\"1300071349\">לקו\"ש ח\"ז ע' 337</a>."],["2456","94","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור</a> ד\"ה וספרתם וד\"ה והניף את העומר (לה, ב ואילך). ד\"ה והניף את העומר במאמרי אדהאמ\"צ במדבר ח\"ב (ע' תנח ואילך). ד\"ה משכני דש\"פ במדבר ה'תש\"א. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121099\" data-slug=\"likkutei-sichot\" data-id=\"1300121099\">לקו\"ש חי\"ב ע' 99</a> ואילך."],["2457","95","בהתפלה שאומרים אחרי ספה\"ע."],["2458","96","ראה אוה\"ת ענינים ע' קיד ואילך. המשך תרס\"ו ע' קעג ואילך. המשך תער\"ב ח\"א פנ\"ג (ע' צה) ואילך. וראה ספר הערכים-חב\"ד כרך ב ערך אור ס\"ג ואילך (ע' תמא ואילך). <i>וש\"נ</i>."],["2459","97","ראה סידור (עם דא\"ח) שער הסוכות רמח, א-ב. שערי אורה ד\"ה יביאו לבוש מלכות פי\"ב-ג."],["2460","98","סידור (עם דא\"ח) שער הל\"ג בעומר דש, א."],["2461","99","סי' ז\"ך וביאורו וסי' כח."],["2462","100","שם דש, א ואילך."],["2463","101","ראה פע\"ח שער כב (שער ספה\"ע) פ\"ז. מ\"ח מס' אייר וסיון פ\"א מ\"ו. ושם מ\"ז: שמחה גדולה. וראה אגרות-קודש אדמו\"ר הזקן ריש ע' קיז.\nוראה ד\"ה להבין ענין הילולא דרשב\"י בסה\"מ תקס\"ד (ע' קא ואילך, ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940218\" data-slug=\"or-hatorah-hb\" data-id=\"8159940218\">אוה\"ת ענינים ע' ריח</a> ואילך); מאמרי אדהאמ\"צ ויקרא ח\"ב (ע' תרסו ואילך); סה\"מ תרנ\"ד (ע' רסא ואילך), ועוד – בטעם שעושין שמחה ביום ההילולא דרשב\"י אף שנקבע תענית על מיתת צדיקים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071355\" data-slug=\"likkutei-sichot\" data-id=\"1300071355\">לקו\"ש ח\"ז ע' 343</a> בהערה. וש\"נ."],["2464","102","ראה המשך שמח תשמח תרנ\"ז ס\"ע 49 (סה\"מ תרנ\"ז ע' רכד) ואילך. ועוד."],["2465","103","ישעי' לה, י. נא, יא."],["2466","104","אגה\"ק הידועה דהבעש\"ט (נדפסה גם בריש ס' כתר שם טוב הוצאת קה\"ת)."],["2467","105","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091023\" data-slug=\"likkutei-sichot\" data-id=\"1300091023\">לקו\"ש ח\"ט ע' 23</a> הערה 61."]]],[1500380044,"<h3>בס\"ד. ש\"פ אמור, י\"ט אייר, ה'תשל\"ד<sup data-n=\"2468\">*</sup></h3>\n<b>פתח</b> רבי שמעון ואמר אני לדודי ועלי תשוקתו<sup data-n=\"2469\">1</sup>, כל יומין דאתקטרנא בהאי עלמא בחד קטירא אתקטרנא בי' בקוב\"ה ובגין כך השתא ועלי תשוקתו<sup data-n=\"2470\">2</sup>. ובהמשך הענין שם<sup data-n=\"2471\">3</sup>, מסתכל הוינא כל יומא בהאי קרא דכתיב<sup data-n=\"2472\">4</sup> בה' תתהלל נפשי כו' והאידנא אתקיים קרא כולא כו' דהא נשמתי בי' אחידא בי' להיטא בי' אתדבקת כו'. שבמשך כל ימי חייו (כל יומין דאתקטרנא בהאי עלמא) הי' רשב\"י מקושר בהקב\"ה (אתקטרנא הוא לשון קשר, כמו ותקשור על ידו שני וגו'<sup data-n=\"2473\">5</sup> ותרגם וקטרת על ידיה זהוריתא<sup data-n=\"2474\">6</sup>), דהתקשרות היא דוקא בשני דברים, והאידנא, ביום הסתלקותו<sup data-n=\"2475\">7</sup>, הגיע לדרגא נעלית יותר, שנעשה חד עם הקב\"ה, בי' <i>אחידא</i>.\n<b>והנה</b> אף שלהדרגא דבי' אחידא הגיע רשב\"י (רק) ביום הסתלקותו, הרי מכיון <i>שכל ימיו</i> השתדל להגיע לדרגא זו (מסתכל הוינא <i>כל יומא</i> בהאי קרא), מובן, שבכללות שייך לזה והגיע לזה<sup data-n=\"2476\">8</sup> גם בחייו<sup data-n=\"2477\">9</sup>, אלא שהשלימות בזה (קרא <i>כולא</i>) נתקיים בו האידנא, ביום הסתלקותו. וכמובן גם מהמבואר בהמשך תרס\"ו<sup data-n=\"2478\">10</sup> דזה שעסק התורה דרשב\"י הי' באופן דתורתו אומנתו<sup data-n=\"2479\">11</sup>, היינו שעסק התורה שלו היתה באופן דהמשכת מ\"ד<sup data-n=\"2480\">12</sup> (ודלא כשאר התנאים שהלימוד שלהם הי' באופן דהעלאת מ\"ן), הוא הענין ד(בי' אחידא) בי' להיטא, והרי זה שרשב\"י היתה תורתו אומנתו, הי' זהבמשך כל ימי חייו. ויש להוסיף, דזה שבכמה דרושים<sup data-n=\"2481\">13</sup> מובא הענין דנשמתי בי' אחידא כו' בהמשך אחד עם בחד קטירא אתקטרנא, הוא, כי גם בהענין דבחד קטירא אתקטרנא יש בפנימיות בי' אחידא כו', אלא שבמשך כל ימי חייו לא הי' זה (בי' אחידא כו') בגילוי, וביום ההסתלקות שלו, שאז מתגלה הפנימיות (השרש והמקור) של כל עניני עבודת האדם שעבד במשך כל ימי חייו<sup data-n=\"2482\">14</sup>, אז מתגלה הפנימיות דבחד קטירא אתקטרנא<sup data-n=\"2483\">15</sup>, שהוא (לא רק התקשרות, אלא גם) בי' <i>אחידא</i>.\nב) <b>ויובן</b> זה בהקדים הידוע<sup data-n=\"2484\">16</sup> שגם התקשרות היא למעלה מדביקות. דדביקות היא בחיצוניות, כמו כאשר ידבק האזור אל מתני איש<sup data-n=\"2485\">17</sup>, שהדביקות דאזור ל(מתני) האיש היא רק לחיצוניותו, והתקשרות הוא בפנימיות, כמו ונפשו קשורה בנפשו<sup data-n=\"2486\">18</sup> שזה מגיע בפנימיותו<sup data-n=\"2487\">19</sup>. וזהו החילוק בין קרבנות לקטורת, דעבודת הקרבנות היא מצד זה שישראל דבוקים בהקב\"ה [כדאיתא במדרש<sup data-n=\"2488\">20</sup> ובזהר<sup data-n=\"2489\">21</sup>], ולכן היו מקריבים הקרבנות על מזבח החיצון, דבנפש האדם הוא חיצוניות הלב<sup data-n=\"2490\">22</sup>. וקטורת הוא לשון קשר<sup data-n=\"2491\">23</sup> [דכל קשר שבפסוק מתורגם קטר<sup data-n=\"2492\">24</sup>], ולכן הקטורת היא על מזבח הפנימי, דבנפש האדם הוא פנימיות הלב<sup data-n=\"2490\">22</sup>. והחילוק שבין העבודה דחיצוניות הלב להעבודה דפנימיות הלב הוא<sup data-n=\"2493\">25</sup>, שהעבודה דחיצוניות הלב היא ע\"פ טעם ודעת, דבהאהבה שע\"פ טעם ודעת שייך שינויים<sup data-n=\"2494\">26</sup>, והעבודה דפנימיות הלב היא למעלה מטעם ודעת, שאין שייך בה שינוי. וזהו שקרבנות הוא לשון קירוב<sup data-n=\"2495\">27</sup> וקטורת לשון התקשרות, דקירוב מורה שהוא מציאות, אלא שהוא קרוב לאלקות, אבל אפשר שיתרחק ח\"ו, והתקשרות (קטורת) הוא קשר של קיימא, דאמיתית ענין קשר של קיימא הוא שאין שייך בזה שינוי.ג) <b>והנה</b> חילוק זה בין דביקות והתקשרות הוא בהעבודה דמלמטה למעלה<sup data-n=\"2496\">28</sup>. דקרבנות וקטורת שניהם הם עמוד העבודה, שהיא העלאה מלמטה למעלה<sup data-n=\"2497\">29</sup>. והחילוק בין דביקות והתקשרות בענין ההמשכה מלמעלה למטה (תורה וגמ\"ח) הוא כדאיתא בזהר<sup data-n=\"2498\">30</sup> כמה חביבין ישראל קמי קוב\"ה כו' ובעא לאתדבקא בהו ולאתקשרא עמהון, ומבאר אדמו\"ר האמצעי<sup data-n=\"2499\">31</sup> דלאתדבקא בהו הוא ע\"י המצוות, דההמשכה שע\"י המצוות היא בבחינת מקיף<sup data-n=\"2500\">32</sup> כמ\"ש<sup data-n=\"2501\">33</sup> וימינו תחבקני, שהאור שנמשך ע\"י המצוות הוא מחבק את האדם המקיים את המצוות, דחיבוק הוא מבחוץ, ולכן אומר לאתדבקא בהו, דדביקות הוא חיבור חיצוני. ולאתקשרא עמהון הוא ע\"י התורה, דהמשכה שע\"י התורה היא בפנימיות כמ\"ש<sup data-n=\"2502\">34</sup> ותורתך בתוך מעי. ולכן אומר ולאתקשרא עמהון, דהתקשרות הוא חיבור פנימי. שהחיבור דהקב\"ה עם ישראל שע\"י התורה נק' התקשרות, כמאמר<sup data-n=\"2503\">35</sup> תלת קשרין<sup data-n=\"2504\">36</sup> אינון מתקשרן דא בדא, קוב\"ה<sup data-n=\"2505\">37</sup> אורייתא וישראל.\nד) <b>והנה</b> בהדביקות דישראל בהקב\"ה [שמצד זה יש להם הכח להקריב קרבנות] שני ענינים. דבמדרש<sup data-n=\"2506\">38</sup> איתא דזה שהקב\"ה צוה את ישראל להקריב קרבנות הוא מפני שהן דבוקין לי הדא הוא דכתיב&lt;17&gt; כי כאשר ידבק האזור אל מתני איש גו', ובזהר<sup data-n=\"2507\">39</sup> איתא זכאין אינון ישראל דקב\"ה קרא לון אדם כו' אדם כי יקריב מכם<sup data-n=\"2508\">40</sup>, מאי טעמא קרא לון אדם משום דכתיב<sup data-n=\"2509\">41</sup> ואתם הדבקים בהוי' אלקיכם גו'. ומבואר בהמשך תרס\"ו<sup data-n=\"2510\">42</sup>, שבמדרש מדבר בענין הדביקות דכלים, שהכלים הם<sup data-n=\"2511\">43</sup> בבחינתמציאות והיחוד (הדביקות) שלהם אינו יחוד עצמי, ולכן מביא הפסוק כאשר ידבק האזור גו' שהאזור הוא מציאות לעצמו אלא שדבוק להאדם, ובזהר מדבר בענין הדביקות דאורות, שהדביקות והיחוד דאורות הוא יחוד עצמי&lt;43&gt;, ולכן מביא הכתוב ואתם הדבקים בהוי' אלקיכם, דביקות ממש. ויש לומר, דזה שגם הדביקות דאורות נק' בשם דביקות, דדביקות הוא בחיצוניות (כנ\"ל), הוא מפני שגם האור הוא התפשטות וגילוי שמחוץ להעצם.\n<b>וע\"פ</b> הידוע<sup data-n=\"2512\">44</sup> דתורה ומצוות הם (דוגמת) אורות וכלים, יש לומר, שגם החיבור שע\"י עסק התורה (כמו שהתורה היא בבחינת התפשטות וגילוי<sup data-n=\"2513\">45</sup>) הוא בכלל ענין הדביקות<sup data-n=\"2514\">46</sup>, וענין ההתקשרות שע\"י עסק התורה [דישראל <i>מתקשרין</i> באורייתא ואורייתא בקוב\"ה], הוא מצד עצם התורה שלמעלה מהתפשטות וגילוי. ויובן זה ע\"פ הידוע<sup data-n=\"2515\">47</sup> שבההתקשרות דישראל אורייתא וקוב\"ה שני אופנים. שמצד התורה כמו שנמשכה בהשתלשלות, מכיון שהסדר דהשתלשלות הוא <i>שהחיצוניות</i> שבעליון נעשה <i>פנימיות</i> להתחתון, אופן ההתקשרות דישראל באורייתא הוא שהסתים (הפנימיות) דישראל מתקשר בגליא (חיצוניות) דאורייתא, וכמו\"כ הוא בההתקשרות דאורייתא בקוב\"ה, שהסתים והפנימיות דאורייתא מתקשר בגליא דקוב\"ה. ובאופן זה, ההתקשרות של גליא דישראל עם סתים דקוב\"ה היא ע\"י כמה ממוצעים (סתים דישראל, גליא דאורייתא, סתים דאורייתא וגליא דקוב\"ה). אבל מצד עצם התורה, כמו שהיא למעלה מהשתלשלות, ההתקשרות דישראל בקוב\"ה היא שגם הגליא דישראל מתקשר בהסתים דקוב\"ה בלי ממוצעים. וגם כשלומד גליא דתורה בהבנה והשגה שלו הוא מקושר (גם הגליא דנשמתו, עד לההבנה וההשגה שלו) גם עם סתים דאורייתא, ועל ידה – עם סתים דקוב\"ה.\n<b>ויש</b> לומר, שההתקשרות דישראל ואורייתא שמצד דרגת התורה כמו שנמשכה בהשתלשלות, נכללת בענין הדביקות שהיא בחיצוניות. כי ההתקשרות דישראל באורייתא (שמצד דרגא זו) היא בהחיצוניות (גליא) דאורייתא, ויתירה מזו, גם הפנימיות שבבחינה זו היא כמו שנמשכה בהשתלשלות להיות ממוצע. והלשון תלת<i>קשרין</i> אינון <i>מתקשרן</i> דא בדא הוא (בעיקר<sup data-n=\"2516\">48</sup>) בההתקשרות שמצד עצם התורה שלמעלה מהשתלשלות<sup data-n=\"2517\">49</sup>, דהתקשרות זו היא בסתים דאורייתא ובסתים דקוב\"ה, פנימיות.\nה) <b>והנה</b> גם בההתקשרות שמצד עצם התורה, ישראל ואורייתא וכן אורייתא וקוב\"ה הם כמו שני דברים אלא שמתקשרים זה בזה. משא\"כ זה שישראל אורייתא וקוב\"ה כולא חד, הוא למעלה מההתקשרות דישראל אורייתא וקוב\"ה כמו שהיא מצד עצם התורה שלמעלה מהשתלשלות. ויובן זה בהקדים הדיוק במה שאמרו תלת קשרין אינון מתקשרן דא בדא, דלכאורה ישנם רק ב' קשרין, שישראל מתקשרין באורייתא ואורייתא בקוב\"ה. ואחד הביאורים בזה<sup data-n=\"2518\">50</sup>, דקשר השלישי הוא הקשר דישראל וקוב\"ה שלא ע\"י אמצעות התורה, מצד שהשרש דישראל הוא בהעצמות, שלמעלה<sup data-n=\"2519\">51</sup> מהשרש דתורה. והסדר דג' קשרים אלו הם כמו טבעת (עיגול) שאין בו ראש וסוף. שבתחלה ישראל מתקשרין באורייתא ואורייתא בקוב\"ה ולאח\"ז הקשר דקוב\"ה וישראל, דיש לומר שלאחרי שישראל מתקשרין באורייתא ועל ידה בקוב\"ה, מתגלה השרש דישראל שלמעלה מהשרש דתורה, הקשר דישראל וקוב\"ה. ולאחרי שנעשה קשר זה (דישראל וקוב\"ה), אזי בתחלה הוא הקשר דישראל וקוב\"ה, ולאחרי שנתגלה השרש דישראל בעצמותו ית', הם ממשיכים זה גם בתורה, ע\"ד דוד הי' מחבר תורה שלמעלה בקוב\"ה<sup data-n=\"2520\">52</sup>. דנוסף לזה שהתורה היא חכמתו של הקב\"ה, דהחכמה היא באין ערוך לגבי עצמות אוא\"ס וישראל ממשיכים בה עצמות אוא\"ס<sup data-n=\"2521\">53</sup>, הנה כיון שגם בהשרש דתורה וישראל כמו שהם בהעצמות, השרש דישראל הוא למעלה מהשרש דתורה, לכן על ידי עסק התורה דישראל נמשך בה מהעצמות ממש.\n<b>ועפ\"ז</b> יש לומר, דזה שישראל אורייתא וקוב\"ה כולא חד (דלא רק שהם מקושרים זה בזה אלא שהם חד ממש) הוא (בעיקר) בישראל. דבנוגע לתורה, מכיון שהתורה היא בשביל ישראל (דבר אל בנ\"י צו את בנ\"י<sup data-n=\"2522\">54</sup>), היינו שהיא <i>דוגמת</i> אמצעי,היא כמו מציאות דבר שמחובר ומקושר עם הקב\"ה, משא\"כ ישראל שהם מושרשים בהעצמות ממש, זה שישראל מושרשים בהעצמות, אין זה שמושרש בו ענין אחר ח\"ו אלא שזה (השרש דישראל) חד עם העצמות. וע\"י שישראל ממשיכים העצמות בתורה, נעשית גם התורה חד עם העצמות, ישראל אורייתא וקוב\"ה כולא חד, חד ממש.\nו) <b>וע\"פ</b> כל הנ\"ל יש לבאר, דשני הענינים שברשב\"י, בחד קטירא אתקטרנא ובי' אחידא כו', הם שני אופנים בלימוד התורה שלו (עיקר ענינו דרשב\"י, תורתו אומנתו). ויובן ע\"פ הידוע<sup data-n=\"2523\">55</sup> דזה שגם ע\"י לימוד נגלה דתורה נעשה ההתקשרות דישראל בהעצמות דתורה ודקוב\"ה (כנ\"ל סעיף ד), הוא בהעלם, וגילוי העצמות (דתורה ודקוב\"ה) הוא בהעסק דפנימיות התורה. וכיון שהלימוד דרשב\"י הי' באופן שגם בלימוד הנגלה שלו האיר הפנימיות<sup data-n=\"2524\">56</sup>, לכן, ההתקשרות שלו בהעצמות דאורייתא ודקוב\"ה, גם בלימוד הנגלה שלו, היתה בגילוי. וזהו שאמר כל יומין דאתקטרנא בהאי עלמא בחד קטירא אתקטרנא בי' בקוב\"ה, שגם לימוד הנגלה שלו (שבזה הי' רוב לימודו<sup data-n=\"2525\">57</sup>) [ועד\"ז כל עניניו, שהיו חדורים בתורה, מכיון שתורתו אומנתו] היתה באופן דהתקשרות שלמעלה מדביקות, בחד קטירא אתקטרנא. ויתירה מזו, שעי\"ז הגיע גם לקשר השלישי, הקשר דישראל וקוב\"ה שמצד עצם הנשמה כמו שהיא מקושרת עם העצמות. דזהו\"ע <i>בחד</i> קטירא אתקטרנא, דהתקשרות שמצד יחידה<sup data-n=\"2526\">58</sup> (עצם הנשמה) היא למעלה מהתחלקות דשני קוין, וכמבואר במק\"א<sup data-n=\"2527\">59</sup>, דבבחינת היחידה, שניהם הם ענין אחד, <i>חד</i> קטירא. דבהקשר דישראל וקוב\"ה שע\"י אורייתא, כיון שהתורה היא כמו אמצעי ואינה חד ממש עם העצמות, לכן, גם ההתקשרות דישראל וקוב\"ה שע\"י התורה (גם ההתקשרות כמו שהיא מצד עצם התורה שלמעלה מהשתלשלות), היא דוגמת התקשרות דשני דברים המתקשרים, ובמילא, ההתקשרות היא באופן שיש לה רצון לאלקות (מציאות דרצון, שנחלק לשני קוין), <i>ואמיתית</i> הענין דבחד קטירא אתקטרנא, קשר אחד, הוא בקשר דישראל וקוב\"ה (שלמעלה מהקשר שלהם ע\"י אמצעות התורה), מצד זה שהשרש דישראל הוא בהעצמות.\n<b>וע\"פ</b> כל הנ\"ל יש לומר, דזה שרשב\"י הגיע להשלימות דבי' אחידא ביום הסתלקותו דוקא, הוא, כי במשך כל ימי חייו, עיקר ענינו הי' עסק התורה (תורתו אומנתו), ולכן גם בהענין <i>דבחד</i> קטירא אתקטרנא (שמצד עצם הנשמה) הי' נרגש ענין ההתקשרות (דוגמת התקשרות דשני דברים שמתקשרים), וביום הסתלקותו, האיראצלו בגילוי (ובשלימות<sup data-n=\"2528\">60</sup>) הקשר דישראל וקוב\"ה שמצד עצם הנשמה, נשמתי בי' אחידא<sup data-n=\"2529\">61</sup>.\nז) <b>והנה</b> אף שזה דבחד קטירא אתקטרנא, ומכ\"ש זה דבי' אחידא, היא מדריגה נעלית ביותר, מ\"מ, ע\"י שפתח ר\"ש ואמר בחד קטירא אתקטרנא כו', דפירוש \"פתח\" הוא<sup data-n=\"2530\">62</sup> שפתח את הצנור, ניתן הכח לכאו\"א מישראל שיהי' אצלו אפס קצהו ושמץ מנהו<sup data-n=\"2531\">63</sup> דענין זה, שלימוד התורה שלו יהי' באופן דנפשו קשורה להתורה בכל פנימיותו, דהגם שישנם זמנים שמוכרח להפסיק מלימוד התורה<sup data-n=\"2532\">64</sup>, מ\"מ, בעת הלימוד יהי' זה (לימוד התורה) כל מציאותו, ועד שיהי' חד עם התורה ועם נותן התורה, חד ממש<sup data-n=\"2533\">65</sup>. והנתינת כח לזה ביתר שאת היא ע\"י לימוד פנימיות התורה, תורתו של רשב\"י<sup data-n=\"2534\">66</sup>, שעי\"ז ישנו הכח (עוד יותר) להתקשר ולהתאחד עם התורה ונותן התורה. וע\"י הלימוד וההפצה דתורתו של רשב\"י, שבדורותינו אלה נתגלתה בתורת החסידות, מקרבים גם את הגאולה, וכהבטחת מלך המשיח להבעש\"ט<sup data-n=\"2535\">67</sup> דלכשיפוצו מעינותיך חוצה אתי מר דא מלכא משיחא, וכדאיתא בזהר<sup data-n=\"2536\">68</sup> דבהאי חיבורא דילך (דהרשב\"י) כו' יפקון בי' מן גלותא ברחמים.\n**********",[["2468","*","יצא לאור ב<b>קונטרס ל\"ג בעומר – תשמ\"ט</b>, \"לקראת ל\"ג בעומר הבעל\"ט . . <i>מוצש\"ק פ' בהר תשמ\"ט</i>\"."],["2469","1","שה\"ש ז, יא."],["2470","2","זח\"ג (אדר\"ז) רפח, א. וראה ד\"ה אני לדודי ועלי תשוקתו ה'תרצ\"ו (ה'תש\"ח) ס\"ב (סה\"מ ה'תש\"ח ע' 183)."],["2471","3","רצב, א."],["2472","4","תהלים לד, ג."],["2473","5","וישב לח, כח."],["2474","6","סה\"מ ה'תש\"ח שם. וראה לקמן ס\"ב (מאוה\"ת והמשך יונתי שבהערה 24) שכל קשר שבפסוק מתורגם בלשון קטר.\nויש לומר, ד\"זהוריתא\" הוא גם מלשון זהר ואור [וכמובן גם מזה שויקרא שמו זרח על שם <i>זריחת</i> מראה <i>השני</i> (וישב שם, ל ובפרש\"י שם)]. ואולי יש לומר, דזה שמעתיק בסה\"מ ה'תש\"ח שם גם תיבת שני וזהוריתא הוא – כי עיקר הענין דהתקשרות בפנימיות הוא בהאור <i>שכל ענינו</i> הוא שהוא גילוי המאור (ראה לקמן ס\"ד). ואולי יש לומר, דזהו גם הטעם על זה שבאוה\"ת ובהמשך יונתי שבהערה 24 מביא תחלה הפסוק (ואתחנן ו, ח) \"וקשרתם לאות גו'\" <i>ולאח\"ז</i> \"ותקשור על ידו\" (היפך מסדר הפסוקים כמו שהם בתורה) – כי בתחלה מביא התקשרות דלבוש (דתפילין הם לבוש), ולאח\"ז התקשרות נעלית יותר, התקשרות <i>דאור</i>."],["2475","7","ראה זהר שם בתחלת הענין (רפז, ב) \"בההוא יומא דר\"ש בעא לאסתלקא מן עלמא\"."],["2476","8","להעיר ממרז\"ל שבמקום שמחשבתו של אדם שם הוא נמצא (ראה כש\"ט – הוצאת קה\"ת תשמ\"ט – בהוספות סי' מח. וש\"נ)."],["2477","9","שהרי יגעתי ולא מצאתי אל תאמין (מגילה ו, ב)."],["2478","10","ע' מה."],["2479","11","שבת יא, א. טושו\"ע (ודאדה\"ז) או\"ח סו\"ס קו. הל' ת\"ת לאדה\"ז פ\"ד ס\"ד-ה."],["2480","12","ראה המשך תרס\"ו שם <i>שזהו</i> ענין \"תורתו אומנתו\"."],["2481","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380889\" data-slug=\"likkutei-torah\" data-id=\"4001380889\">לקו\"ת תבוא מג, סע\"א</a>. המשך יונתי תר\"ם ע' נו. המשך תרס\"ו שם ס\"ע מד. המשך תער\"ב ח\"א פ' ריב (ע' תל). ובכ\"מ."],["2482","14","סידור – עם דא\"ח – שער הל\"ג בעומר דש, סע\"א ואילך. וראה אגה\"ק סי' ז\"ך (קמז, סע\"א)."],["2483","15","שלכן, גם זה ש\"<i>כל יומין</i> כו' בחד קטירא אתקטרנא\", אמר <i>ביום הסתלקותו</i>. ולהעיר מסידור שם (דש, ריש ע\"ג) \"עלו עם שרש נשמתו כו' למעלה מעלה, וכמו שאמר על עצמו בחד קטירא אתקטרנא\"."],["2484","16","ביאוה\"ז לאדמו\"ר האמצעי תרומה מט, א – הובא בסה\"מ עזר\"ת ע' פו. ובסה\"מ עזר\"ת שם הובא זה לענין \"בחד קטירא אתקטרנא\"."],["2485","17","ירמי' יג, יא."],["2486","18","ויגש מד, ל."],["2487","19","וכמובן מהמשך הכתוב (שם, לא) והי' כראותו כי אין הנער ומת גו'."],["2488","20","ויק\"ר פ\"ב, ד – נעתק לקמן סעיף ד."],["2489","21","ח\"ב פו, א – נעתק לקמן שם."],["2490","22","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו\"ת סוכות עח, ד</a>. סה\"מ עזר\"ת שם. ובכ\"מ. – נסמנו לעיל ח\"א ריש ע' קסה."],["2491","23","בסה\"מ עזר\"ת שם, וכן בהמשך יונתי תר\"ם (ע' נו) ובהמשך תער\"ב שבהערה 25 שהעבודה דקטורת היא כמו \"בחד קטירא אתקטרנא\"."],["2492","24","אוה\"ת תולדות קנב, סע\"א. המשך יונתי תר\"ם ע' נז."],["2493","25","ראה בארוכה המשך תער\"ב שבהערה 13. ד\"ה בסוכות תשבו ה'תשמ\"א ס\"ב (לעיל ח\"א ע' קסד)."],["2494","26","ראה ד\"ה פדה בשלום ה'תשל\"ט ס\"ג (לעיל ח\"ב ע' מ ואילך)."],["2495","27","ראה ד\"ה בסוכות תשבו הנ\"ל שם. וש\"נ."],["2496","28","ראה סה\"מ עזר\"ת ע' פו \"עבודת הקרבנות . . בחי' חיצוניות הלב, אמנם בחי' פנימיות הלב הו\"ע הקטורת שהוא לשון התקשרות, והתקשרות הוא למעלה מדביקות . . וכמ\"ש בביאוה\"ז פ' תרומה\". אבל צ\"ע מהמשך תער\"ב ח\"א פקע\"ה (ע' שנז) דזה שאיתא בביאוה\"ז פ' תרומה שהתקשרות הוא יותר מדביקות \"י\"ל דשם מדבר בדביקות שמצד העליון . . אבל מלמטלמ\"ע הוא בבחי' התאחדות יותר מהתקשרות\"."],["2497","29","להעיר שתפלת מנחה היא כנגד קטורת* – והרי תפלה (גם תפלת מנחה) היא מלמטה למעלה."],["2498","30","ח\"ב פ' תרומה קכו, סע\"א."],["2499","31","בביאוה\"ז שבהערה 16."],["2500","32","שלכן המצוות הם לבושים והתורה מזון – <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>. ובכ\"מ."],["2501","33","שה\"ש ב, ו. שם ח, ג."],["2502","34","תהלים מ, ט. תניא שם."],["2503","35","זח\"ג עג, א."],["2504","36","\"צ\"ע דבזהר פ' אחרי דע\"ג ע\"א לא נא' הל' תלת קשרין כ\"א תלת דרגין אינון דמתקשרין כו'. אמנם בודאי נמצא באיזה מקום בזהר או בתי' בל' תלת קשרין, וכפה\"נ כ\"ק רבינו אדמו\"ר זצוקללה\"ה נ\"ע אמר בכל פעם בל' תלת קשרין כו' שכן נז' הל' בכל הדרושים\" – סה\"מ תרנ\"ז ס\"ע כח."],["2505","37","כ\"ה (קוב\"ה אורייתא וישראל, סדר דמלמעלה למטה) בזהר שם. ובכ\"מ הסדר הוא ישראל אורייתא וקוב\"ה, כדלקמן סוף סעיף ד."],["2506","38","שבהערה 20."],["2507","39","שבהערה 21."],["2508","40","ויקרא א, ב. ובהמשך תרס\"ו שבהערה 42, שדוקא בחינת אדם (שהוא דבוק בהקב\"ה) ביכלתו להקריב קרבן. וצ\"ע ביאור קרבנות של גוים. ואכ\"מ."],["2509","41","ואתחנן ד, ד."],["2510","42","סד\"ה אדם כי יקריב (ס\"ע קצה ואילך)."],["2511","43","ראה ד\"ה הנ\"ל תרס\"ו (ע' קצ). <i>ובכ\"מ</i>.\n*) <i>הגהות מיימוני לרמב\"ם הל' תפלה פ\"ג ה\"ד אות ג</i>.<i> זהר ח\"א רל</i>,<i> א</i>."],["2512","44","קיצורים והערות לתניא פכ\"ג (ע' קה ואילך). המשך תער\"ב ח\"א פקע\"ט (ע' שסו ואילך)."],["2513","45","להעיר מהידוע, שהאור עם היות שענינו הוא גילוי העצם, מ\"מ, בפרט זה שהוא גילוי הוא כמו דבר נוסף על העצם (סה\"מ תרע\"ח ע' צט. קונטרסים ח\"א רח, א)."],["2514","46","בקיצורים והערות לתניא שם ובהמשך תער\"ב שם, ענין זה (שהתורה היא כמו אורות) הוא ביאור על זה שאורייתא וקוב\"ה כולא <i>חד</i> (שלמעלה גם מענין ההתקשרות), אבל אין סתירה מזה למ\"ש בפנים, כי בכללות, ענין ה\"התקשרות\" הוא <i>בכל</i> הדרגות דתורה (כנ\"ל סעיף ג מביאוה\"ז שם, דע\"י המצוות נעשה \"דביקות\", וע\"י התורה \"התקשרות\"), וגם ב\"התקשרות\" שייך הענין \"חד\"*, כמ\"ש בביאוה\"ז שם \"ולאתקשרא עמהון ממש <i>בתכלית היחוד</i>\". אבל בפרטיות, גם בתורה יש שני הענינים ד\"דביקות\" ו\"התקשרות\", כבפנים. וזה ש\"אורייתא וקוב\"ה כולא <i>חד</i>\" הוא למעלה מענין ה\"התקשרות\" דתורה, כדלקמן סעיף ה."],["2515","47","ראה בארוכה מאמרי אדמו\"ר האמצעי דברים ח\"ג ס\"ע תשעח ואילך. המשך תער\"ב ח\"ב פשס\"ד (ע' תשמו ואילך).\n*) <i>ולהעיר</i>,<i> שגם בנוגע לכלים – שבעבודת האדם הו\"ע המצוות, דביקות שלמטה מהתקשרות (ביאוה\"ז שם) – אמרו </i>\"<i>איהו וגרמוהי </i><b>חד</b>\"<i> (תיקוני זהר בהקדמה ג</i>,<i> ב)</i>."],["2516","48","ראה לעיל הערה 46."],["2517","49","להעיר, שלכאורה עיקר ההדגשה והחידוש בהמאמר דתלת קשרין כו' הוא ההתקשרות באופן הב'*. ועפ\"ז יומתק הלשון תלת קשרין אינון מתקשרן (התקשרות שלמעלה מדביקות) – כי עיקר ההדגשה במאמר זה היא ההתקשרות שמצד עצם התורה שלמעלה מהשתלשלות."],["2518","50","ראה גם לקו\"ש חי\"ח ע' 409. ובמאמרי אדמו\"ר האמצעי שם (ע' תשפג) – הביאור דקשר השלישי <i>באופן אחר</i>."],["2519","51","ראה בהנסמן בהערה 54."],["2520","52","ס' הבהיר סנ\"ח (קצו) (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a>. סה\"מ ה'תש\"ה ע' 123. ובכ\"מ). וכ\"ה בזח\"ג רכב, ב. תולעת יעקב (לבעמח\"ס עבודת הקודש) סוד השבת כח, ד. עבודת הקודש חלק העבודה פכ\"ד. מעין החכמה, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380502\" data-slug=\"likkutei-torah\" data-id=\"4001380502\">לקו\"ת שם מז, ג</a>. נא, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650185\" data-slug=\"or-hatorah-hb\" data-id=\"8316650185\">אוה\"ת נ\"ך</a> תהלים כרך ב ס\"ע תתקיד. ובכ\"מ."],["2521","53","סה\"מ ה'תש\"ה שם. ושם, שזהו\"ע דוד מחבר תורה בהקב\"ה."],["2522","54","דזוהי הראי' שישראל קדמו לתורה – ב\"ר (פ\"א, ד) ותדבא\"ר (פי\"ד. וראה לקו\"ש חל\"ד ע' 222 הע' 48), הובא בסה\"מ ה'ש\"ת ע' 61. ה'תש\"ה שם ע' 121. ובכ\"מ.\n*) <i>ראה במאמרי אדמו\"ר האמצעי שם (ע' תשפב-ג)</i>,<i> ובהמשך תער\"ב שם</i>,<i> שבההתקשרות דאופן הא' התורה היא כמו </i>\"<i>ממוצע המפסיק</i>\",<i> ובההתקשרות דאופן הב' היא </i>\"<i>ממוצע המחבר</i>\".<i> – והרי עיקר החידוש בהמאמר </i>\"<i>תלת קשרין</i>\"<i> הוא זה שהתורה היא </i>\"<i>ממוצע המחבר</i>\"."],["2523","55","המשך תער\"ב שבהערה 47."],["2524","56","המשך תער\"ב שם. וראה גם המשך תרס\"ו ע' מה. שם ע' שו. ובכ\"מ."],["2525","57","ראה אגה\"ק סכ\"ו (קמג, א). וראה \"שיעורים בספר התניא\" לאגה\"ק כאן הערה 24. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380196\" data-slug=\"likkutei-torah\" data-id=\"4001380196\">לקו\"ת אחרי כח, א</a>: וכל עסק רשב\"י הי' בנגלה."],["2526","58","ראה גם סידור – עם דא\"ח – קסג, א שענין \"<i>בחד</i> קטירא אתקטרנא\" הוא ההתקשרות שמצד יחידה."],["2527","59","סה\"מ עת\"ר ע' קעז. ושם, שזהו בדוגמת הרצון לחיות, דזה שרוצה לחיות ואינו רוצה למות, הוא חד ממש."],["2528","60","אבל <i>כללות</i> הענין דבי' אחידא הי' אצלו בגילוי גם מקודם, כנ\"ל סעיף א."],["2529","61","וע\"פ מ\"ש בפנים יומתק הלשון \"<i>נשמתי</i> בי' אחידא\", כי הענין דבי' אחידא הוא מצד (שרש) הנשמה שלמעלה מתורה."],["2530","62","ראה סה\"מ תרע\"ח ע' רפג. תרפ\"ח ע' קב. וראה גם בהנסמן לעיל ח\"א ע' רעח הערה 16."],["2531","63","ע\"ד לשון אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, א</a>) בנוגע למשה רבינו."],["2532","64","להעיר, שהדוגמא בש\"ס ופוסקים (נסמן לעיל הערה 11) על \"תורתו אומנתו\" היא <i>מרשב\"י וחבריו</i>."],["2533","65","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה (ט, ב</a>) שע\"י התורה נעשה יחוד נפלא שאין יחוד כמוהו כו'."],["2534","66","ראה סד\"ה להבין ענין הילולא דרשב\"י עטר\"ת (סה\"מ עטר\"ת ע' תכ): ענינו הי' לגלות בחי' פנימיות התורה כו'."],["2535","67","אגרת הקודש המפורסמת דהבעש\"ט, נדפסה גם בריש ס' כתר שם טוב."],["2536","68","ח\"ג קכד, ב (ברע\"מ), ע\"פ הגירסא באגה\"ק רסכ\"ו (קמב, א)."]]]]});
